window.__Q=window.__Q||{};window.__Q["tcm/2/A1"]=[{"q":"可辨为“里邪出表”的项是","o":["脘腹冷痛1周，昨起恶寒发热流清涕","头痛多年，今起口眼歪斜","聚餐后腹痛腹泻3日","发热3天，今日疹出热渐退去","咳喘多日，今起咯血"],"a":3,"e":"里邪出表指病邪由里透达于外，麻疹疹出而身热渐退，是邪有外出之机；脘腹冷痛转为恶寒发热则属表邪入里。"},{"q":"下列哪项不属于心阴虚证的常见症状","o":["心悸","心烦","失眠多梦","口燥咽干","满面通红"],"a":4,"e":"心阴虚以心悸心烦、失眠多梦、口燥咽干、舌红少津为常见表现；满面通红属邪热亢盛之实热象，非阴虚所见。"},{"q":"肝胃郁热多见","o":["口中酸馊","口中泛酸","口甜","口苦","口黏腻"],"a":1,"e":"肝胃郁热则胃气上逆而泛吐酸水，故口中泛酸；口苦属肝胆火旺，口甜属脾胃湿热，口中酸馊为食积。"},{"q":"以下不是一息五至以上的脉象的是","o":["动脉","促脉","数脉","滑脉","疾脉"],"a":3,"e":"数脉一息五至以上，疾脉七至以上，促脉数而时止，动脉数而躁动；滑脉一息四至、往来流利，不属五至以上。"},{"q":"下列何项不是导致便秘的常见原因","o":["热结","阴虚","寒凝","湿热","血虚"],"a":3,"e":"便秘可因热结、寒凝、阴虚、血虚致肠道失润或传导无力；湿热多致便溏不爽、黏滞臭秽，并非便秘常见成因。"},{"q":"肺阴虚证的辨证要点是以阴虚证与下列何项共见","o":["干咳少痰","咳痰清稀","咳嗽少气","咳痰黄稠","咳痰量多"],"a":0,"e":"肺阴虚以阴虚内热与干咳少痰、痰中带血共见，干咳少痰为肺失濡润之征；咳痰清稀属寒饮，黄稠属痰热。"},{"q":"下列除哪项外均属于麻疹的表现","o":["疹色桃红","形似麻粒","先见于耳后发际","按出疹顺序依次消退","细小稀疏"],"a":4,"e":"麻疹疹色桃红、形似麻粒、先见于耳后发际，出齐后按顺序依次消退；细小稀疏为风疹的特点。"},{"q":"望色十法中的“抟”是","o":["浅淡","疏离","壅滞","暗浊","浮露"],"a":2,"e":"望色十法中抟指色泽壅滞不解，主病邪由浅入深、气血壅聚；浅淡为微，疏离为散，暗浊为甚。"},{"q":"不属于青色主病的是","o":["寒证","气滞","疼痛","惊风","血虚"],"a":4,"e":"青色主寒证、痛证、气滞、血瘀与惊风；血虚无以充养，面色多淡白，不属青色主病。，青色亦见于阴寒内盛之腹痛。"},{"q":"下列哪项不属表证的表现","o":["恶寒发热","鼻塞喷嚏","脉浮苔薄","咳吐黄痰","头身疼痛"],"a":3,"e":"表证以恶寒发热、鼻塞喷嚏、头身疼痛、脉浮苔薄为特点；咳吐黄痰为邪已入里、痰热蕴肺之象。"},{"q":"下列哪项不是阳水证的临床表现","o":["起病急，病程短","水肿先从头面肿起","上半身肿甚","水肿皮薄光亮","肢冷，腰酸痛"],"a":4,"e":"阳水起病急、病程短，肿从头面先起、上半身肿甚、皮薄光亮；肢冷腰酸痛属阴水，为脾肾阳虚水泛。"},{"q":"以寒热往来，胁肋灼痛，大便不调，小便短赤，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝血虚证"],"a":1,"e":"寒热往来、胁肋灼痛、大便不调、小便短赤、舌红苔黄腻、脉弦滑数，为湿热蕴结肝胆、疏泄失职之候。"},{"q":"肾气不固证的临床特征，不包括","o":["月经淋漓不尽","男子滑精早泄","小便余沥不尽","男子精少不育","女子胎动易滑"],"a":3,"e":"肾气不固以膀胱失约、精关不固、胎元不固为特征，见尿后余沥、滑精早泄、月经淋漓、胎动易滑；精少不育属肾精不足。"},{"q":"主肾虚、寒证、水饮、血瘀、疼痛的是","o":["白色","黄色","黑色","青色","红色"],"a":2,"e":"黑色主肾虚、寒证、水饮与血瘀，缘肾阳虚衰、水寒不化、血行瘀滞而见面色黧黑。，故望色见黑当先辨其寒热虚实。"},{"q":"火淫证的临床表现有","o":["发热恶寒","斑疹","头胀痛","渴不多饮","脉细数"],"a":1,"e":"火淫证见壮热面赤、口渴汗多、舌红脉数，热迫血分则肌肤发斑疹；发热恶寒属表证，渴不多饮属湿热。"},{"q":"面色黄而枯槁无光是","o":["萎黄","黄胖","阳黄","阴黄","虚黄"],"a":0,"e":"萎黄指面色淡黄而枯槁无华，因脾胃气虚、气血不足；黄胖为黄而虚浮，阳黄阴黄必伴目黄身黄。"},{"q":"下列叙述中，正确的一项是","o":["脉来一息七至以上为数脉","动脉与代脉均可由情志刺激引起","浮大无根，应指散漫的脉主诸虚劳损","弱脉是举之无力，按之空虚的脉","细脉必为虚脉"],"a":1,"e":"动脉与代脉均可因七情惊恐而致，气机逆乱则脉动躁数或脉气不相接续；数脉为五至以上而非七至，散脉主元气离散。"},{"q":"苔黑而滑润者多属","o":["阴虚阳亢","饮食停滞","瘀血内停","寒湿内阻","湿热内蕴"],"a":3,"e":"苔黑而滑润为阳虚寒盛、寒湿内阻，水湿不化而上泛；若黑而燥裂则属热极津枯，二者寒热相反。"},{"q":"伤寒证的临床表现有","o":["腹冷痛","肠鸣腹泻","恶寒发热","恶风汗出","脉沉紧"],"a":2,"e":"伤寒为寒邪束表、卫阳被遏，见恶寒发热、无汗、头身疼痛、脉浮紧；恶风汗出为太阳中风，脉沉紧主里寒。"},{"q":"循衣摸床、撮空理线的表现属于","o":["少神","神乱","失神","假神","得神"],"a":2,"e":"循衣摸床、撮空理线为神志昏迷、动作失常，属邪盛正衰、失神之危候，提示脏腑精气将竭。"},{"q":"舌体局部出现青紫色斑点，大小不等，不高于舌面，为","o":["紫红舌","紫黑舌","绛紫舌","淡青紫舌","瘀斑舌、瘀点舌"],"a":4,"e":"舌面出现青紫色斑点、大小不等而不高出舌面者，为瘀斑舌、瘀点舌，主血瘀；紫红舌为全舌色紫。"},{"q":"辨别虚实真假的关键是","o":["脉沉取之有力无力","舌质的红与白","病情的轻重程度","病人体质的强弱","腹痛喜冷或喜暖"],"a":0,"e":"辨别虚实真假以脉之沉取有力无力为关键，举之虽盛而沉取空瘪者为假实，沉取有力者方为真实。"},{"q":"皮肤变红，如染脂涂丹，称为","o":["漆疮","丹毒","类丹毒","痈","膏药风"],"a":1,"e":"皮肤焮红成片、色如涂丹、边缘清楚者为丹毒，因火邪侵淫、血分热盛；漆疮则有接触油漆史。"},{"q":"肾气竭绝可出现","o":["弹石脉","雀啄脉","虾游脉","屋漏脉","釜沸脉"],"a":0,"e":"七怪脉中弹石脉按之坚搏如弹石，为肾气竭绝；雀啄、屋漏主脾胃之气将绝，二者不可混同。"},{"q":"戴阳证的面色为","o":["颧颊嫩红如妆","满面通红","两颧潮红","面色青紫","面色苍白"],"a":0,"e":"戴阳证为虚阳浮越于上，面色苍白而两颧嫩红如妆、游移不定；满面通红属实热，两颧潮红属阴虚。"},{"q":"燥淫证易发生于","o":["春季","夏季","长夏","秋季","冬季"],"a":3,"e":"燥为秋季主气，燥邪伤人自口鼻而入，故燥淫证多发于秋季，见口鼻干燥、干咳少痰、皮肤干燥。"},{"q":"除哪项外，均可引起舌颤动","o":["阴液耗损","阳衰阴盛","气血虚衰","热极动风","肝阳化风"],"a":1,"e":"舌颤动多因阴液耗损、气血虚衰、热极动风或肝阳化风，舌失濡养、筋脉拘急而抖；阳衰阴盛多见舌淡胖嫩。"},{"q":"舌苔薄白而润，一般不会见于","o":["正常舌象","表证初起","里证病轻","阳虚内寒","阴虚火旺"],"a":4,"e":"薄白而润为正常舌苔，亦见于表证初起、里证病轻与阳虚内寒；阴虚火旺则舌红少苔或无苔。"},{"q":"脉象细软，浮取可得，重按不显者是","o":["虚脉","细脉","濡脉","微脉","散脉"],"a":2,"e":"濡脉浮细而软、重按不显，主诸虚与湿困；虚脉举按皆无力，微脉极细极软、若有若无。，三者皆属虚类脉而主病有别。"},{"q":"自汗、盗汗并见与下列哪项有关","o":["阴虚证","血虚证","阳虚证","气阴两虚证","血瘀证"],"a":3,"e":"自汗属气虚、盗汗属阴虚，二者并见提示气阴两虚，卫外不固与阴不敛阳同时存在。，治当益气养阴兼顾。"},{"q":"胃脘冷痛喜按，泛吐清水，恶食生冷，倦怠乏力，舌质淡嫩，脉沉迟无力，证属","o":["胃阳虚证","脾肾阳虚证","寒滞胃脘证","肝胃不和证","肝郁脾虚证"],"a":0,"e":"胃脘冷痛喜按、泛吐清水、恶食生冷，为胃阳不足、寒从内生，兼倦怠乏力、舌淡嫩、脉沉迟无力，证属胃阳虚。"},{"q":"肾气不固所致的小便改变为","o":["小便频数而色黄","小便频数而色清","小便频数而色赤","小便频数而混浊","小便频数而涩痛"],"a":1,"e":"肾气不固则膀胱失约，小便频数而色清，甚则余沥失禁；色黄赤者属热，涩痛者属淋证。，与湿热下注之尿赤涩痛不同。"},{"q":"皮肤黄中显黑，黑而晦暗，称","o":["肾虚","萎黄","苍黄","黑疸","失荣"],"a":3,"e":"皮肤黄中显黑、黑而晦暗者为黑疸，由黄疸日久、肝肾亏虚、瘀血内停所致；萎黄为淡黄而枯槁。"},{"q":"多食易饥，大便溏泄是","o":["食积不化","脾胃虚弱","肝脾不和","胃火亢盛","胃强脾弱"],"a":4,"e":"多食易饥为胃热消谷，大便溏泄为脾失健运，二者并见即胃强脾弱。，即胃热而脾虚之候。"},{"q":"下述哪项不是引起气滞证的常见原因","o":["情志不畅","用力闪挫","病邪阻滞","阴血亏虚","阳虚寒凝"],"a":3,"e":"气滞多因情志不畅、用力闪挫、病邪阻滞及阳虚寒凝致气机不畅；阴血亏虚属虚证，非气滞常见成因。"},{"q":"卫气营血辨证是哪位医家创立的","o":["吴鞠通","叶天士","陈平伯","薛生白","吴又可"],"a":1,"e":"卫气营血辨证由叶天士创立，用于外感温热病的辨证；吴鞠通创三焦辨证，吴又可主戾气致病说。"},{"q":"目部分属五脏中，两眦血络属","o":["肝","脾","心","肺","肾"],"a":2,"e":"五轮学说中两眦血络属心，为血轮；黑睛属肝，白睛属肺，瞳神属肾，胞睑属脾。，胞睑红肿多责之脾胃。"},{"q":"肝经风热上攻，多见哪种目色异常改变","o":["白睛色红","两眦红肿赤痛","睑缘赤烂","全目赤肿","黑睛赤肿"],"a":3,"e":"肝经风热上攻则全目赤肿疼痛；白睛红赤属肺火，两眦赤痛属心火，睑缘赤烂属脾经湿热。"},{"q":"不属于外伤病因的是","o":["寄生虫","跌仆损伤","冻伤","烫伤","溺水"],"a":0,"e":"外伤指跌仆坠落、烫伤、冻伤、溺水及虫兽伤等外力损伤；寄生虫属虫积病因，不属外伤范畴。"},{"q":"脉来缓而时一止，止无定数的脉象是","o":["代脉","促脉","涩脉","结脉","散脉"],"a":3,"e":"结脉脉来缓而时有一止、止无定数，主阴盛气结、寒痰血瘀；代脉则止有定数，促脉数而时止。"},{"q":"温病热入营分“口干反不甚渴”的机理是","o":["津液耗伤不甚","津液逐渐恢复","热蒸营阴上潮","邪热迫血妄行","邪热逐渐衰退"],"a":2,"e":"热入营分，邪热蒸腾营阴上潮于口，故口干而反不甚渴，与津液大伤之口渴大异。，为营热蒸腾而非津伤之大渴。"},{"q":"继入院记录之后，对患者病情和诊疗过程所进行的连续性记录。内容包括患者的病情变化情况、重要的辅助检查结果及临床意义、上级医师查房意见、会诊意见、医师分析讨论意见、所采取的诊疗措施及效果、医嘱更改及理由、向患者及其近亲属告知的重要事项等。记录书写以上内容的是","o":["门诊病历初诊记录","门诊病历复诊记录","住院病历初诊记录","住院病历复诊记录","病程记录"],"a":4,"e":"病程记录为继入院记录之后，对病情变化、辅助检查结果、上级医师查房及会诊意见、诊疗措施与效果所作的连续记录。"},{"q":"下列各项，不属头晕常见原因的是","o":["气血两虚","痰湿内阻","肺阴不足","肝阳上亢","肝火上炎"],"a":2,"e":"头晕多因气血两虚、痰湿内阻、肝阳上亢、肝火上炎及肾精不足；肺阴不足以干咳少痰为主，不致眩晕。"},{"q":"腹痛作泻，泻后痛减，或大便时干时稀排便不爽，此证属于","o":["肝郁脾虚","肾阳虚","脾阳虚","湿热","食积"],"a":0,"e":"腹痛作泻、泻后痛减、大便时干时稀而排便不爽，为肝郁乘脾、脾失健运之征，属肝郁脾虚。"},{"q":"以视力减退，肢麻震颤，关节拘急，月经量少、色淡，甚则闭经，面白，舌淡，脉细为主要表现的证是","o":["肝阴虚证","肝阳上亢证","肝气郁结证","肝血虚证","血虚生风证"],"a":4,"e":"视力减退、肢麻震颤、关节拘急、经少色淡、面白舌淡脉细，为肝血亏虚、筋脉失养而风动，属血虚生风证。"},{"q":"外感秽浊不正之气，热毒内盛的舌象是","o":["白腻苔","黄腻苔","灰黑苔","腐苔","积粉苔"],"a":4,"e":"积粉苔苔白如积粉、扪之不燥，为秽浊湿邪与热毒相结，多见于温疫初起。，为温疫初起之典型舌象。"},{"q":"夜卧不安，伴见脘闷腹胀，嗳气酸馊，舌苔厚腻者，属于","o":["心脾两虚","肝胃不和","脾胃气虚","胆郁痰扰","食积胃脘"],"a":4,"e":"夜卧不安伴脘闷腹胀、嗳气酸馊、舌苔厚腻，为食滞胃脘、胃气不和，即胃不和则卧不安。"},{"q":"下列哪项不是假神之征","o":["形体消瘦","真寒假热证","目光晦滞，浮光外露","食量突然增加","突然精神转佳"],"a":0,"e":"假神见于久病重病之人突然精神转佳、言语不休、食量突增、颧红如妆，为精气衰竭、虚阳外越；形体消瘦属失神之象。"},{"q":"血虚证必有的特征性表现是","o":["心悸失眠","经少经闭","肢体麻木","头晕眼花","颜色淡白"],"a":4,"e":"血虚证以面唇舌甲颜色淡白为必有表现，因血液亏少不能充养；心悸、肢麻、经少为常见兼症。"},{"q":"举之浮大中空，如按葱管，为","o":["濡脉","芤脉","革脉","散脉","洪脉"],"a":1,"e":"芤脉浮大中空、如按葱管，主失血伤阴；革脉则浮而搏指、中空外坚如按鼓皮。，两脉皆中空而脉位有浮沉之别。"},{"q":"花剥苔多见于","o":["脾虚伤食","湿遏热郁","痰浊未化","胃气阴两伤","脾胃阳虚"],"a":3,"e":"花剥苔为舌苔剥落不全、剥处光滑，属胃之气阴两伤；镜面舌则示胃阴枯竭。，剥处不复生苔者病情较重。"},{"q":"心脾两虚是指","o":["心脾气血虚","心脾气阴虚","心脾阴阳虚","心脾阳气虚","心脾阴血虚"],"a":0,"e":"心脾两虚即心脾气血两虚，因思虑劳倦伤脾、气血化源不足、心神失养，见心悸失眠、食少便溏。"},{"q":"虚热证区别于实热证的典型特点有","o":["颧红盗汗","大便干结","小便短黄","舌红","脉数"],"a":0,"e":"虚热证以颧红盗汗、五心烦热、舌红少苔、脉细数为特点；大便干结、小便短黄、脉数为虚实热共有。"},{"q":"热渐盛而津渐伤的舌象是","o":["舌苔由白转黄","舌苔由厚变薄","舌苔由润变燥","舌光无苔","舌苔黑而燥裂"],"a":2,"e":"舌苔由润转燥，示热邪渐盛而津液渐伤；苔由白转黄则为邪由表入里化热。，润燥变化可测津液之盛衰。"},{"q":"身热不扬，汗出热不解，见于下列何证","o":["脾气虚证","脾阳虚证","脾虚气陷证","寒湿困脾证","湿热蕴脾证"],"a":4,"e":"身热不扬、汗出热不解、苔黄腻，为湿热蕴脾、湿遏热伏之象；寒湿困脾则苔白腻而热象不显。"},{"q":"积粉苔多见于","o":["秽浊湿邪与热毒相结","燥热伤津","痰饮内停","湿浊中阻，津气不化","外感寒湿"],"a":0,"e":"积粉苔由秽浊湿邪与热毒相结、苔垢堆积而成，苔白如积粉而不燥，多见于温疫初起。，与白腻苔之寒湿不同。"},{"q":"疮疡漫肿无头，肤色晦黯，局部麻木，不热少痛为","o":["痈","疽","疔","疖","丹毒"],"a":1,"e":"疮疡漫肿无头、肤色晦黯、局部麻木、不热少痛者为疽，属阴证；痈则红肿热痛、界限清楚。"},{"q":"虚脉的脉象特征是","o":["脉细如线，软弱无力","极细极软，若有若无","沉细而软，应指无力","三部脉举之均无力，按之空虚","浮细而软，应指无力"],"a":3,"e":"虚脉三部举之无力、按之空虚，主气血两虚；濡脉浮细而软，微脉极细极软，三者脉力不同。"},{"q":"主元气离散，脏腑之气将绝的脉象是","o":["弱脉","散脉","虚脉","微脉","细脉"],"a":1,"e":"散脉浮大无根、应指散漫、至数不齐，主元气离散、脏腑之气将绝。，属脉无根蒂之危候。"},{"q":"下列除哪项外，均为疹的临床表现","o":["色红","点小如粟","压之不退色","高出皮肤","抚之碍手"],"a":2,"e":"疹色红、点小如粟、高出皮肤、抚之碍手，压之退色；压之不退色为斑的特征。，故以压之是否退色相鉴别。"},{"q":"下列哪项不是寒证与热证的鉴别要点","o":["脉迟与脉数","尿清长与尿短黄","口渴与不渴","头痛与不痛","苔黄与苔白"],"a":3,"e":"寒热鉴别重在口渴与否、尿清长与短黄、苔白与苔黄、脉迟与脉数；头痛有无与寒热属性无关。"},{"q":"以下不属于浮脉类的是","o":["浮脉","濡脉","洪脉","长脉","芤脉"],"a":3,"e":"浮脉类包括浮、洪、濡、散、芤、革，均以轻取即得为共同点；长脉属长脉类，主气机有余。"},{"q":"脾有湿热可出现","o":["睑缘赤烂","全目赤肿","目眦淡红","目窠浮肿","白睛红赤"],"a":0,"e":"胞睑属脾，脾经湿热上蒸则睑缘赤烂；全目赤肿属肝经风热，目眦淡白属血虚。，目色异常当分脏腑归经。"},{"q":"区别病邪性质的主要依据是","o":["舌体的颜色","舌苔的厚薄","舌体的动态","舌苔的颜色","舌下络脉"],"a":3,"e":"舌苔颜色是辨别病邪性质的主要依据，苔白多主寒、苔黄多主热；苔之厚薄主要反映邪之深浅。"},{"q":"舌中部所候的脏腑一般是","o":["脾胃","肝胆","心肺","肾","三焦"],"a":0,"e":"舌面分候脏腑，舌尖候心肺，舌中候脾胃，舌边候肝胆，舌根候肾，故舌中部候脾胃。，分部诊察可定病位。"},{"q":"胸背彻痛剧烈，主要是由于","o":["痰浊阻肺","痰热蕴肺","心血不足","心脉闭塞","心阳亏虚"],"a":3,"e":"胸背彻痛剧烈、痛如针刺并见面唇青紫者，为心脉闭塞、瘀血阻络之胸痹心痛。，其痛势剧烈而彻背。"},{"q":"满面通红者多属于","o":["阴虚阳亢","真寒假热","实热证","戴阳证","虚热证"],"a":2,"e":"满面通红属实证热证，因邪热亢盛、血行加速、脉络充盈；两颧潮红属阴虚，颧红如妆属戴阳。"},{"q":"泻下黄臭秽稀便，排便不爽者，其病机是","o":["暑热内蕴","脾气虚弱","湿热","肝郁脾虚","肺热移肠"],"a":2,"e":"泻下黄臭稀便、排便不爽、肛门灼热，为湿热蕴结大肠、传导失常；脾虚则泻下清稀、完谷不化。"},{"q":"肝经风火上扰不会导致","o":["目痒","目痛","雀盲","目眩","目赤"],"a":2,"e":"雀盲为肝血不足、目失濡养所致，入夜视物不清；肝经风火上扰则目赤、目痛、目痒、目眩。"},{"q":"中医诊断学的基本原理与近代控制论的“黑箱”理论相似之处的是","o":["以常衡变","见微知著","司外揣内","四诊合参","整体审察"],"a":2,"e":"司外揣内即通过观察外在征象推测内在脏腑病变，与黑箱理论由输出推断内部结构相类似。"},{"q":"按痰饮停积的部位分类，饮留胃肠的是","o":["痰饮","支饮","溢饮","悬饮","伏饮"],"a":0,"e":"饮留胃肠者为痰饮，饮停胸胁为悬饮，饮溢四肢为溢饮，饮停胸肺为支饮。，四饮以停积部位而分。"},{"q":"苔黑燥裂，甚则生芒刺，多为","o":["热入营血","热极津枯","肾阴亏虚","寒极","湿热"],"a":1,"e":"苔黑燥裂、甚则生芒刺，为邪热炽盛、热极津枯之象；苔黑滑润则属寒湿内盛。，二者寒热属性迥异。"},{"q":"脉体宽大，充实有力，状若波涛汹涌，来盛去衰，是","o":["浮脉","散脉","实脉","大脉","洪脉"],"a":4,"e":"洪脉脉体宽大、充实有力、状若波涛、来盛去衰，主气分热盛；实脉则举按皆有力。，与洪大而无波澜者不同。"},{"q":"口气酸臭，多属","o":["疮疡溃腐","食积胃肠","口腔不洁","脏腑败坏","湿热久蕴"],"a":1,"e":"口气酸臭多因食积胃肠、腐浊之气上逆；口气腐臭属疮疡溃腐，口气臭秽属胃热。，当结合舌脉辨其虚实。"},{"q":"胃气虚证与脾气虚证的鉴别，最有意义的症状是","o":["是否面色萎黄","有无少气懒言","有无神疲肢倦","是否大便稀溏","是否舌淡脉弱"],"a":3,"e":"胃气虚与脾气虚均见食少、舌淡脉弱，而大便稀溏为脾失运化之征，是二者鉴别最有意义的症状。"},{"q":"下列哪项不属于黑色的主病","o":["肾虚","寒证","水饮","血瘀","失血"],"a":4,"e":"失血多见面色淡白或㿠白，不属黑色主病；黑色主肾虚、寒证、水饮与血瘀。，故黑色多主里、主寒、主瘀。"},{"q":"小腿青筋暴露，久立后更明显，多因","o":["寒湿久留","寒湿内侵、瘀血阻络","气血亏虚","痰瘀阻络","风湿久蕴"],"a":1,"e":"小腿青筋暴露、久立后加重，为寒湿内侵、瘀血阻络，血行不畅而脉络迂曲。，多见于久立久行者。"},{"q":"口苦而黏腻多属","o":["伤食","肝胆火旺","肝胆湿热","脾胃湿热","肝胃不和"],"a":2,"e":"口苦属胆热上溢，黏腻属湿浊内蕴，口苦而黏腻即肝胆湿热之候。，湿与热合故黏腻不爽。"},{"q":"小便混浊如米泔，见于下列何证","o":["脾气虚证","脾阳虚证","脾不统血证","脾虚气陷证","寒湿困脾证"],"a":3,"e":"小便混浊如米泔，为脾虚气陷、清浊不分、精微下注所致，故属脾虚气陷证。，与湿热淋证之尿浊不同。"},{"q":"齿痕舌常与下列哪种舌象并见","o":["胖大舌","瘦薄舌","裂纹舌","芒刺舌","歪斜舌"],"a":0,"e":"齿痕舌常与胖大舌并见，因脾虚水湿不运、舌体胖嫩而受齿列挤压成痕。，舌淡胖嫩、苔白滑为常伴之象。"},{"q":"下列各项，属于“症状”的是","o":["心烦失眠","喉中痰鸣","腹如舟状","脉细无力","舌苔薄黄"],"a":0,"e":"症状为患者自身感到的痛苦与不适，心烦失眠属之；喉中痰鸣、腹如舟状、脉象舌象均属体征。"},{"q":"下列各项，属于脾气虚证与脾阳虚证的鉴别要点的是","o":["形寒肢冷","食少纳呆","腹胀便溏","肢倦懒言","舌淡苔白"],"a":0,"e":"脾阳虚在脾气虚基础上兼见形寒肢冷、腹痛喜温喜按，故形寒肢冷为二者鉴别的关键。，食少腹胀便溏为二者共有。"},{"q":"突发片状脱发，显露圆形或椭圆形的光亮头皮而无自觉症状，称为斑秃，多为","o":["精血不足","血虚受风","血热化燥","劳神伤血","疳积"],"a":1,"e":"斑秃为突发片状脱发、头皮光亮而无自觉症状，多因血虚受风、发失所养；发黄干枯易落属精血不足。"},{"q":"语声重浊多为","o":["外感风燥","外感风寒","外感风热","寒邪客肺","热邪壅盛"],"a":1,"e":"语声重浊为外感风寒、肺气不宣、鼻窍不利所致；风热犯肺则语声高亢而浊。，闻诊可辨外邪之寒热。"},{"q":"属于舌象生理变异的是","o":["光线影响","年龄因素","染苔","喝牛奶","长期服用某些抗生素"],"a":1,"e":"年龄因素属舌象生理变异，小儿舌质淡嫩、老人舌色较暗；光线、染苔、服药均属外界干扰。"},{"q":"釜沸脉的脉象是","o":["短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","脉来乍疏乍密，如解乱绳状","急促坚硬如弹石","如屋漏残滴，良久一滴"],"a":1,"e":"釜沸脉如釜中沸水、浮泛无根、至数不清，主三阳热极、阴液枯竭。，属七怪脉中阴竭阳越之危候。"},{"q":"下列哪项不是面色白的主病","o":["虚寒","气血不足","失血","热证","阳气虚弱"],"a":3,"e":"面色白主虚寒、气血不足、失血与阳气虚弱；热证多见满面通红，故不属白色主病。，故白色主虚、主寒。"},{"q":"虫积肠道证所致饮食异常最易表现为","o":["嗜食异物","多食易饥","饥不欲食","偏食酸辣","厌食油腻"],"a":0,"e":"虫积肠道、耗伤水谷精微，脾胃运化失常，故嗜食异物如泥土、生米之类。，虫积日久可见面黄肌瘦。"},{"q":"下列哪项不见消谷善饥","o":["胃火亢盛","胃阴不足","胃强脾弱","消渴","瘿病"],"a":1,"e":"消谷善饥由胃火亢盛、腐熟太过所致，见于胃火亢盛、胃强脾弱、消渴与瘿病；胃阴不足则饥不欲食。"},{"q":"濡脉与弱脉的不同点主要表现在","o":["脉位","脉力","脉宽","脉长","脉律"],"a":0,"e":"濡脉浮细而软，弱脉沉细而软，二者脉力脉形相近，区别在于脉位一浮一沉。，浮沉之分即其鉴别要点。"},{"q":"判断胃气渐复可见","o":["舌苔剥落部位时时转移","舌苔从全到剥","舌苔剥落后复生薄白之苔","剥落处全无舌苔","未剥落处似有腻苔或滑苔"],"a":2,"e":"舌苔剥落后复生薄白之苔，示胃气渐复、预后较好；苔从全到剥或剥处无苔则为胃气渐衰。"},{"q":"脘腹痞闷，腹痛便溏，纳呆口腻，头身困重，苔白腻，脉濡缓，证属","o":["湿热蕴脾证","饮停胃肠证","脾阳虚证","寒湿困脾证","肝胃不和证"],"a":3,"e":"脘腹痞闷、腹痛便溏、纳呆口腻、头身困重、苔白腻、脉濡缓，为寒湿内盛、困阻脾阳之候。"},{"q":"由于气候影响，平脉在冬天可见","o":["浮","沉","洪","弦","迟"],"a":1,"e":"平脉随四时变动，春弦、夏洪、秋浮、冬沉，冬季阳气潜藏、脉气下沉，故平脉在冬天见沉。"},{"q":"舌红绛，苔少而干，多见于","o":["寒邪直中","痰饮内停","湿热困脾","营血热盛","瘀血内停"],"a":3,"e":"舌红绛、苔少而干，为热入营血、营阴耗伤之象；舌绛紫而润多属瘀血内停。，热灼营阴故苔少而干。"},{"q":"巅顶痛属","o":["太阳经头痛","阳明经头痛","少阳经头痛","少阴经头痛","厥阴经头痛"],"a":4,"e":"巅顶为足厥阴肝经所过，故巅顶痛属厥阴经头痛；前额属阳明，两侧属少阳，后枕属太阳。"},{"q":"短脉的主病是","o":["虚证","实证","气病","血病","寒证"],"a":2,"e":"短脉首尾俱短、不及本位，主气病；短而有力为气郁，短而无力为气虚。，气郁者多实，气虚者多虚。"},{"q":"下列何项不属对婴儿问诊的内容","o":["喂养的方法","预防接种情况","胸腹有无胀痛","坐爬立走的时间","出牙学语的迟早"],"a":2,"e":"婴儿不能自述，问诊靠家长代述喂养方法、预防接种及坐爬立走、出牙学语等生长发育情况；胸腹有无胀痛须患者自述，非婴儿问诊内容。"},{"q":"舌痿软而淡白无华者，多属于","o":["热极伤阴","气血俱虚","阴虚火旺","肝肾阴虚","风痰阻滞"],"a":1,"e":"舌痿软而淡白无华，为气血俱虚、舌失充养；舌红绛而痿软则属热极伤阴。，痿软之因当分虚实。"},{"q":"气滞证的特征表现是","o":["头昏眼花","胀满疼痛","绞痛","脘腹坠胀","手足发麻"],"a":1,"e":"气滞证以胀满疼痛、部位不定、时轻时重为特征，因气机郁滞、不通则痛。，其痛走窜而不固定。"},{"q":"发黄干枯，稀疏易落，多为","o":["精血不足","血虚受风","气血亏虚","先天不足","疳积"],"a":0,"e":"头发干枯发黄、稀疏易落，为精血不足、发失濡养；突然片状脱落属血虚受风。，精血充足则发润而黑。"},{"q":"辨别寒热真假的重要依据是","o":["脉象沉取的有力与无力","满面通红与颧浮红如妆","语声的洪亮与低怯","舌质的苍老与娇嫩","胀痛是否拒按"],"a":1,"e":"辨别寒热真假以面色为要，满面通红属实热，颧红如妆、游移不定属真寒假热。，假热之赤色浮嫩而不耐久按。"},{"q":"心气虚的面色表现为下列哪项","o":["面色淡白","面色㿠白","面色萎黄","面色青紫","面色黧黑"],"a":0,"e":"心气虚则推动无力、气血不充，面色淡白；面色㿠白多属阳虚水泛，萎黄属脾虚。，心阳虚则面色㿠白而虚浮。"},{"q":"对里证的描述不正确的是","o":["多见于内伤杂病之中","外感病无里证","外邪可直中脏腑","情志致病发即里证","厥阴病证"],"a":1,"e":"里证可由外邪入里、外邪直中脏腑、情志内伤及脏腑失调所致，外感病发展过程中亦可出现里证，故“外感病无里证”之说错误。"},{"q":"不属于佝偻病患儿常见表现的是","o":["方颅","鸡胸","肋如串珠","梭状指","项软"],"a":3,"e":"佝偻病患儿可见方颅、鸡胸、肋如串珠、项软等骨骼改变；梭状指见于先天性发绀型心脏病。"},{"q":"脉来缓而时止，止无定数，为","o":["代脉","促脉","涩脉","结脉","濡脉"],"a":3,"e":"结脉脉来缓慢而时有一止、止无定数，主阴盛气结、寒痰血瘀；代脉则止有定数。，结与代以止之有无定数相区别。"},{"q":"以下哪项不属脉体宽大的脉象","o":["洪脉","大脉","芤脉","革脉","牢脉"],"a":3,"e":"洪、大、芤脉均脉体宽大；革脉浮而搏指、中空外坚如按鼓皮，以中空为特点，不属宽大之列。"},{"q":"举之无力，按之空虚，为","o":["弱脉","虚脉","涩脉","微脉","濡脉"],"a":1,"e":"举之无力、按之空虚者为虚脉，主气血两虚；弱脉沉细而软，须重按始得。，虚脉以举按俱无力为特点。"},{"q":"弦脉的脉象是","o":["脉气紧张，端直而长","脉来绷急，状如牵绳","浮而搏指，滑数有力","沉按实大，弦长有力","状如波涛，来盛去衰"],"a":0,"e":"弦脉端直而长、指下挺然、脉气紧张如按琴弦，主肝胆病、痛证与痰饮。，端直以长为弦脉之要。"},{"q":"以肢体震颤，手足拘急，爪甲不荣，面白无华，舌质淡白，脉细或弱为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","肝胆湿热证"],"a":0,"e":"肢体震颤、手足拘急、爪甲不荣、面白无华、舌淡白、脉细弱，为肝血亏虚、筋脉失养而风动，属血虚生风证。"},{"q":"三部脉举之无力，按之空虚的脉象，属于","o":["芤脉","虚脉","浮脉","散脉","绝脉"],"a":1,"e":"三部脉举之无力、按之空虚者为虚脉，主气血两虚、脏腑功能衰退。，与芤脉之浮大中空不同。"},{"q":"肝阳上亢证与肝火炽盛证均可见","o":["吐血衄血","头重脚轻","头晕耳鸣","腰膝酸软","五心烦热"],"a":2,"e":"两证均有头晕耳鸣、头目胀痛、面赤易怒，因肝阳偏亢、气血上涌；头重脚轻、腰膝酸软为肝阳上亢独有。"},{"q":"厚苔不见于哪项","o":["胃肠食滞","痰浊停滞","病位在里","外感风寒","肠热腑实"],"a":3,"e":"厚苔主邪盛入里、胃肠食滞、痰浊停滞及肠热腑实；外感风寒初起苔多薄白。，苔之厚薄可测邪气深浅。"},{"q":"肝郁气滞证与肝火炽盛证均可见","o":["情志抑郁","面红目赤","舌体淡白","月经后期","胁肋疼痛"],"a":4,"e":"两证均见胁肋疼痛，因肝失疏泄、经气不利；面红目赤属肝火炽盛，情志抑郁属肝郁气滞。"},{"q":"心阴虚证的脉象是","o":["脉细数","脉细弦","脉细弱","脉细迟","脉沉细"],"a":0,"e":"心阴虚则阴不制阳、虚热内生，脉细而数；脉细弱属气血虚，脉沉细多属阳虚。，数主热，细主阴血不足。"},{"q":"以头目胀痛，眩晕耳鸣，面红目赤，急躁易怒，失眠多梦，头重脚轻，腰膝酸软，舌红少津，脉弦或弦细数为主要表现的证候是","o":["肝胆湿热证","肝风内动证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":2,"e":"头目胀痛、眩晕耳鸣、面红目赤、急躁易怒，兼头重脚轻、腰膝酸软、舌红少津，为上盛下虚之肝阳上亢证。"},{"q":"温病化热，津液暴伤可见","o":["苔白而湿润","薄白苔","积粉苔","苔白糙裂","白腻苔"],"a":3,"e":"温病化热、津液暴伤，苔失濡润而见白糙裂纹；苔白湿润属寒湿，积粉苔属秽浊热毒相结。"},{"q":"咳吐脓血腥臭痰，多属","o":["肺热","肺痨","肺胀","肺痿","肺痈"],"a":4,"e":"咳吐脓血腥臭痰为热毒壅肺、血腐成脓，是肺痈的典型表现；肺痨以干咳痰中带血、潮热盗汗为主。"},{"q":"临床提示正气不足，精气轻度损伤，脏腑功能减弱，此属于","o":["得神","少神","失神","假神","神乱"],"a":1,"e":"少神又称神气不足，表现为精神不振、目光乏神、动作迟缓，提示正气不足、精气轻度损伤。"},{"q":"由于气候影响，平脉在秋天可见","o":["浮","沉","洪","弦","迟"],"a":0,"e":"四时平脉春弦、夏洪、秋浮、冬沉，秋季阳气渐收、脉气轻浮，故平脉在秋天可见浮。，脉应四时方为平脉。"},{"q":"痰湿困脾所致嗜睡的表现是","o":["困倦嗜睡，头脑昏沉","精神疲惫，似睡非睡","饭后嗜睡，神疲倦怠","高热神迷，昏昏欲睡","昏睡伴有鼾声，痰鸣"],"a":0,"e":"痰湿困脾、清阳不升，故困倦嗜睡而头脑昏沉、身重苔腻；饭后嗜睡属脾虚，昏睡痰鸣属痰蒙神窍。"},{"q":"寒证的典型舌象是","o":["舌红苔黄而干","舌淡白苔白腻","舌青紫苔黄腻","舌绛苔干","舌绛紫无苔"],"a":1,"e":"寒证舌淡白、苔白腻，因阳气不足、水湿不化；舌红苔黄、舌绛苔干均为热象。，苔白腻为寒湿内盛之征。"},{"q":"气滞类证不包括下列哪项","o":["气滞证","气逆证","气郁证","气闭证","气陷证"],"a":4,"e":"气滞类证包括气滞、气逆、气闭、气郁；气陷属气虚下陷之气陷类，不属气滞。，气陷以气虚下陷、内脏下垂为特征。"},{"q":"小儿食指络脉诊法始见于","o":["《内经》","《察病指南》","《伤寒论》","《景岳全书》","《水镜图诀》"],"a":4,"e":"小儿食指络脉诊法始见于《水镜图诀》，书中记载望指纹以辨小儿病证；《内经》论诊络而未成专法。"},{"q":"下列哪项可导致尿后余沥不尽","o":["结石阻塞","肾阳虚","肾阴虚","瘀血内阻","肾气不固"],"a":4,"e":"尿后余沥不尽为肾气不固、膀胱失约、余溺不能尽排；结石、瘀血多致尿痛或尿闭。，多见于年老肾气亏虚者。"},{"q":"弦细脉的主病为","o":["血虚肝郁","肝郁气滞","肝胆湿热","水饮内停","气血不足"],"a":0,"e":"弦细脉主血虚肝郁，弦为肝郁、细为血虚；弦滑数多主肝胆湿热。，细主阴血虚，弦主气郁。"},{"q":"根据五轮学说，白睛属","o":["心","肺","脾","肝","肾"],"a":1,"e":"五轮学说中白睛属肺，为气轮；黑睛属肝为风轮，两眦属心为血轮，瞳神属肾为水轮，胞睑属脾为肉轮。"},{"q":"寒证的典型临床表现有","o":["恶热喜冷","口渴欲饮","痰、涕黄稠","小便短黄","舌淡苔白"],"a":4,"e":"寒证舌淡苔白、畏寒肢冷、分泌物清稀；恶热喜冷、口渴、痰涕黄稠、小便短黄均为热象。"},{"q":"下列何项与肝郁化火失眠无关","o":["心悸健忘","烦躁失眠","面目红赤","脉象弦数","性急易怒"],"a":0,"e":"肝郁化火、上扰心神则烦躁失眠、面红目赤、性急易怒、脉弦数；心悸健忘属心血不足。，治宜疏肝泻火安神。"},{"q":"下列除哪项外，均可导致便秘","o":["阳虚","气虚","血虚","阴虚","湿热"],"a":4,"e":"阳虚、气虚、血虚、阴虚均可致肠道推动无力或失于濡润而便秘；湿热多致便溏不爽、黏滞臭秽。"},{"q":"暑邪的致病特点有","o":["干涩伤津","多夹湿","易生风动血","易扰神明","易致肿疡"],"a":1,"e":"暑为阳邪，其性炎热升散，易伤津耗气、上扰神明，且暑多夹湿，故见身热汗多、心烦口渴、胸闷呕恶。"},{"q":"脉“有胃气”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","从容流利，和缓律齐","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":2,"e":"脉有胃气指脉来从容和缓、流利调匀、节律一致，反映脾胃运化健旺与气血充盈。，即脉象有神之和缓从容。"},{"q":"脉形浮大而软，按之中空，属于","o":["散脉","虚脉","芤脉","革脉","濡脉"],"a":2,"e":"脉形浮大而软、按之中空如按葱管者为芤脉，主失血、伤津。，与革脉之弦急中空相区别。"},{"q":"微脉、弱脉和濡脉共有的特征是","o":["脉细如线","细小无力","浮取即得","沉取始得","紧涩不畅"],"a":1,"e":"微脉极细极软、若有若无，弱脉沉细而软，濡脉浮细而软，三者共有特征为脉细而无力。，三者脉位有浮沉之别。"},{"q":"痰湿困脾所致嗜睡的特点是","o":["精神疲惫，似睡非睡","饭后嗜睡，神疲倦怠","昏睡伴有鼾声、痰鸣","困倦嗜睡，头脑昏沉","困倦嗜睡，睡后易醒"],"a":3,"e":"痰湿困脾、清阳不升，故困倦嗜睡、头脑昏沉、肢体困重；饭后嗜睡属脾虚气弱。，治宜健脾燥湿化痰。"},{"q":"下列哪种情况中不会出现滑脉","o":["实热","妊娠","疼痛","宿食","痰湿"],"a":2,"e":"滑脉主痰饮、食积、实热，妊娠亦见滑脉；疼痛多致弦脉或紧脉，不见滑脉。，疼痛多见于弦、紧脉。"},{"q":"肺热炽盛证的辨证要点是以咳喘、胸痛与下列何项共见","o":["里实热证","表实热证","里虚热证","风热表证","痰热里证"],"a":0,"e":"肺热炽盛以咳喘、胸痛与里实热证共见为辨证要点，见发热、口渴、痰黄稠、舌红苔黄、脉数。"},{"q":"属于血分证病位的是","o":["肺","胸膈","肝肾","胃","胆"],"a":2,"e":"血分证病位在肝肾，为温热邪毒深入血分、耗血动血，见斑疹显露、出血、舌深绛。，故入血就恐耗血动血。"},{"q":"三部脉举按均有力，来去俱盛的脉象，属于","o":["洪脉","滑脉","紧脉","实脉","弦脉"],"a":3,"e":"实脉三部举按皆有力、来去俱盛，主邪气亢盛而正气不虚；洪脉来盛去衰，滑脉往来流利。"},{"q":"下列哪项不会导致泄泻","o":["脾胃虚弱","肾阴亏虚","肾阳不足","大肠湿热","肠胃积滞"],"a":1,"e":"泄泻可因脾胃虚弱、肾阳不足、大肠湿热、肠胃积滞而致；肾阴亏虚无以温煦运化，不致泄泻。"},{"q":"下述哪项不是导致口气秽臭的原因","o":["口腔不洁","龋齿","消化不良","胃热","脾胃虚寒"],"a":4,"e":"口气秽臭多因口腔不洁、龋齿、消化不良、胃热上蒸；脾胃虚寒者口气清冷而无臭。，脾胃虚寒者口中多和而无异味。"},{"q":"湿邪困阻气机所致疼痛的特点是","o":["胀痛","冷痛","隐痛","重痛","绞痛"],"a":3,"e":"湿性重浊黏滞，困阻气机则疼痛重着、固定不移、缠绵难愈，故其疼痛特点为重痛。，湿性黏滞故痛而兼重着酸楚。"},{"q":"阴虚风动证与血虚生风证均可见到的症状是","o":["四肢颤动","面红目赤","舌体淡白","角弓反张","腰膝酸软"],"a":0,"e":"两证均因筋脉失养而风动，故同见四肢颤动、抽搐；面红目赤属热极生风，舌淡白属血虚生风。"},{"q":"月经推迟7天以上，量少、色淡而质稀者，属于","o":["血虚","血寒","血热","血瘀","气滞"],"a":0,"e":"月经推迟七天以上而量少、色淡、质稀，为血虚冲任不足、血海空虚；血寒多色暗有块、小腹冷痛。"},{"q":"鱼翔脉的主病是","o":["肾与命门之气皆亡","三阴寒极，阳亡于外","三阳热极，阴液枯竭","孤阳无依，躁动不安","胃气营卫将绝"],"a":1,"e":"鱼翔脉如鱼在水中游动、时隐时现、至数不清，主三阴寒极、阳亡于外。，与虾游脉之孤阳无依不同。"},{"q":"口干，但欲漱水不欲咽，多为","o":["外感风热","外感温热","湿热内蕴","里热炽盛","瘀血内阻"],"a":4,"e":"口干但欲漱水不欲咽，为瘀血内阻、津不上承而本无津伤，故虽口干而不欲咽。，瘀血内停故但欲漱水以润之。"},{"q":"下列哪项是面色黑的主病","o":["虚寒、瘀血、水饮","肾虚、寒证、水饮及血瘀","肾虚、痛证","肾虚、水饮","寒湿、痰饮"],"a":1,"e":"黑色主肾虚、寒证、水饮及血瘀，因肾阳虚衰、水寒不化、血行瘀滞而见面色黧黑。，肾色外泛故见黧黑晦暗。"},{"q":"以少腹冷痛，牵引阴部坠胀作痛，遇寒痛甚，畏寒肢冷，舌淡苔白，脉沉紧或弦紧为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝阴虚证"],"a":0,"e":"少腹冷痛牵引阴部坠胀、遇寒痛甚、畏寒肢冷、舌淡苔白、脉沉紧，为寒邪凝滞肝经之寒滞肝脉证。"},{"q":"舌尖所候的脏腑一般是","o":["脾胃","肝胆","心肺","肾","三焦"],"a":2,"e":"舌面分候脏腑，舌尖候心肺，舌中候脾胃，舌边候肝胆，舌根候肾，故舌尖异常多反映心肺病变。"},{"q":"面色青黄者，多属","o":["阴寒内生","寒邪凝滞","心脉痹阻","热盛动风","肝郁脾虚"],"a":4,"e":"面色青黄并见，青属肝、黄属脾，为肝木乘脾、肝郁脾虚之象。，木旺乘土故色见青黄。，治宜疏肝健脾。"},{"q":"下列各项，不属寒湿困脾证的临床表现的是","o":["面黄鲜明","腹胀便溏","口腻纳呆","肢体困重","脉象濡缓"],"a":0,"e":"寒湿困脾见面色晦黄、腹胀便溏、口腻纳呆、肢体困重、脉濡缓；面黄鲜明属湿热蕴结之阳黄。"},{"q":"以两目干涩，胁肋灼痛，两颧潮红，五心烦热，舌红少苔，脉弦细数为主要表现的证是","o":["肝阴虚证","肝血虚证","肝阳上亢证","肝气郁结证","血虚生风证"],"a":0,"e":"肝阴不足，目失濡养则两目干涩，肝络失养则胁肋灼痛；阴虚内热故两颧潮红、五心烦热，舌红少苔、脉弦细数为阴虚之征。"},{"q":"产后大出血，继则冷汗淋漓，甚则晕厥。其病机是","o":["气滞血瘀","气不摄血","气随血脱","气血两虚","气血失和"],"a":2,"e":"产后大出血致血脱，气无所附而随之外脱，故冷汗淋漓、甚则晕厥，此为气随血脱的重危证候。"},{"q":"紧脉的主病是","o":["邪闭","厥证","肿痈","湿证","宿食"],"a":4,"e":"紧脉脉体绷急、弹指有力，主实寒、疼痛与宿食；寒凝气阻或食积停滞，脉道拘急，故见此象。"},{"q":"《诊家正眼》在《濒湖脉学》的基础上又增加一种脉象是","o":["疾脉","结脉","紧脉","牢脉","数脉"],"a":0,"e":"李时珍《濒湖脉学》载二十七脉，李中梓《诊家正眼》增列疾脉而成二十八脉，所增者为疾脉。"},{"q":"表现为神志清楚，而吐字困难不清，语言不流畅的是","o":["狂言","错语","呓语","言謇","谵语"],"a":3,"e":"言謇指神志清楚而言语謇涩、吐字不清，多为风痰阻络、舌本不利；谵语、错语属神志异常的语言错乱。"},{"q":"脉率迟缓，时见一止，止无定数，是指","o":["代脉","促脉","结脉","动脉","涩脉"],"a":2,"e":"结脉脉来迟缓而时有一止、止无定数，主阴盛气结、寒痰血瘀；代脉虽亦时止，但止有定数，二者以此相别。"},{"q":"手指关节呈梭状畸形，活动受限者，多因","o":["寒湿内侵","瘀血阻络","寒湿久留","风湿久蕴、痰瘀阻络","气血亏虚"],"a":3,"e":"指关节呈梭状畸形，由风湿日久、痰瘀互结、筋骨失养所致，属痹证后期关节变形，屈伸受限。"},{"q":"下列哪项不属于舌态的变化","o":["痿软","强硬","歪斜","胖大","短缩"],"a":3,"e":"舌态包括痿软、强硬、歪斜、颤动、吐弄、短缩六种；胖大属舌形改变，反映水湿痰饮内停。"},{"q":"引起阳黄的主要病机是","o":["痰热","寒湿","脾虚","肝失疏泄","湿热"],"a":4,"e":"阳黄由湿热熏蒸肝胆、胆汁外溢肌肤而成，黄色鲜明如橘；寒湿困阻所致者为阴黄，其色晦暗。"},{"q":"属于证候错杂关系的是","o":["表实寒证、表实热证、里实寒证","表实热证、里实寒证、里实热证","里实寒证、里实热证、里虚寒证","表寒里热证、上热下寒证、里虚表实证","里实热证、里虚寒证、里虚热证"],"a":3,"e":"证候错杂指表里、上下、虚实同时并见，如表寒里热、上热下寒、里虚表实；其余各项为单一或同类证候并列。"},{"q":"胸闷心悸，咳嗽气喘，牵引疼痛，属","o":["饮停胸胁","饮停肠间","饮停于胃","水饮凌心","痰湿阻肺"],"a":0,"e":"饮邪停于胸胁、阻滞气机，故胸闷心悸、咳喘牵引作痛，属四饮中的悬饮，与支饮停肺不同。"},{"q":"下列哪项对诊断脾肺气虚证最有意义","o":["咳喘短气、食少便溏","咯痰清稀、面白神疲","肢体浮肿、舌淡脉弱","气短而喘、声低懒言","纳少腹胀、身倦乏力"],"a":0,"e":"脾肺气虚须脾虚与肺虚并见，咳喘短气提示肺虚，食少便溏提示脾虚，二者同具方为定位依据。"},{"q":"下列各项，不属“证名”的是","o":["肝阳化风","烂喉丹痧","脾肾阳虚","痰热壅肺","膀胱湿热"],"a":1,"e":"烂喉丹痧是以症状命名的病名，不属证名；肝阳化风、脾肾阳虚、痰热壅肺、膀胱湿热均由病位与病性构成证名。"},{"q":"根据五轮学说，风轮是指目的哪个部位","o":["瞳仁","黑睛","两眦","白睛","眼睑"],"a":1,"e":"五轮学说中黑睛为风轮属肝，瞳仁为水轮属肾，两眦为血轮属心，白睛为气轮属肺，眼睑为肉轮属脾。"},{"q":"表现为语言低微，气短不续，欲言不能复言的是","o":["少气","夺气","气粗","短气","气微"],"a":1,"e":"夺气指语言低微、气短不续、欲言不能复言，为宗气大虚、气不接续之象；少气仅言气息微弱。"},{"q":"下列哪项不属于心血虚证的常见症状","o":["心悸","头晕眼花","失眠多梦","面色㿠白","健忘"],"a":3,"e":"心血虚以心悸、失眠多梦、健忘、头晕眼花、面色淡白无华为主；面色㿠白属阳气虚衰，故不属本证。"},{"q":"现病史的时间界限是","o":["医生认为最恰当的时间","无明确的时间界限","当前所有症状出现的时间","既往史涉及病痛的时间","主诉所述症状所定的时间"],"a":4,"e":"现病史自发病之时起至本次就诊止，起病时间以主诉所述症状出现的时间为界，非既往患病时间。"},{"q":"心阳暴脱证与心脉痹阻证不同的症状是","o":["心胸憋闷","痛引肩背","气短乏力","冷汗淋漓","脉沉无力"],"a":3,"e":"心阳暴脱由心阳衰微、阳气欲脱所致，冷汗淋漓、四肢厥冷为阳气外脱的特有表现，心脉痹阻无此征。"},{"q":"肠热腑实证发热的特点是","o":["骨蒸潮热","身热不扬","暮热早凉","身热夜甚","日晡潮热"],"a":4,"e":"肠热腑实为热邪与燥屎互结于阳明，腑气不通、邪热内蒸，故日晡潮热、腹痛拒按、大便秘结。"},{"q":"下列各项，不属胃热炽盛证的临床表现的是","o":["胃脘灼痛","消谷善饥","龈肿齿衄","舌红少苔","便秘尿黄"],"a":3,"e":"胃热炽盛属实热证，舌红而苔黄燥；舌红少苔为胃阴不足、虚热内生之象，故不属本证。胃阴不足则舌红少苔。"},{"q":"两颧潮红多见于","o":["阴虚阳亢","外感发热","真寒假热","气虚发热","火热炽盛"],"a":0,"e":"两颧潮红为阴虚阳亢、虚火上炎所致，午后尤显，伴五心烦热；外感发热则满面通红。外感热盛则满面通红。"},{"q":"表现为咳声重浊紧闷，痰多色白易咯的是","o":["风寒束表","寒邪客肺","痰湿阻肺","阴虚肺燥","热邪壅肺"],"a":2,"e":"痰湿阻肺，痰壅气逆、肺失宣降，故咳声重浊紧闷、痰多色白易咯，舌苔多白腻而脉滑。此属寒痰壅肺。"},{"q":"饮停胸胁证属饮证中之","o":["支饮","悬饮","痰饮","溢饮","淡饮"],"a":1,"e":"饮停胸胁即悬饮；饮停胃肠为痰饮，饮溢四肢为溢饮，饮停胸肺为支饮，四者以停聚部位相别。"},{"q":"舌下络脉粗胀，或呈青紫、紫红、绛紫、紫黑色，多见于","o":["血瘀","寒凝","热极","痰阻","气滞"],"a":0,"e":"舌下络脉粗胀，或呈青紫、紫红、紫黑色，为血行瘀滞、脉络不通之征，主血瘀。舌质多紫暗或有瘀斑。"},{"q":"大便溏泄黄糜，多为","o":["脾胃虚寒","胃热炽盛","食积大肠","胃腑气滞","大肠湿热"],"a":4,"e":"大便溏泄黄糜、黏臭、肛门灼热，为湿热蕴结大肠，传导失常、气机阻滞所致，舌苔多黄腻。"},{"q":"判断正气渐衰，可见","o":["舌苔从全到剥","舌苔剥落处复生薄白之苔","未剥落处似有腻苔或滑苔","剥落处似存新生颗粒","舌苔剥落部位时时转移"],"a":0,"e":"舌苔由全到剥，示胃气渐衰、胃阴耗伤，为正气渐衰；剥落处复生薄白苔，方为正气渐复。"},{"q":"脉“有根”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","不快不慢，和缓有力","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":3,"e":"脉之有根指尺脉有力、沉取不绝，反映肾气未绝、根基尚存，与有胃、有神合称脉象三要素。"},{"q":"渴喜热饮，但饮水不多，多属","o":["湿热证","水逆证","瘀血","痰饮内停","阳明经证"],"a":3,"e":"渴喜热饮而饮水不多，为痰饮内停、津不上承所致；饮入不能化津，故虽渴而不欲多饮。此为饮停心下之象。"},{"q":"惊风常见面色是","o":["赤色","黄色","黑色","青色","白色"],"a":3,"e":"小儿惊风，筋脉拘急、气血郁滞不通，故面部多见青色，为青色主惊风之典型表现。青为肝色，主惊风。"},{"q":"小儿发结如穗，枯黄无泽，伴见面黄肌瘦者，多为","o":["疳积","精血不足","脾胃虚弱","劳神伤血","血虚受风"],"a":0,"e":"小儿发结如穗、枯黄无泽，伴面黄肌瘦，为脾胃受损、气血生化不足之疳积，多因喂养不当。"},{"q":"目部五脏分属中的水轮是","o":["目眦","瞳仁","白睛","眼睑","黑睛"],"a":1,"e":"目部五脏分属中，瞳仁为水轮属肾，黑睛为风轮属肝，白睛为气轮属肺，两眦为血轮属心。"},{"q":"实证的络脉异常有","o":["络色深浓而黯滞","络色浅谈而枯槁不泽","络脉淡白纤细","络脉沉隐","络脉鲜红"],"a":0,"e":"实证络脉色深浓而黯滞；虚证则浅淡枯槁不泽、纤细沉隐，据此可辨络脉之虚实属性。色泽荣枯可辨虚实。"},{"q":"缓脉常见于","o":["水饮内停","湿邪困阻","气滞血瘀","食积停滞","虚阳浮越"],"a":1,"e":"缓脉来去怠缓，主湿邪困阻与脾虚；湿性黏滞，阻遏脉道，故脉来弛缓，一息四至。湿去则脉自和。"},{"q":"外感热病，邪热深入营分，多见","o":["淡舌","红舌","绛舌","青舌","紫舌"],"a":2,"e":"绛舌为深红色，主热入营血与阴虚火旺；邪热深入营分，营阴受损，故舌色深绛。绛而干者阴液已伤。"},{"q":"煤气中毒的患者可见","o":["口唇樱桃红色","口唇淡白","口唇红赤","口唇青紫","口唇青黑"],"a":0,"e":"一氧化碳与血红蛋白结合成碳氧血红蛋白，使口唇黏膜呈樱桃红色，为煤气中毒的特征体征。"},{"q":"《濒湖脉学》中记载的脉象有","o":["24种","27种","28种","33种","32种"],"a":1,"e":"李时珍《濒湖脉学》载二十七脉，李中梓《诊家正眼》在此基础上增疾脉，遂成二十八脉。"},{"q":"下列哪项不是肾阴虚证与肾精不足的共同表现","o":["腰膝酸软","遗精","女子经少","经闭","男子精少"],"a":1,"e":"肾阴虚与肾精不足均见腰膝酸软、女子经少经闭、男子精少；遗精由阴虚火旺扰动精室所致，非二者共有。"},{"q":"厌食油腻厚味，胁肋胀痛，苔黄腻者，多为","o":["伤食","气滞","肝胆病","妊娠","脾胃病"],"a":2,"e":"厌食油腻、胁肋胀痛、苔黄腻，为肝胆湿热、疏泄失职、胆汁排泄不畅之象，属肝胆病。治宜清利肝胆湿热。"},{"q":"半表半里证的典型表现为","o":["腹痛喜按","口渴喜饮","胸胁苦满","鼻塞流涕","小便清长"],"a":2,"e":"半表半里为邪郁少阳、枢机不利，故胸胁苦满、寒热往来、口苦咽干、脉弦，为少阳证主症。"},{"q":"脉极细极软，按之欲绝，似有若无属，称为","o":["散脉","虚脉","濡脉","微脉","数脉"],"a":3,"e":"微脉极细极软，按之欲绝，似有若无，主阳气衰微、气血大虚，多见于久病危重之人。脉道失充，故按之欲绝。"},{"q":"湿浊内蕴，阳气被遏，湿浊痰饮停聚舌面，可见","o":["燥苔","腐苔","剥苔","润苔","腻苔"],"a":4,"e":"腻苔颗粒细腻致密、揩之不去，由湿浊内蕴、阳气被遏、痰饮停聚舌面而成，主湿浊痰饮。"},{"q":"气滞心脉之心脉痹阻证心胸疼痛的特点是","o":["刺痛","胀痛","冷痛","灼痛","闷痛"],"a":1,"e":"气滞心脉，气机郁滞不通，故心胸胀痛，时轻时重，随情志变化增减，脉多弦，属实证。治当行气活血。"},{"q":"面色青黑主病为","o":["痛","热","湿","虚","燥"],"a":0,"e":"青色主寒、痛、瘀血与惊风；面色青黑并见，多为阴寒内盛、气血凝滞、疼痛剧烈所致。面黑而干枯者多属肾虚。"},{"q":"鉴别表证与里证主要审察","o":["寒热","头痛","腹痛","咳嗽","脉象"],"a":0,"e":"表证与里证的鉴别关键在于恶寒发热的有无与轻重，表证必恶寒发热并见，里证则但寒不热或但热不寒。"},{"q":"患部形小而圆，突起根浅，红肿热痛不甚，易于成脓，脓出即愈，为","o":["疽","痈","疔","疖","丹毒"],"a":3,"e":"疖形小而圆、突起根浅、红肿热痛不甚，易成脓易破溃而愈；痈疽范围大而深，疔则坚硬根深。"},{"q":"面色黧黑，肌肤甲错者，多为","o":["肾虚水饮","肾阴虚火旺","瘀血久停","寒湿带下","肾阳虚衰，血失温养"],"a":2,"e":"面色黧黑，肌肤甲错，为瘀血久停、新血不生、肌肤失养所致，常伴舌紫暗、脉涩。此为久瘀入络之征。"},{"q":"以男性阴囊瘙痒、潮湿，女性外阴湿疹或阴器肿痛、带下黄臭，舌红，苔黄腻，脉弦滑数为主要表现的证候是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","胆郁痰扰证"],"a":1,"e":"湿热蕴结肝胆、下注前阴，故阴囊潮湿瘙痒、带下黄臭，舌红苔黄腻、脉弦滑数为湿热之征。"},{"q":"下列选项中，均具有脉搏有力特点的脉象是","o":["牢脉，实脉，洪脉，弦脉","洪脉，实脉，弦脉，芤脉","牢脉，革脉，弦脉，弱脉","弱脉，革脉，伏脉，牢脉","牢脉，弱脉，沉脉，伏脉"],"a":0,"e":"牢、实、洪、弦四脉脉体充实、应指有力；芤、革脉按之中空，弱脉则柔软无力，以此相别。"},{"q":"神疲乏力，面色萎黄，食少，便溏，皮下紫斑，证属","o":["脾气虚证","脾虚气陷证","脾不统血证","脾阳虚证","寒湿困脾证"],"a":2,"e":"脾气虚衰，统血无权，血溢脉外故见皮下紫斑，兼食少便溏、神疲乏力、面色萎黄、舌淡脉弱。"},{"q":"与忧伤证无关的是","o":["烦躁多怒","情绪忧虑","抑郁寡欢","表情淡漠","善太息"],"a":0,"e":"忧伤证见情绪忧虑、抑郁寡欢、表情淡漠、善太息；烦躁多怒属怒伤肝、肝气上逆之象。肝在志为怒，怒则气上。"},{"q":"肠热腑实证与肠燥津亏证均可见","o":["神昏谵语","脉数有力","热结旁流","大便秘结","腹痛拒按"],"a":3,"e":"肠热腑实为燥屎内结、腑气不通，肠燥津亏为津枯肠失濡润，二者传导失常，故均见大便秘结、排便困难。"},{"q":"属于温病中焦病证的症状是","o":["恶寒","耳聋","手足蠕动","鼻塞","腹满"],"a":4,"e":"温病中焦病证为邪入脾胃、气机壅滞，故腹满、便秘或便溏、苔黄燥；耳聋、手足蠕动分属上焦、下焦。"},{"q":"以下症状表现为牙关紧急的是","o":["口张","口噤","口撮","口振","口动"],"a":1,"e":"口噤指牙关紧急、口闭难开，见于破伤风、痉病；口撮为上下口唇紧聚，口张则口开不闭。"},{"q":"医生用指掌稍用力寻抚胸腹、腧穴、肿胀等部位，称为","o":["按法","摸法","触法","压法","叩法"],"a":1,"e":"摸法是以指掌稍用力寻抚胸腹、腧穴、肿胀处，测其温度、压痛与肿块性质，属切诊范围。"},{"q":"下列脉象中不主虚证的是","o":["浮脉","牢脉","微脉","细脉","濡脉"],"a":1,"e":"牢脉沉取实大弦长、坚牢不移，主阴寒内盛、疝气癥积，属邪实内结之脉，故不主虚。沉取始得，故与虚脉相别。"},{"q":"下列各项，不属血瘀证的临床表现的是","o":["痛如针刺","腹内肿块","出血反复不止","头晕胀痛","面色黧黑"],"a":3,"e":"血瘀证以刺痛、腹内肿块、出血反复不止、面色黧黑、舌紫暗为主；头晕胀痛属肝阳上亢。"},{"q":"与湿证有关的脉象是","o":["迟脉，弱脉，濡脉","弱脉，细脉，散脉","细脉，濡脉，缓脉","涩脉，微脉，濡脉","弱脉，濡脉，涩脉"],"a":2,"e":"湿性黏滞重浊，困阻脉道，故脉见细、濡、缓，为湿证常见的脉象组合，亦见于脾虚。苔多白腻，可佐证之。"},{"q":"黄糙苔主","o":["里热炽盛，阴津耗竭","风寒入里，化热伤津","邪热伤津，燥结腑实","气血亏虚，复感湿热","痰热内蕴，食积化腐"],"a":2,"e":"黄糙苔苔色黄而干涩粗糙，为邪热伤津、燥结腑实之征，多见于热盛日久、津液已伤。苔质糙裂为津伤之征。"},{"q":"沉迟脉的主病多为","o":["里寒证","肝郁气滞","水饮内停","气滞血瘀","阴血亏虚"],"a":0,"e":"沉脉主里，迟脉主寒，两脉并见多属里寒证，伴畏寒肢冷、腹痛喜温、舌淡苔白。脉来无力者，阳虚尤甚。"},{"q":"只有通过问诊可知的症状是","o":["苔黄","耳鸣","水肿","汗出","面赤"],"a":1,"e":"耳鸣为患者自觉耳内鸣响，无外在客观征象，唯问诊可知；苔黄、水肿、汗出、面赤均可望而得之。"},{"q":"下列哪项是少阴病的主要脉症","o":["脉沉细，四肢厥","脉微细，但欲寐","脉弦细，面色赤","脉沉迟，但恶寒","脉细数，不得眠"],"a":1,"e":"少阴病为心肾阳虚、阴寒内盛，故脉微细、但欲寐，伴无热恶寒、四肢厥冷、下利。此为心肾阳衰之危候。"},{"q":"下列哪项对诊断肾虚水泛证最无意义","o":["心悸气短","小便清长","畏寒肢冷","腰膝酸冷","咳喘痰鸣"],"a":1,"e":"肾虚水泛以水肿、尿少、腰膝酸冷、心悸咳喘为主；小便清长为肾阳虚的一般表现，对水泛辨证意义最小。"},{"q":"动脉见于","o":["热证","痛、惊","阳盛实热","阳极阴竭","气滞血瘀"],"a":1,"e":"动脉脉短如豆、厥厥动摇，滑数有力，主惊恐与疼痛，因气血逆乱、脉道拘急所致。脉形如豆，关部明显。"},{"q":"缓脉的主病为","o":["水饮","痰证","湿证","食积","气滞"],"a":2,"e":"缓脉一息四至、来去怠缓，主湿邪困脾，亦见于脾胃虚弱，须结合兼症与舌象辨别。脉率偏慢，一息四至。"},{"q":"下列选项中，均具有脉搏无力特点的脉象是","o":["散脉，弱脉，微脉","濡脉，结脉，浮脉","结脉，代脉，紧脉","沉脉，伏脉，革脉","牢脉，短脉，弦脉"],"a":0,"e":"散、弱、微三脉均脉力软弱、按之无力；浮、结、代、紧、牢诸脉不以无力为特征。故三者俱主虚证。"},{"q":"对诊断肾阳虚证最有意义的症状是","o":["形寒肢冷，面白神疲","滑精早泄，小便频数","精冷不育，腰膝酸软","下肢水肿，按之凹陷","大便稀溏，排便不爽"],"a":2,"e":"精冷不育为肾阳虚衰、命门火不足、生殖功能减退的特异表现，腰膝酸软定位在肾，故对本证诊断意义最大。"},{"q":"下列各项，不属脾病常见症状的是","o":["腹胀","嗳气","便溏","浮肿","便血"],"a":1,"e":"嗳气由胃气上逆、胃失和降所致，属胃病症状；腹胀、便溏、浮肿、便血均可由脾失健运、统摄无权引起。"},{"q":"寒痰阻肺证最易见到的舌苔是","o":["薄白苔","白燥苔","积粉苔","白腻苔","白腐苔"],"a":3,"e":"寒痰阻肺，痰湿内盛上泛舌面，故舌苔白腻，痰白质稀易咯，伴胸闷畏寒、脉弦滑。此属寒饮停聚于肺。"},{"q":"寒热转化的关键因素是","o":["邪气的性质","气候的冷热","脏腑的盛衰","阴液的盈亏","阳气的盛衰"],"a":4,"e":"寒热转化取决于阳气盛衰，阳虚则从寒化、阳复则从热化，故阳气盛衰为寒热转化的关键。"},{"q":"舌苔薄白不见于下列哪项","o":["正常人","外感初起","气血亏虚","痰浊内阻","里邪不甚"],"a":3,"e":"薄白苔见于常人、外感初起，亦主里邪不甚；痰浊内阻则苔白腻，故不见薄白苔。苔之厚薄可辨邪之深浅。"},{"q":"语言异常与下列何脏关系最密切","o":["心","肝","脾","肺","肾"],"a":0,"e":"心主神明，舌为心之苗，语言为神明活动之外现，故语言异常与心关系最密切，心神受扰则言错、谵语。"},{"q":"下列除哪项外，均为膀胱湿热证的特征表现","o":["尿频","尿急","尿痛","遗尿","尿黄"],"a":3,"e":"膀胱湿热见尿频、尿急、尿痛、尿黄；遗尿为膀胱失约、肾气不固所致，故不属本证。治宜清热利湿通淋。"},{"q":"细小如线，应指明显的脉象是","o":["虚脉","涩脉","细脉","微脉","濡脉"],"a":2,"e":"细脉脉细如线而应指明显，主气血两虚、湿邪困阻；微脉则极细极软、按之欲绝。主虚证与湿证。"},{"q":"舌苔黏腻而厚，口中发甜，多因","o":["食积","脾虚湿困","痰浊内阻","脾胃湿热","胃气衰败"],"a":3,"e":"苔黏腻而厚、口中发甜，为脾胃湿热、湿浊上泛所致，甘味属脾，故甜味多见于脾病。苔黄腻为湿热之征。"},{"q":"发结如穗，枯黄无泽，伴见面黄肌瘦的小儿，多见于","o":["肾精亏损","气血亏虚","疳积病","血虚受风","先天遗传"],"a":2,"e":"小儿发结如穗、枯黄无泽，伴面黄肌瘦，为脾胃虚弱、气血生化不足之疳积病，属疳证范畴。"},{"q":"脉形超过本部，长而不急为","o":["弦脉","紧脉","长脉","革脉","牢脉"],"a":2,"e":"长脉脉体超过本位，首尾端直而长，和缓不促，主阳证、热证及气机健旺，为有余之象。病主有余之证。"},{"q":"邪实为主，正虚为次的是","o":["实证","虚证","虚证夹实","实证夹虚","虚实并重"],"a":3,"e":"邪实为主、正虚为次者称实证夹虚，虚象轻浅而不占主导，治以祛邪为主、兼以扶正。治宜祛邪为主，兼以扶正。"},{"q":"气血两虚证的常见脉象","o":["弦脉","涩脉","浮脉","虚脉","紧脉"],"a":3,"e":"气血两虚，脉道不充、鼓动无力，故脉来虚软无力，按之空豁，主诸虚劳损。虚脉为诸虚劳损之主脉。"},{"q":"下列哪项不属于心血虚证的辨证要点","o":["心悸","失眠","多梦","血虚症状","烦躁"],"a":4,"e":"心血虚以心悸、失眠、多梦、健忘及血虚见症为辨证要点；烦躁属心神被扰的实象。舌淡脉细为血虚之征。"},{"q":"长期精神紧张，最容易出现的头发病变为","o":["白发","发黄干枯","斑秃","顶秃","发结如穗"],"a":2,"e":"长期精神紧张、情志郁结致气滞血瘀，毛发失养，故见突然成片脱落之斑秃，多无自觉症状。"},{"q":"舌上有糜点如饭粒，揩之即去，旋即复生，揩去处舌面光剥无苔，称为","o":["垢腻苔","黏腻苔","霉苔","脓腐苔","腐苔"],"a":2,"e":"霉苔由秽浊邪毒上泛舌面而成，形如饭粒，揩去复生，露光剥舌面，主胃气衰败、湿浊内盛。"},{"q":"属风热表证发热特点的是","o":["发热重恶寒轻","恶寒重发热轻","发热轻而恶风","但寒不热","但热不寒"],"a":0,"e":"风热为阳邪，热为阳、寒为阴，故发热重而恶寒轻，伴咽喉肿痛、口渴、脉浮数，与风寒表证相反。"},{"q":"胃热者，呕吐物多表现为","o":["清稀无气味","腐臭而秽浊","气味酸腐","无酸腐气味","吐脓血腥臭"],"a":2,"e":"胃热炽盛，胃气上逆，故呕吐物气味酸腐秽臭，伴胃脘灼痛、口臭、舌红苔黄、便秘尿黄。"},{"q":"阴虚证临床表现有","o":["口淡不渴","两颧潮红","无汗或自汗","小便清长或尿少不利","大便稀薄"],"a":1,"e":"阴虚证见两颧潮红、五心烦热、盗汗、舌红少苔、脉细数；口淡不渴、小便清长为阳虚之象。"},{"q":"下列何项是导致嗜睡的机理","o":["阳虚阴盛","阴虚阳盛","阳不入阴","心胆气虚","心脾两虚"],"a":0,"e":"嗜睡由阳虚阴盛、痰湿困阻，阳气不振而神失所养；阳不入阴、神不守舍则为不寐。阳虚阴盛则精神不振。"},{"q":"下列哪项不属“心脾两虚”的病理改变","o":["脾气亏虚，不能统血","生化不足，血液亏少","心阳气虚，血行不畅","心血不足，心神失养","脾失健运，营气不足"],"a":2,"e":"心脾两虚为心血不足、脾气亏虚，属气血两虚，无阳气虚衰、血行不畅之病理改变。本证属气血两虚。"},{"q":"沉按实大弦长，坚牢不移，为","o":["长脉","弦脉","伏脉","牢脉","紧脉"],"a":3,"e":"牢脉沉按实大弦长、坚牢不移，脉位深而有力，主阴寒内积、癥瘕疝气。沉取有力，故不主虚。"},{"q":"脉“有神”主要是指","o":["不浮不沉，不大不小","柔和有力，节律一致","不快不慢，和缓有力","尺脉有力，沉取不绝","一息四至，闰以五至"],"a":1,"e":"脉之有神指脉来柔和有力、节律整齐，反映胃气与气血充盈，为脉象三要素之一，病则脉失神气。"},{"q":"严重呼吸困难患者，其唇色的变化为","o":["淡白","红润","青紫","青黑","淡紫"],"a":2,"e":"严重呼吸困难，气机壅滞、血行瘀阻，故口唇青紫，甚则爪甲亦紫，属气滞血瘀之象。此为缺氧之征。"},{"q":"尿频、尿急、尿痛之症，属于","o":["尿失禁","淋证","癃闭","肾阳虚","肾阴虚"],"a":1,"e":"尿频、尿急、尿痛为湿热蕴结膀胱、气化不利所致，属淋证，与癃闭之尿闭不通不同。治宜清热利湿通淋。"},{"q":"亡阳证汗出的特点是","o":["冷汗淋漓","汗冷味咸","汗热而黏","汗出如油","汗出恶风"],"a":0,"e":"亡阳证阳气欲脱，汗出而冷、淋漓不止，伴四肢厥冷、脉微欲绝，为阳气外脱之危候。此为阳气外脱之危候。"},{"q":"舌苔白厚腻而干，多见于","o":["秽浊湿邪与热毒相结","燥热伤津","痰饮内停","湿浊中阻，津气不化","外感寒湿"],"a":3,"e":"白厚腻苔而干，为湿浊中阻、津气不化，津不上承故见干燥，舌面虽干而苔仍厚腻。此属湿遏津伤。"},{"q":"下列何项不属排尿感异常","o":["小便涩痛","小便频数","尿后余沥","小便失禁","小便灼热"],"a":1,"e":"排尿感异常包括小便涩痛、灼热、余沥不尽与失禁；小便频数属尿次异常，二者分类不同。"},{"q":"胃阴虚者常出现下列何症","o":["不饥少食","厌食油腻","消谷善饥","饥不欲食","突然食多"],"a":3,"e":"胃阴不足，虚热内生，胃失濡润、受纳无权，故饥不欲食，伴口燥咽干、舌红少苔。此为胃阴虚之特征。"},{"q":"小便频数、量少、色赤而痛，伴腰痛，属于","o":["膀胱湿热","下焦虚寒","肾气不固","心火亢盛","肾阴不足"],"a":0,"e":"小便频数量少、色赤而痛，为湿热下注膀胱；兼腰痛示病邪及肾，属膀胱湿热，非肾气不固。"},{"q":"消渴病的特点是","o":["尿急尿频尿痛","小便余沥不尽","多饮多食多尿","夜尿频多","小便失禁"],"a":2,"e":"消渴以多饮、多食、多尿、消瘦为特点，病机为阴虚燥热、津液输布失常，属三消并见。病位在肺胃肾。"},{"q":"下列哪项非白色所主病证","o":["寒证","夺气","脾虚","虚证","脱血"],"a":2,"e":"白色主虚证、寒证、失血与夺气；脾虚见面色萎黄，故黄色方主脾虚，白色不主脾虚。黄为脾之主色。"},{"q":"不属于正常舌质表现的是","o":["淡红鲜明","滋润光泽","活动自如","舌体柔软","舌体胖大"],"a":4,"e":"正常舌质淡红鲜明、滋润光泽、舌体柔软、活动自如；舌体胖大为水湿痰饮内停之病象。胖大之舌多属病态。"},{"q":"突发耳鸣，声大如潮，按之不减，伴有口苦、胁肋灼痛，属于","o":["阴虚火旺","肝胆火旺","肝肾阴虚","肾精亏损","肾气虚弱"],"a":1,"e":"突发耳鸣声大如潮、按之不减，属实证；伴口苦、胁肋灼痛，为肝胆火盛、循经上扰清窍。"},{"q":"以抑郁不乐，胸胁少腹走窜疼痛，病情轻重与情绪变化关系密切为主要表现的证是","o":["肝阴虚证","肝风内动证","肝气郁结证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"肝气郁结，疏泄失职，气机郁滞，故情志抑郁、胸胁少腹走窜胀痛，病情随情绪波动。脉弦为肝郁之征。"},{"q":"望色十法中，面色清明，多主阳证的是","o":["浮","清","散","微","泽"],"a":1,"e":"望色十法中，清者色泽清明、主病在阳，浊者色泽暗浊、主病在阴，为辨阴阳之要。此属望色十法之要。"},{"q":"气滞血瘀或伤精血少常见于以下哪一项脉象","o":["迟脉","细脉","涩脉","短脉","浮脉"],"a":2,"e":"涩脉往来艰涩不畅，如轻刀刮竹，主气滞血瘀、痰食内停与伤精血少、脉道失润。脉来涩滞，如刀刮竹。"},{"q":"对诊断肾阳虚证最无意义的是","o":["经少崩漏","五更泄泻","形寒肢冷","早泄精冷","性欲减退"],"a":0,"e":"肾阳虚以腰膝酸冷、形寒肢冷、五更泄泻、性欲减退、精冷为主；经少崩漏属精血亏虚，非本证要点。"},{"q":"在《灵枢•五色》中，青为","o":["心","肝","脾","肺","肾"],"a":1,"e":"《灵枢·五色》以青为肝、赤为心、黄为脾、白为肺、黑为肾，为五色配五脏之依据。五色应五脏，各有主属。"},{"q":"以干咳无痰、或痰少而黏为主要表现的证是","o":["肺气虚证","风热犯肺证","肺阴虚证","痰热壅肺证","肺热炽盛证"],"a":2,"e":"肺阴不足，虚火灼津，肺失濡润，故干咳无痰或痰少而黏，伴潮热盗汗、舌红少津。此属肺阴虚燥热。"},{"q":"判断病情的轻重和预后，更重要的是皮肤的","o":["色","泽","形","态","润"],"a":1,"e":"皮肤以润泽为要，泽反映精气盛衰与脏腑功能，故较色更能判断病情轻重与预后，枯槁无泽者病重。"},{"q":"暴病见下列何项，属脉症不相应","o":["浮脉","沉脉","洪脉","数脉","实脉"],"a":1,"e":"暴病多属实证，脉应浮洪数实；反见沉脉，为脉症不相应，提示邪盛而正气受损，预后欠佳。"},{"q":"热证通常不见","o":["数脉","滑脉","洪脉","促脉","结脉"],"a":4,"e":"结脉主阴盛气结、寒痰血瘀，属阴寒之象；热证多见数、滑、洪、促脉，不见结脉。结脉属阴，故热证不见。"},{"q":"湿浊上泛而胃气衰败，多见哪种舌象","o":["苔薄白而干","苔厚白而滑","苔厚白而干","苔白如积粉","苔白而腐"],"a":4,"e":"苔白而腐，苔质厚浊如腐渣，由湿浊上泛、胃气衰败、浊气熏蒸舌面所致，主病危重。此为胃气将败之兆。"},{"q":"以胁下肿块，或妇女乳房胀痛，月经不调，痛经；舌苔薄白，脉弦为主要表现的证是","o":["肝阴虚证","肝风内动证","肝郁气滞证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"肝郁气滞，气机不畅，血行瘀滞，故胁下肿块、乳房胀痛、月经不调、痛经，脉弦。此为肝郁气滞之候。"},{"q":"下列选项中，不属于个人生活史内容的是","o":["平素健康状况","生活经历","精神情志","饮食嗜好","婚姻产育"],"a":0,"e":"个人生活史包括生活经历、精神情志、饮食嗜好、婚姻产育；平素健康状况属既往史内容。"},{"q":"下列各项，属于胃气虚证与脾气虚证的鉴别要点的是","o":["面色萎黄","少气懒言","神疲肢倦","大便稀溏","舌淡脉弱"],"a":3,"e":"胃气虚以胃脘痞闷、食少乏味为主，脾气虚则运化失职而大便稀溏，此为二者鉴别要点。舌淡脉弱亦支持脾虚。"},{"q":"牙龈红肿疼痛，多为","o":["胃火亢盛","心脾积热","血络瘀阻","阴虚火旺","燥热伤津"],"a":0,"e":"牙龈红肿疼痛为胃火循经上炎所致，常伴口臭、齿衄、口渴、舌红苔黄，属实证。脉多滑数有力。"},{"q":"若见眉间、鼻柱、唇周色青者，多属于","o":["虚寒证","实寒证、剧痛","肝病迁延日久","惊风或惊风先兆","脾虚湿盛"],"a":3,"e":"眉间、鼻柱、唇周色青，为小儿惊风或惊风先兆，属肝风内动、筋脉拘急之象，亦见于惊恐。"},{"q":"久病见何脉为逆","o":["沉脉","细脉","浮脉","微脉","伏脉"],"a":2,"e":"久病正虚，脉当沉细弱；反见浮脉，为正气外浮、脉症相反，故谓之逆，主预后不良。此属脉症相反之逆候。"},{"q":"胃气虚证与胃阳虚证的鉴别要点是","o":["有无嗳气呃逆","有无食少纳差","有无乏力倦怠","有无胃脘冷痛","有无消谷善饥"],"a":3,"e":"胃阳虚在胃气虚基础上兼见胃脘冷痛、喜温喜按，有无冷痛为二者鉴别的关键。胃气虚则无冷痛之象。"},{"q":"下列哪项对诊断脾肺气虚证最无意义","o":["食少腹胀","面白神疲","面浮肢肿","咳喘短气","痰黏难咯"],"a":4,"e":"脾肺气虚以食少腹胀、咳喘短气、面浮肢肿、面白神疲为主；痰黏难咯属肺阴虚、虚火灼津。"},{"q":"舌体软弱无力，不能随意伸缩回旋者，称为","o":["短缩舌","痿软舌","吐弄舌","强硬舌","颤动舌"],"a":1,"e":"痿软舌指舌体软弱、不能随意伸缩回旋，由气血虚衰、阴液亏耗、筋脉失养所致。多见于久病重病之人。"},{"q":"下列属于望苔质的是","o":["青紫","裂纹","老嫩","剥落","点刺"],"a":3,"e":"苔质包括厚薄、润燥、腐腻、剥落、偏全；青紫属苔色，裂纹、老嫩、点刺属舌质。观苔质可测邪之性质。"},{"q":"均主饮食积滞的脉象是","o":["散脉，弱脉，代脉","滑脉，紧脉，促脉","结脉，代脉，促脉","沉脉，伏脉，革脉","牢脉，短脉，弦脉"],"a":1,"e":"滑脉主痰饮食积，紧脉主食积与寒痛，促脉主阳盛实热兼气血痰食停滞，三者均可因食积而见。"},{"q":"语言错乱，语后自知言错者称为","o":["错语","独语","谵语","呓语","郑声"],"a":0,"e":"错语指语言错乱、语后自知言错，由心气不足、神失所养所致，多见于久病体虚。此为心气不足之象。"},{"q":"对失眠诊断为心肾不交证最有意义的依据是","o":["心烦多梦，颧红盗汗","心悸怔忡，肢肿尿少","心烦健忘，脉象细数","心烦遗精，腰酸潮热","心烦而悸，舌红少苔"],"a":3,"e":"心肾不交为心火偏亢、肾水不足，水火不济，故心烦失眠、腰酸、遗精、潮热盗汗并见。舌红少苔，脉细数。"},{"q":"属风寒表证发热特点的是","o":["恶寒发热俱轻","恶寒发热俱重","恶寒发热交替","发热重恶寒轻","恶寒重发热轻"],"a":4,"e":"风寒束表，卫阳被遏，正邪交争，故恶寒重而发热轻，伴无汗、头身疼痛、脉浮紧。此为表寒证之特征。"},{"q":"舌红而肿胀满口，伴有齿痕者，为","o":["寒湿壅盛","脾虚","湿热痰浊壅滞","气虚","阳虚水湿内停"],"a":2,"e":"舌红而肿胀满口兼齿痕，为湿热痰浊壅滞舌体；脾虚者舌淡胖有齿痕而不红，可资鉴别。苔黄腻，脉滑数。"},{"q":"大便夹有不消化的食物，酸腐臭秽者，多因","o":["大肠湿热","寒湿内盛","伤食积滞","脾胃虚弱","肝胃不和"],"a":2,"e":"大便夹不消化食物、酸腐臭秽，为食积停滞、脾胃运化失职、浊气下趋所致，多伴脘腹胀满。"},{"q":"结脉的脉象是","o":["数而时一止，止无定数","缓而时一止，止有定数","缓而时一止，止无定数","时止有定数，良久方来","数而时一止，止有定数"],"a":2,"e":"结脉脉来迟缓，时有一止而止无定数；代脉止有定数，促脉则数而时止，三者以此相别。三脉虽均见歇止，主病各异。"},{"q":"下列何项可致小儿生长发育迟缓","o":["肾阴不足证","肾精不足证","肾阳虚证","脾肾亏虚证","肾气不足证"],"a":1,"e":"肾精不足，生长发育乏源，故小儿身材矮小、骨骼痿软、智力迟钝、囟门迟闭，成人则早衰。"},{"q":"两经或三经证候同时出现的是","o":["循经传","直中","合病","表里传","并病"],"a":2,"e":"两经或三经证候同时出现者称合病；一经证候未罢又见他经证候者为并病，与循经传不同。"},{"q":"脾气虚证与寒湿困脾证鉴别的要点症状是","o":["食欲不振","口淡不渴","便溏腹胀","苔白厚腻","脉缓"],"a":3,"e":"脾气虚证舌苔薄白，寒湿困脾则苔白厚腻，故舌苔为二者鉴别的要点，兼症亦可参合。苔之厚薄，可辨虚实。"},{"q":"大肠湿热证泻下的特点是","o":["里急后重","泻下酸腐","溏结不调","五更泄泻","大便腥臭"],"a":0,"e":"大肠湿热，湿热壅滞肠道、气机阻滞，故泻下黏冻、里急后重、肛门灼热，小便短黄。苔黄腻为湿热之征。"},{"q":"根据点刺所在部位推测邪热所在脏腑，如舌边有点刺，多为","o":["心火亢盛","胃肠热盛","肝胆火盛","气血壅滞","肺热炽盛"],"a":2,"e":"舌边属肝胆，故舌边有点刺者多为肝胆火盛；舌尖属心，舌中属脾胃，舌根属肾。舌尖点刺则属心火。"},{"q":"水逆证的呕吐特点是","o":["饮后即吐","吐利并作","朝食暮吐","吐物酸腐","呕吐如喷"],"a":0,"e":"水逆证为饮停于胃、水气上逆，故渴欲饮水而水入即吐，伴小便不利，属饮证之一。此为饮停于胃之征。"},{"q":"两颧潮红多属于","o":["肝火盛","心火盛","阳明热盛","阴虚内热","气虚发热"],"a":3,"e":"两颧潮红为阴虚内热、虚火上浮所致，午后颧红尤著，伴五心烦热、盗汗、舌红少苔。此为阴虚内热之征。"},{"q":"腰脊疼痛连及下肢者，多属","o":["风湿痹病","肾气亏虚","痰湿内阻","经络阻滞","带脉损伤"],"a":3,"e":"腰脊疼痛连及下肢，为邪阻经络、气血运行不畅所致，属经络阻滞，非肾虚之酸痛。痛处固定，按之痛甚。"},{"q":"大便灰白呈陶土色，多见于","o":["湿热或暑湿伤及胃肠","黄疸","热盛伤津","外感寒湿","饮食生冷"],"a":1,"e":"大便灰白如陶土，因胆道阻滞、胆汁不能下泄肠中，多见于黄疸，属胆道阻塞之征。此为胆道阻塞之征。"},{"q":"下列各项，属于湿热蕴脾证与寒湿困脾证共有的表现是","o":["面黄晦暗","便溏不爽","面黄鲜明","身热不扬","口苦口黏"],"a":1,"e":"湿热蕴脾与寒湿困脾均致脾运失职、湿滞肠道，故便溏不爽为二者共有表现，余症寒热各异。"},{"q":"病室散发烂苹果味，多属","o":["脏腑败坏","水肿晚期","消渴病晚期","瘟疫病","失血症"],"a":2,"e":"病室散发烂苹果味，为消渴病后期酮浊内蕴、脏腑气衰之危候，属病体气味异常。闻诊气味可助辨证。"},{"q":"代脉的主病是","o":["元气离散","气血两虚","诸虚劳损","失精亡血","脏气衰微"],"a":4,"e":"代脉来缓而时一止、止有定数，主脏气衰微，亦见于疼痛、惊恐、跌打损伤，其止有规律可循。"},{"q":"与气虚兼并的虚证，哪项少见","o":["气虚髓亏","津气亏虚","气阴两虚","气血两虚","阳气亏虚"],"a":0,"e":"气虚常与血虚、阴虚、阳虚、津亏并见而为气血、气阴、阳气之虚，气虚髓亏临床少见。故气虚髓亏较为少见。"},{"q":"颤动舌的临床意义为","o":["中风先兆","心脾有热","肝风内动","热入心包","风痰阻络"],"a":2,"e":"颤动舌由肝风内动、筋脉失养所致，舌体震颤抖动不宁，见于热盛、阳亢、阴亏、血虚。脉多弦，舌多颤动。"},{"q":"肛门气坠，常于劳累或排便后加重，多属","o":["湿热下注","肝气郁结","脾虚气陷","寒滞肝脉","大肠湿热"],"a":2,"e":"肛门气坠、劳累或排便后加重，为中气下陷、脾虚气陷、升举无权所致，甚则脱肛。此为气陷下泄之征。"},{"q":"咳声轻清低微证属","o":["风寒束表","风热犯肺","肺气亏损","肺阴不足","燥邪犯肺"],"a":2,"e":"咳声轻清低微为肺气虚损、宣降无力，属虚证，伴气短乏力；咳声重浊紧闷则属实证。其声低怯，气短乏力。"},{"q":"本已极度衰竭，突然出现神气暂时“好转”的是","o":["得神","少神","失神","假神","神乱"],"a":3,"e":"假神为久病重病之人突然精神转佳、言语不休、欲进饮食，是阴阳即将离决的危候，又称回光返照。"},{"q":"芤脉的脉象特征是","o":["轻按搏指，中空外坚","浮大而软，按之中空","脉位表浅，细软无力","三部脉举之无力，按之空虚","沉细无力"],"a":1,"e":"芤脉浮大中空，如按葱管，主失血与伤阴，因血脱于外、脉道失充而张力尚存，多见于大失血后。"},{"q":"具有神昏谵语，躁扰不宁，或壮热神昏，呼吸气粗，喉中痰鸣等临床表现的属于","o":["神乱","少神","得神","假神","失神"],"a":4,"e":"失神见神昏谵语、躁扰不宁、壮热息粗、喉中痰鸣，为邪热内陷心包、正气大伤。此为邪热内陷心包。"},{"q":"下列哪项对诊断心肾不交证最有意义","o":["心悸失眠，头晕目眩","心悸怔忡，肢肿尿少","心烦失眠，腰酸盗汗","嗜睡神疲，心悸肢肿","眩晕耳鸣，腰膝酸软"],"a":2,"e":"心肾不交为水火不济、心火偏亢而肾水不足，故心烦失眠与腰酸盗汗并见，为辨证要点。心火得降则诸症自平。"},{"q":"外邪最易侵袭何经","o":["厥阴经","太阳经","阳明经","太阴经","少阳经"],"a":1,"e":"太阳经主一身之表，为诸经之藩篱，故外邪侵袭首犯太阳经，见恶寒发热、头身痛、脉浮。"},{"q":"下列各项，不属胃气虚证的临床表现的是","o":["胃脘冷痛喜温","胃脘痞闷","恶心呕逆","食后脘胀更甚","舌淡苔白脉弱"],"a":0,"e":"胃气虚见胃脘痞闷、食少乏味、恶心呕逆、食后胀甚；胃脘冷痛喜温属胃阳虚，为辨证关键。"},{"q":"下列哪项可视作血寒证","o":["寒凝肠胃证","寒凝胞宫证","寒邪束表证","寒邪客肺证","寒凝关节证"],"a":1,"e":"血寒证为寒凝血脉，寒凝胞宫致少腹冷痛、月经后期、痛经、色暗有块，故属血寒。此为寒凝血脉之征。"},{"q":"热证的辨证要点有","o":["畏寒","口淡不渴","小便清长","面赤心烦","恶心呕吐"],"a":3,"e":"热证以面赤、心烦、口渴、舌红、脉数为主；畏寒、口淡不渴、小便清长为寒证之象。苔黄燥，脉数有力。"},{"q":"老人头摇不能自主，最常见的原因是","o":["肝阳上亢","气血两虚","肾精亏损","高热伤津","阴虚火旺"],"a":1,"e":"头摇不能自主属虚风内动，老年气血两虚，筋脉失于濡养，血虚生风而致。肝阳上亢、高热伤津所致者多伴眩晕、壮热等实象，与老年慢性头摇不同。"},{"q":"下列除哪项外脉率均较快","o":["促脉","结脉","疾脉","动脉","数脉"],"a":1,"e":"结脉为脉来缓慢而时有一止，止无定数，脉率不数。促、疾、动、数四脉均以脉率增快为共同特征，故结脉独异。"},{"q":"呕吐物清稀无臭，或清水者，多因","o":["胃阳不足","寒邪犯胃","食积内停","胃阳不足或寒邪犯胃","胃有积热"],"a":3,"e":"吐物清稀无臭或纯为清水，属寒饮内停：胃阳不足则水谷不化，寒邪犯胃则胃气上逆，二者皆可致之。胃有积热者吐物臭秽，食积者吐物酸腐夹不化食物。"},{"q":"对诊断肾精不足证最无意义的是","o":["经闭不孕","耳鸣耳聋","齿摇发脱","烦热盗汗","健忘恍惚"],"a":3,"e":"烦热盗汗为阴虚内热之象，属肾阴虚证。肾精不足主生长发育与生殖障碍，见经闭不孕、耳鸣耳聋、齿摇发脱、健忘恍惚，而无明显虚热表现。"},{"q":"下列哪个病证不属于痰火扰神证临床表现","o":["失眠","心烦","癫","神昏谵语","狂"],"a":2,"e":"痰火扰神证属阳热实证，见狂躁妄动、神昏谵语、心烦失眠。癫为痰气郁结、蒙蔽心神之阴证，静而少动，与痰火扰神之阳动之象相反。"},{"q":"下列选项中，均具有脉位表浅特点的脉象是","o":["浮脉，洪脉，革脉，濡脉","弱脉，长脉，弦脉，虚脉","浮脉，散脉，弦脉，弱脉","弱脉，革脉，伏脉，芤脉","牢脉，弱脉，浮脉，短脉"],"a":0,"e":"浮脉举之有余、按之不足；洪脉浮大有力；革脉浮而搏指、中空外坚；濡脉浮细而软，四者脉位皆浅。弱脉沉细而软、伏脉推筋着骨乃得，脉位皆沉。"},{"q":"小儿食指络脉色紫红主病","o":["表热","内热","血瘀证","惊风证","气血亏虚"],"a":1,"e":"络脉色泽辨病性：鲜红主表热，紫红为热邪入里，主内热；青色主惊风，紫黑主血瘀，淡白主气血亏虚。"},{"q":"腹部按之肌肤凉而喜温者，为","o":["寒证","热证","虚证","实证","饮证"],"a":0,"e":"按诊辨寒热：腹部肌肤凉而喜温者为寒证，多因阳气不足或寒邪内侵；按之灼热喜凉者为热证。虚证以按之痛减、腹壁柔软为特点。"},{"q":"下列除哪项外，均为头晕的常见原因","o":["气血两虚","痰湿内阻","肺阴不足","肝阳上亢","肝火上炎"],"a":2,"e":"头晕多因气血两虚、痰湿内阻、肝阳上亢、肝火上炎、肾精不足，病位在肝脾肾。肺阴不足以干咳少痰、咽干音哑为主，不致头晕。"},{"q":"弱脉的脉象是","o":["脉细如线","沉而细软","极细极软","浮而细软","脉微欲绝"],"a":1,"e":"弱脉沉细而软，按之乃得，应指无力，主气血两虚、阳气衰微。濡脉浮细而软，一沉一浮为二者鉴别要点；微脉则极细极软、似有似无。"},{"q":"呕吐物酸腐夹杂不消化食物，多属","o":["痰饮","寒呕","胃痈","热呕","食积"],"a":4,"e":"吐物酸腐夹不消化食物，为宿食停滞、胃气上逆，属食积。痰饮者吐清稀痰涎，寒呕者吐清水，热呕者吐物臭秽而黄。"},{"q":"沉而细软，应指无力是","o":["濡脉","微脉","细脉","弱脉","涩脉"],"a":3,"e":"弱脉脉体细软而沉，应指无力，主气血不足、阳气虚衰。濡脉浮细而软，微脉极细极软、似有似无，细脉虽细而脉形分明。"},{"q":"水肿以眼睑头面浮肿，上半身肿甚为特点者属于","o":["心阳不足证","风水搏肺证","脾虚失运证","肾虚水泛证","脾肾阳虚证"],"a":1,"e":"风水搏肺证因风邪袭肺、宣降失司、水道不利，肿起眼睑头面而偏于上半身，来势迅速。肾虚水泛多从下肢足跗肿起，脾虚失运则肿势缓而周身俱肿。"},{"q":"脉在皮肤，浮数之极，至数不清，浮泛无根，称为","o":["鱼翔脉","虾游脉","釜沸脉","屋漏脉","弹石脉"],"a":2,"e":"釜沸脉浮数之极，至数不清，如釜中沸水浮泛无根，主三阳热极、阴液枯竭。鱼翔脉在皮肤、头定尾摇，虾游脉来则跃去、须臾又来。"},{"q":"肺气虚证的咳喘特点最主要的是","o":["咳喘胸闷，喉中痰鸣","咳喘痰多，色白稀薄","咳喘无力，声低息微","咳喘痰少，不易咳吐","咳嗽痰多，色黄质稠"],"a":2,"e":"肺气虚证肺主气功能减退，故咳喘无力、声低息微、气短懒言，伴自汗畏风、易感外邪。痰多色白稀薄属寒痰阻肺，痰黄稠者为热。"},{"q":"循衣摸床属于","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"循衣摸床、撮空理线是神明失守、病情危笃之象，属失神。假神为久病重病本已失神，忽现精神转佳、言语不休，属精气衰竭、阴阳即将离决。"},{"q":"釜沸脉的主病是","o":["孤阳无依，躁动不安","三阴寒极，阳亡于外","三阳热极，阴液枯竭","肾与命门之气皆亡","胃气营卫将绝"],"a":2,"e":"釜沸脉主三阳热极、阴液枯竭，热盛阴涸而阳气浮越，故脉浮数无根。虾游脉主孤阳无依，屋漏脉主胃气营卫将绝，弹石脉主肾与命门之气皆亡。"},{"q":"热证的形成原因不包括","o":["外感热邪","体内阳盛","阴液亏虚","阳气不足","寒湿郁久"],"a":3,"e":"热证由外感热邪、阳盛有余、阴虚不能制阳或寒湿郁久化热而成。阳气不足则温煦无力，是寒证尤其虚寒证的形成基础。"},{"q":"自汗与盗汗并见的常见原因是","o":["血液亏虚","阳气不足","阴液亏虚","气阴两虚","阴血亏虚"],"a":3,"e":"自汗属气虚、卫外不固，盗汗属阴虚、寐时阳入于里而虚热迫津。二者并见提示气阴两虚，气虚则表疏，阴虚则内热。"},{"q":"滑脉的脉象特征是","o":["来盛去衰","厥厥动摇","浮大中空","往来流利","如轻刀刮竹"],"a":3,"e":"滑脉往来流利、应指圆滑，如珠走盘，主痰饮、食积、实热，妇人妊娠亦见。涩脉往来艰涩，如轻刀刮竹，与滑脉正相反。"},{"q":"真热假寒与真寒假热证均可见","o":["口渴喜饮","小便清长","下利臭秽","面色浮红如妆","四肢厥冷"],"a":4,"e":"真热假寒为热盛阳郁、格阴于外，真寒假热为阴寒内盛、格阳于外，阳气均不达四末，故皆见四肢厥冷。面赤如妆、口渴喜热饮为真寒假热所独见。"},{"q":"阳气暴脱者多见","o":["面色淡白","面色㿠白","面白虚浮","面色苍白","面色青黑"],"a":3,"e":"阳气暴脱，脉络骤失温运，血不上荣，故面色苍白，每伴大汗淋漓、四肢厥冷、脉微欲绝。面色㿠白为阳虚水泛，淡白为气血不足，起病皆较缓。"},{"q":"舌苔由厚转薄为","o":["由实转虚","邪气入里","胃气暴绝","正气胜邪，病趋好转","热邪伤津而病势加重"],"a":3,"e":"舌苔厚薄反映邪气深浅与邪正消长：由厚转薄为邪气渐退、正气胜邪，病势向愈；由薄转厚则邪气渐盛、病位深入。"},{"q":"下述哪项不是血热证的表现","o":["月经量多色淡","身热面赤发斑","肌肤生疔痈疮疖","温病之血分证","迫血妄行而出血"],"a":0,"e":"血热证热入血分、迫血妄行，见身热面赤发斑、出血色深红、肌肤生疔痈疮疖，温病血分证即属此。月经量多而色淡为气虚不能摄血，与血热不符。"},{"q":"带下臭秽而黄稠者，多属","o":["寒湿","湿热","癌肿","痰饮","气滞"],"a":1,"e":"带下色黄稠黏、臭秽，为湿热下注。色白清稀无臭属寒湿，色白质稠如豆渣多属脾虚湿盛，五色杂下、臭秽难闻须警惕癌肿。"},{"q":"点刺舌常与哪项并见","o":["青舌","紫舌","红舌","绛舌","淡白舌"],"a":2,"e":"点刺舌为邪热亢盛、气血壅滞之象，热盛则舌色红，故点刺多与红舌并见；热极伤阴、营血受灼时舌转绛，点刺更为显露。"},{"q":"雀啄脉的脉象是","o":["脉在皮肤，时而跃然而去，须臾又来","短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","如屋漏残滴，良久一滴","脉在筋肉间，连连数急，三五不调，止而复作，如雀啄食状"],"a":4,"e":"雀啄脉在筋肉之间，连连数急，三五不调，止而复作，如雀啄食之状，主脾胃之气将绝。屋漏脉如残滴良久一滴，弹石脉如指弹石，皆为真脏脉。"},{"q":"肝胆湿热之呕吐物常为","o":["吐物酸腐","吐清稀痰涎","吐黄绿苦水","呕吐鲜血夹食物残渣","呕吐清水痰涎"],"a":2,"e":"肝胆湿热，胆汁上溢，故呕吐黄绿苦水，伴口苦、胁痛。吐物酸腐为食积，吐清稀痰涎为痰饮，吐鲜血夹食物残渣多见于胃络损伤。"},{"q":"下列各项，可出现日晡潮热的是","o":["湿遏热伏","热入营血","阳明经证","阳明腑证","阴虚内热"],"a":3,"e":"日晡潮热指午后申时热势增高，为阳明腑实、燥屎内结，常伴腹满硬痛、便秘、谵语。湿温潮热以身热不扬为特点，阴虚潮热则见骨蒸盗汗。"},{"q":"下列关于小儿食指络脉诊法描述错误的是","o":["小儿食指络脉诊法适用于3岁以下的小孩","食指络脉的显现与分布，可分为风、气、命三关","若络脉透过三关直达指端者，称为“透关射甲”","从风关向气关、命关直推","其络脉色淡为虚，色滞为实"],"a":3,"e":"诊络脉须用拇指从命关向风关方向轻推，使络脉显露而色泽真实，逆向直推则气血壅滞、色泽失真。三关定位、透关射甲及色淡为虚、色滞为实之说均正确。"},{"q":"“八纲”一词正式提出首见于","o":["《伤寒杂病论》","《景岳全书》","《诸病源候论》","《伤寒质难》","《伤寒六书》"],"a":3,"e":"“八纲”一词由祝味菊在《伤寒质难》中正式提出。八纲内容虽源于《内经》，历代医家多有阐发，如《景岳全书》论阴阳表里寒热虚实，然未以此名统称。"},{"q":"腹部肿块推之不移，痛有定处，为","o":["癥积","瘕聚","痞满","结胸","肠痈"],"a":0,"e":"癥积为有形之块，固定不移，痛有定处，属血分病，病在脏。瘕聚则聚散无常、推之移动、痛无定处，属气分病，二者以定与不定相区别。"},{"q":"带下夹杂有血液，黏稠臭秽者，属于","o":["脾虚湿困","脾胃阳虚","寒湿下注","肝经湿热","阴虚火旺"],"a":3,"e":"带下赤白相兼、黏稠臭秽，为肝经湿热下注、损伤血络。寒湿下注者带下清稀色白，脾虚湿困者量多色白而无臭，阴虚火旺者多赤白带而质稀。"},{"q":"两眦赤痛，多属","o":["肺火","外感风热","心火上炎","脾有湿热","肝经风热"],"a":2,"e":"目眦属血轮，内应于心，两眦赤痛为心火上炎。白睛赤为肺火，胞睑红肿为脾经湿热，目珠疼痛连及巅顶多属肝经风热。"},{"q":"下列不属于麻疹逆症的表现是","o":["疹点依出疹的先后逐渐回隐","壮热无汗","疹点不能透发","疹点色淡红而黯，或赤紫黯滞，或白而不红","疹点突然隐没，神昏喘息"],"a":0,"e":"麻疹顺证疹点依序透发，先耳后发际、头面，渐及胸腹四肢，疹色红润，之后依先后次序回隐。壮热无汗、疹不透发、色紫黯滞或骤然隐没伴神昏喘息，皆属逆证。"},{"q":"可辨为“表热里寒”的是","o":["恶寒发热，舌淡苔白","恶寒发热，咳喘痰黄","恶寒发热，神疲气短","恶寒发热，脘腹冷痛","发热重恶寒轻，便溏尿清"],"a":4,"e":"表热里寒为表有热而里有寒：发热重、恶寒轻属表热，便溏、小便清长属里寒。恶寒发热伴脘腹冷痛者表证性质未明，不足以定为表热。"},{"q":"虫积肠道证最不易见到的症状是","o":["嗜食异物","大便秘结","大便排虫","面黄体瘦","面见白斑"],"a":1,"e":"虫积肠道证见脐周腹痛时作、嗜食异物、面黄体瘦、面部白斑、大便排虫，虫扰气机多致便溏不调。大便秘结非其常见表现，多属肠燥津亏或腑实。"},{"q":"左少腹作痛，按之累累有硬块者为","o":["虫积","肠痈","宿粪","癥积","痞满"],"a":2,"e":"左少腹按之累累有硬块而痛，为燥屎内结于肠，属宿粪。肠痈以右少腹痛、拒按、反跳痛为主，癥积之块固定不移而无便结之象。"},{"q":"脏腑病变反映于舌面，其中舌两边属","o":["心肺","三焦","脾胃","肝胆","肾"],"a":3,"e":"舌面分候脏腑：舌尖属心肺，舌中属脾胃，舌边属肝胆，舌根属肾。故舌两边之变化多反映肝胆病变。"},{"q":"风邪的性质和致病特点有","o":["为百病之长","生风动血","性黏滞","易伤津液","性收引"],"a":0,"e":"风为阳邪，轻扬开泄，善行数变，为百病之长，常为外邪致病的先导。生风动血属热邪，性黏滞属湿邪，易伤津液属燥邪，性收引属寒邪。"},{"q":"面部脏腑分候中，左颊候","o":["心","肝","脾","肺","肾"],"a":1,"e":"面部色诊分候：左颊候肝，右颊候肺，额部候心，鼻部候脾，下颏候肾。故左颊色泽变化多反映肝的病变。"},{"q":"中焦湿热郁蒸所致的异常汗出是","o":["手足心汗","阴部汗出","心胸汗多","半身汗出","脘腹汗多"],"a":0,"e":"手足心汗多因脾胃湿热郁蒸或阴经郁热，脾主四肢，湿热旁达四末而汗出。心胸汗多属心脾两虚或心肾不交，半身汗出多为风痰或营卫不调。"},{"q":"受气候的影响，平脉在夏季应","o":["稍弦","稍洪","稍浮","稍沉","稍缓"],"a":1,"e":"脉象随四时生变：春脉微弦，夏脉微洪，秋脉微浮，冬脉微沉，此为平脉应时之象。夏季阳气隆盛，气血充盛于外，故脉来稍洪。"},{"q":"濡脉的主病为","o":["痰证","寒证","水饮","虚证","食滞"],"a":3,"e":"濡脉浮细而软，轻取即得，重按不显，主虚证与湿证。精血亏虚则脉道不充，脾虚湿困则阳气被遏，脉皆浮软无力。"},{"q":"正常络脉的特点不包括","o":["隐现于风关内","淡紫色","形态多为斜形、单支","粗细适中","淡红色"],"a":4,"e":"正常小儿络脉隐现于风关之内，色泽淡紫而红黄相兼，粗细适中，形态多为斜形单支。色鲜红者主表热，色泽变化方具诊断意义。"},{"q":"肾虚面色为","o":["赤色","黄色","青色","白色","黑色"],"a":4,"e":"五色主病：青主肝病与寒痛瘀，赤主热，黄主脾虚湿，白主虚寒失血，黑主肾虚、寒证、水饮与瘀血。肾虚本色外露，故面色黑。"},{"q":"“有根”之脉象是指","o":["不浮不沉","节律一致","不快不慢","和缓有力","尺部沉取有力"],"a":4,"e":"脉之有根指尺部沉取有力，反映肾气未竭，为脉象胃、神、根三要素之一。有胃为徐和从容，有神为柔和有力、节律整齐。"},{"q":"阳虚证的最典型症状是","o":["面色淡白","口淡不渴","大便稀溏","无汗或少汗","畏寒喜暖"],"a":4,"e":"阳虚则温煦失职，故畏寒喜暖为最主要表现，伴面色㿠白、神疲乏力、小便清长、便溏、舌淡脉弱。口淡不渴、便溏虽常见，特异性不及畏寒喜暖。"},{"q":"提示疾病发展转折点的是","o":["自汗","盗汗","蒸汗","冷汗","战汗"],"a":4,"e":"战汗为正邪交争剧烈之象，先恶寒战栗，继而汗出。汗后脉静身凉为邪去正安、病趋好转；汗后烦躁脉疾为邪盛正衰，故为疾病转折点。"},{"q":"临床少见的证候转化是","o":["寒证转化为热证","热证转化为寒证","实证转化为虚证","表证转化为里证","虚证转化为实证"],"a":4,"e":"证候转化以实证转虚、表证入里、寒热互转多见。虚证转实须在正虚基础上复感实邪，或虚证日久导致痰瘀水停，临床较为少见。"},{"q":"神识不清，语言重复，时断时续，语声低弱者称为","o":["谵语","独语","郑声","错语","呓语"],"a":2,"e":"郑声为神识不清、语言重复、时断时续、语声低弱，属久病脏气衰竭、心神散乱之虚证。谵语为神昏而语声高亢有力，属实热扰心。"},{"q":"下列哪项不属于舌体强硬的主病","o":["热入心包","高热伤津","风痰阻络","寒凝筋脉","中风或中风先兆"],"a":3,"e":"舌体强硬因舌络失养或痰瘀阻络，见于热入心包、高热伤津、风痰阻络及中风或中风先兆。寒凝筋脉多致舌体卷缩、脉络拘急，不属强硬。"},{"q":"三焦病证的传变，其中的“逆传”是指","o":["阳明胃传入太阴肺","太阴脾传人太阴肺","从肺卫而传入心包","阳明胃经传入心包","中焦脾胃传入上焦"],"a":2,"e":"三焦传变有顺逆之分：由上焦手太阴肺顺传中焦阳明为顺传；由肺卫不经中焦而径入心包，病情急重，称为逆传。"},{"q":"屋漏脉的脉象是","o":["脉在皮肤，时而跃然而去，须臾又来","短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","如釜中沸水，浮泛无根","脉在皮肤，头定尾摇，似有似无"],"a":2,"e":"屋漏脉如屋漏残滴，良久一滴，脉来极慢而间歇不匀，主胃气营卫将绝。虾游脉时而跃然而去、须臾又来，二者皆属真脏脉，主病危重。"},{"q":"下列各项，属于湿热蕴脾证的临床表现的是","o":["面色萎黄","面黄虚浮","面色苍黄","面黄鲜明如橘皮色","面黄晦黯如烟熏"],"a":3,"e":"湿热蕴脾，胆汁溢于肌肤，故身目俱黄而黄色鲜明如橘皮，属阳黄。面色萎黄属脾虚气血不足，面黄虚浮为黄胖，晦黯如烟熏属寒湿阴黄。"},{"q":"下列哪项是少阴热化证中“心烦不得眠”的病机","o":["余热未清，留扰胸膈","阴虚热扰，心神不宁","阴血不足，心失所养","寒郁化热，扰乱心神","心火炽盛，侵扰心神"],"a":1,"e":"少阴热化证为肾阴亏虚、心火偏亢，阴虚不能上济，虚热扰及心神，故心烦不得眠，伴口燥咽干、舌红少苔、脉细数。"},{"q":"面目肌肤俱黄，黄而晦暗如烟熏色属于","o":["萎黄","黄胖","阴黄","阳黄","苍黄"],"a":2,"e":"阴黄由寒湿困脾、胆汁不循常道而溢，黄色晦黯如烟熏，伴畏寒、便溏、舌淡苔白腻。阳黄为湿热所致，黄色鲜明如橘皮。"},{"q":"由里出表提示","o":["机体抗邪能力强盛","里证转化为表证","治疗护理适当","邪有出路，病情有向愈之势","表里同病"],"a":3,"e":"病邪由里透达于表，说明正气渐复、抗邪有力，邪有外出之路，病势向愈。若里证不减而表证又起，则为表里同病，不属由里出表。"},{"q":"风疹的病因病机是","o":["外感风热时邪","气分热盛","风寒湿邪侵犯肌表","湿郁汗出不彻","邪热入营"],"a":0,"e":"风疹由外感风热时邪，与气血相搏，郁于肌腠，发于皮肤，疹色淡红、细小稀疏、瘙痒，伴发热、微恶风。湿郁汗出不彻所见为白㾦。"},{"q":"病人舌苔厚腻骤然消退，属于","o":["正气渐复病好转","热势加重津液伤","正不胜邪胃气绝","邪气由表入里","病情由虚转实"],"a":2,"e":"舌苔骤退而舌面光剥无苔，是胃气衰败、不能蒸化生苔，属正不胜邪之危候。正气渐复者苔由厚渐薄，而不至骤然消退。"},{"q":"面色黑而干焦多属","o":["肾阴亏虚","肾阳亏虚","肾气亏虚","瘀血阻络","水饮内停"],"a":0,"e":"黑而干焦为肾阴亏耗、虚火灼津，肌肤失润；黑而黯淡多属肾阳虚衰；眼眶周围发黑常为肾虚水饮或寒湿带下。"},{"q":"后囟门出生很小或已闭合，至迟闭合时间约于出生后","o":["12~18周","5~6周","10~12周","6~8周","12~16周"],"a":3,"e":"后囟门多在出生时已闭合或很小，最迟于出生后6～8周闭合；前囟门约在出生后12～18个月闭合。囟门迟闭多见于肾气不足、发育不良。"},{"q":"颈侧颌下有肿块如豆，累累如串珠者，称为","o":["发颐","瘰疬","瘿瘤","痰核","梅核气"],"a":1,"e":"瘰疬生于颈侧颌下，肿块如豆，累累如串珠，多因肺肾阴虚、痰火凝结。瘿瘤生于颈前结喉处，随吞咽移动；痰核为皮下圆滑肿块，不红不痛。"},{"q":"因情志过极导致的“气闭”，最突出的表现是","o":["突然晕厥","胀闷不舒","神情不宁","胀痛窜痛","脉弦"],"a":0,"e":"情志过极则气机闭塞，清窍不通，故突然昏厥、不省人事，属气闭之实证。胀闷不舒、胀痛走窜为气滞，非气闭之闭阻清窍。"},{"q":"因痰浊、瘀血、砂石、寄生虫等阻塞所致的“气闭”，最突出的表现是","o":["突然晕厥","胀闷不舒","神情不宁","绞痛阵作","脉弦"],"a":3,"e":"有形实邪阻塞经络，气血骤闭不通，故绞痛阵作、痛势剧烈而拒按。突然晕厥为情志过极、气闭清窍所致，二者虽同属气闭而病位不同。"},{"q":"心血虚证的脉象是","o":["脉细数","脉细弦","脉细弱","脉浮细","脉沉紧"],"a":2,"e":"心血虚证心血不足，脉道充盈减少，故脉细而弱，伴心悸、失眠多梦、面色淡白、舌淡。脉细数属阴虚内热，脉细弦多见于肝血虚。"},{"q":"肝郁气滞胁痛的特点是","o":["隐痛","灼痛","胀痛","掣痛","绞痛"],"a":2,"e":"肝气郁结，气机不畅，胁络失于疏泄，故胁肋胀痛、走窜不定，随情志变化而增减。灼痛属肝火，隐痛属肝阴不足，刺痛属瘀血阻络。"},{"q":"下列哪项不属脉力不足的脉象","o":["弱脉","濡脉","牢脉","微脉","虚脉"],"a":2,"e":"弱、濡、微、虚四脉皆以脉力软弱无力为特征，主虚证。牢脉沉取实大弦长、坚牢不移，属脉力有余，主阴寒内积、疝气癥积。"},{"q":"湿温潮热的特点是","o":["午后低热","日晡热甚","身热不扬","骨蒸发热","入夜热甚"],"a":2,"e":"湿温潮热以身热不扬为特点，午后热甚，汗出而热不解，伴头身困重、苔腻，因湿遏热伏、热难透达。日晡热甚属阳明腑实，骨蒸发热属阴虚。"},{"q":"望神时观察的要点是神情、气色、体态和","o":["语言","舌象","眼神","呼吸","脉象"],"a":2,"e":"望神以目光、神情、气色、体态为主要内容，其中眼神最为关键。目光精彩内含为有神，目暗睛迷、瞳神呆滞为失神。"},{"q":"导致消谷善饥的病机是","o":["肝胆湿热","胃火炽盛","脾胃虚弱","虫积肠道","胃阴不足"],"a":1,"e":"胃火炽盛，腐熟太过，故消谷善饥，常伴口渴喜冷、口臭、齿龈肿痛、便秘。胃阴不足亦见多食，但兼饥不欲食、口燥咽干，程度较轻。"},{"q":"食少纳呆，消瘦乏力，腹胀便溏，食后胀甚，证属","o":["寒湿困脾证","脾气虚证","胃气虚证","肝胃不和证","肝郁脾虚证"],"a":1,"e":"脾气虚证脾失健运，故食少纳呆、腹胀便溏、食后胀甚，气血生化不足则消瘦乏力、面色萎黄、舌淡脉弱。寒湿困脾当有苔白腻、头身困重。"},{"q":"谵语的病机是","o":["心气大伤","热扰心神","心气不足","痰蒙心神","瘀阻心窍"],"a":1,"e":"谵语为神志不清、语声高亢、胡言乱语，属邪热亢盛、扰乱心神之实证，多见于温病热入营血或阳明腑实。郑声为脏气衰竭、心神散乱之虚证。"},{"q":"对正常舌象的诊断，下列哪项是错误的","o":["舌体柔软","舌体活动自如","舌淡嫩少苔","舌色淡红","舌苔薄白"],"a":2,"e":"正常舌象为淡红舌、薄白苔，舌体柔软、活动自如、荣润有神，胖瘦老嫩适中。舌淡嫩少苔提示气血不足或阴虚，属病舌。"},{"q":"青如翠羽是","o":["主色","客色","善色","恶色","常色"],"a":2,"e":"五色以明润光泽为善色，枯槁晦暗为恶色。青如翠羽、赤如鸡冠、黄如蟹腹、白如豕膏、黑如乌羽，皆为本脏色兼有胃气之善色。"},{"q":"肝血虚和肝阴虚的共同临床表现是","o":["面色红赤","视力减退","面色淡白","潮热盗汗","舌绛"],"a":1,"e":"肝开窍于目，肝血虚则目失濡养，肝阴虚则阴精不能上承，二者皆见视力减退、头晕目眩。面色淡白、舌淡属血虚，潮热盗汗、舌红少津属阴虚。"},{"q":"结、代、促脉，其脉象的共同特点是","o":["脉来时一止","止有定数","止无定数","脉来缓慢","脉来急促"],"a":0,"e":"结、代、促三脉均以脉来时有歇止为共同特点。结脉缓而时止、止无定数，代脉止有定数，促脉数而时止、止无定数，脉率与歇止规律各异。"},{"q":"主气分热盛的脉象是","o":["洪脉","数脉","疾脉","牢脉","动脉"],"a":0,"e":"洪脉脉体阔大、充实有力、来盛去衰，为阳气有余、气分热盛之象，见壮热、烦渴、大汗、脉洪大。数脉主热而不专主气分，疾脉主热极阴竭。"},{"q":"病人但卧不能坐，坐则晕眩，多属","o":["肺胀","哮病","肺气壅滞","痰饮停肺","气血俱虚"],"a":4,"e":"但卧不能坐、坐则晕眩，因气血俱虚、清阳不升，脑失所养，属虚证。肺胀、哮病、痰饮停肺者多但坐不得卧，卧则气逆喘甚，与之相反。"},{"q":"能够判断疼痛虚实的方法是","o":["痛处喜温或喜凉","痛时姿势","喜按或拒按","疼痛部位","痛处颜色"],"a":2,"e":"痛而喜按者为虚，按之气血暂得通畅；痛而拒按者为实，按之邪实壅滞更甚。痛处喜温多寒、喜凉多热，属辨寒热而非辨虚实。"},{"q":"痰色白，质稠量多，滑而易咯出者，多属","o":["寒痰","热痰","燥痰","湿痰","风痰"],"a":3,"e":"湿痰色白、质稠量多、滑而易咯，因脾虚湿盛、湿聚成痰。寒痰色白清稀，热痰色黄黏稠，燥痰量少难咯，风痰痰白而多泡沫。"},{"q":"苔白厚如积粉，多由于","o":["痰湿、食积内阻","表证未罢，内传入里","外感秽浊湿邪与热毒相结合","阴虚火旺，虚火灼津","痰浊湿热内蕴"],"a":2,"e":"苔白厚如积粉、扣之不燥，为积粉苔，由外感秽浊湿邪与热毒相搏、湿遏热伏所致，多见于瘟疫初起。苔白厚腻而滑者属痰湿食积内阻。"},{"q":"皮肤干枯粗糙，状若鱼鳞，多因","o":["阴津已伤","营血亏虚","外邪侵袭","气血阻滞","瘀血日久"],"a":4,"e":"皮肤干枯粗糙、状若鱼鳞，称肌肤甲错，为瘀血内阻、新血不生、肌肤失养所致。营血亏虚者肌肤虽干燥而少甲错，多伴面色淡白、唇甲色淡。"},{"q":"小便频数，黄赤急迫者，属于","o":["肾阳不足","肾气不固","肾阴亏虚","膀胱湿热","瘀血阻滞"],"a":3,"e":"膀胱湿热，气化不利，故小便频数、色黄赤、急迫灼痛，甚或尿血、尿有砂石。肾气不固者小便频数而清长，甚则余沥不尽。"},{"q":"津液的生成与输布，主要与下列哪一项所示脏腑的关系最密切","o":["脾、胃、肺","肺、脾、肾","肺、三焦、肝","肺、肝、膀胱","三焦、膀胱、肺"],"a":1,"e":"津液由脾胃运化水谷而生成，经脾气散精、肺主宣降通调水道而上腾下输，肾主水、司开阖而主津液代谢，故以肺脾肾三脏关系最密切。"},{"q":"以腹部硬满疼痛拒按、便秘为主要表现的证是","o":["胃肠气滞证","肠热腑实证","肠燥津亏证","虫积肠道证","胃热炽盛证"],"a":1,"e":"肠热腑实证为邪热与燥屎互结、腑气不通，故腹部硬满疼痛拒按、大便秘结，伴日晡潮热、谵语、舌红苔黄燥。肠燥津亏者腹无所苦。"},{"q":"乳痈多发于女性","o":["青春期","妊娠期","哺乳期","更年期","老年"],"a":2,"e":"乳痈多因乳汁淤积、肝胃郁热或外感邪毒，好发于产后哺乳期妇女。乳癖多见于中年妇女，乳岩多发于绝经前后。"},{"q":"咳声不扬，痰稠色黄证属","o":["风热袭表","寒邪客肺","痰湿阻肺","痰热壅肺","阴虚肺燥"],"a":3,"e":"痰热壅肺，热灼津液成痰，故咳声不扬、痰稠色黄，伴胸闷、发热、舌红苔黄腻。风热袭表者表证明显，阴虚肺燥者痰少黏而干咳。"},{"q":"下列哪项不属影响脉象的生理性因素","o":["四季气候","地理环境","性别","年龄","体位"],"a":4,"e":"脉象受年龄、性别、体格、情志、劳逸、饮食及四时气候、地理环境等生理因素影响。体位改变属诊脉操作规范，须平臂仰掌，非影响脉象的生理因素。"},{"q":"促脉的脉象是","o":["数而一止，止无定数","数而一止，止有定数","缓而时止，止无定数","缓而时止，止有定数","止有定数，良久方来"],"a":0,"e":"促脉脉来数而时有一止，止无定数，主阳盛实热、气血痰食停滞，亦见于脏气衰败。结脉缓而时止、止无定数，代脉则止有定数。"},{"q":"小儿食指络脉色青主病","o":["惊风证","热证","血瘀证","表证","气血亏虚"],"a":0,"e":"络脉色青主惊风，青而紫黑者主血络郁闭、病势危重。色鲜红主表热，紫红主内热，淡白主气血亏虚，紫黑主血瘀。"},{"q":"可见咳吐脓血腥臭痰表现的证是","o":["风水搏肺证","风寒犯肺证","寒痰阻肺证","饮停胸胁证","痰热壅肺证"],"a":4,"e":"痰热壅肺，热壅血瘀，肉腐血败成痈，故咳吐脓血腥臭痰，伴胸痛、发热、舌红苔黄腻，即肺痈之征。饮停胸胁者咳唾引痛而无脓血。"},{"q":"午后两颧潮红者属","o":["气虚证","虚热证","血虚证","戴阳证","实热证"],"a":1,"e":"午后两颧潮红为阴虚阳亢、虚火上炎之象，属虚热证，伴五心烦热、盗汗、舌红少苔。面赤如妆、游移不定者为戴阳证，属虚寒危候。"},{"q":"气滞血瘀证的疼痛性质","o":["钝痛，持续时间长","刺痛","胀痛","胀闷走窜疼痛，甚或刺痛","空痛"],"a":3,"e":"气滞血瘀证气滞与血瘀并见，故胀闷走窜疼痛与刺痛并作，痛处固定、拒按，舌紫黯或有瘀斑。纯刺痛偏于血瘀，纯胀痛走窜偏于气滞。"},{"q":"久病、重病患者面色苍白，时而颧赤泛红如妆、游移不定是","o":["实热证","虚热证","阴虚证","戴阳证","虚寒证"],"a":3,"e":"戴阳证为阴寒内盛、虚阳浮越于上，故面色苍白而颧部泛红如妆、游移不定，属真寒假热之危候。虚热证颧红固定，多伴潮热盗汗、舌红少苔。"},{"q":"肾虚水泛的痰饮病，面色多为","o":["眼眶周围黑","面色黧黑","面黑而干焦","面色淡白而胖","面色淡黄而兼虚浮"],"a":0,"e":"眼眶周围色黑为肾虚水饮内停、血行不畅之征，故肾虚水泛之痰饮多见。面色黧黑为肾阳衰微，面黑而干焦为肾阴亏耗，三者深浅不同。"},{"q":"下列哪项一般不会出现腻苔","o":["湿浊","阴虚","痰饮","食积","顽痰"],"a":1,"e":"腻苔由湿浊内蕴、阳气被遏、湿浊上泛而成，见于湿浊、痰饮、食积、顽痰。阴虚津亏则苔少或无苔而干，甚则光剥，不会出现腻苔。"},{"q":"表寒证的典型临床表现不包括","o":["恶寒发热","头身疼痛","鼻塞流清涕","咽喉肿痛","无汗"],"a":3,"e":"表寒证为风寒束表、卫阳被遏，见恶寒重发热轻、头身疼痛、无汗、鼻塞流清涕、苔薄白、脉浮紧。咽喉肿痛为热邪上灼，属表热或里热之象。"},{"q":"弦脉与革脉的共同特征主要表现在","o":["流利度","紧张度","至数","脉宽","脉位"],"a":1,"e":"弦脉端直以长、如按琴弦，革脉浮而搏指、中空外坚如按鼓皮，二者脉体皆强直紧张，共同特征在于脉的紧张度。革脉兼浮与中空，与弦脉不同。"},{"q":"下列哪一项不属于失神的临床表现","o":["目暗睛迷","瞳神呆滞","精神委靡","目浮光外露","面色晦黯无华"],"a":3,"e":"失神见目暗睛迷、瞳神呆滞、精神委靡、面色晦黯无华、反应迟钝。目浮光外露为久病重病而突然目光转亮，属假神，是精气衰竭、阴阳离决之危候。"},{"q":"以下不主实热证的是","o":["牢脉","滑脉","洪脉","数脉","长脉"],"a":0,"e":"滑脉主痰饮食积实热，洪脉主气分热盛，数脉主热，长脉主阳盛有余，四者皆可见于实热。牢脉主阴寒内积、疝气癥积，为寒实之象，不主实热。"},{"q":"下列各项，不属脾阳虚证的临床表现的是","o":["浮肿尿少","带下清稀量多","畏寒肢冷","月经过多","腹痛喜温喜按"],"a":3,"e":"脾阳虚证温运失职，见畏寒肢冷、腹痛喜温喜按、浮肿尿少、带下清稀量多、便溏。月经过多因气虚不能摄血或血热、瘀阻所致，非脾阳虚之候。"},{"q":"脾胃虚寒之人可见下列哪一症状","o":["口甜而腻","口中泛酸","口中酸馊","口淡无味","口有苦味"],"a":3,"e":"脾胃虚寒，腐熟运化无力，故口淡无味、纳谷不香，伴畏寒喜温、便溏。口甜而腻属脾胃湿热，口苦属肝胆热，口中泛酸属肝胃郁热。"},{"q":"根据五轮学说，眼睑为","o":["水轮","风轮","血轮","气轮","肉轮"],"a":4,"e":"五轮分属：胞睑为肉轮，属脾；白睛为气轮，属肺；黑睛为风轮，属肝；两眦为血轮，属心；瞳神为水轮，属肾。"},{"q":"根据五轮学说，黑睛属于","o":["肺","脾","肾","心","肝"],"a":4,"e":"黑睛为风轮，内应于肝，肝病每见于黑睛，如黑睛生翳、混浊。白睛属肺，瞳神属肾，两眦属心，胞睑属脾。"},{"q":"小儿食指络脉诊法适用于","o":["七岁以内","五岁以内","三岁以内","一岁以内","十岁以内"],"a":2,"e":"小儿食指桡侧络脉由手太阴肺经分出，三岁以内小儿脉部短小、诊脉不便，故以望络脉代替；三岁以上则应以脉诊为主。"},{"q":"指力适中，不轻不重，按至肌肉而取脉的方法是","o":["浮取","中取","沉取","单按","总按"],"a":1,"e":"切脉有举、按、寻三法：轻指力按于皮肤为举，即浮取；重指力按至筋骨为按，即沉取；不轻不重、按至肌肉者为中取。"},{"q":"灰黑苔辨寒热的关键是观察","o":["舌苔之厚薄","舌苔之腐腻","舌形之胖瘦","舌苔之润燥","舌之老嫩"],"a":3,"e":"灰黑苔主热极或寒盛，辨其寒热以润燥为关键：苔灰黑而燥裂、刮之不脱者属热极伤阴；苔灰黑而润滑者属阳虚寒盛、痰湿内停。"},{"q":"以高热不退，四肢抽搐，颈项强直，两目上视，角弓反张，牙关紧闭，舌红绛，苔黄燥，脉弦数为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","寒滞肝脉证"],"a":3,"e":"热极生风证为邪热炽盛、燔灼肝经，筋脉失养，故高热、四肢抽搐、颈项强直、角弓反张，舌红绛苔黄燥、脉弦数。肝阳化风多见于中老年，以偏瘫为主。"},{"q":"下列何证的主症是寒热往来，胸胁苦满，心烦喜呕","o":["阳明病证","厥阴病证","太阴病证","太阳病证","少阳病证"],"a":4,"e":"少阳病证为邪居半表半里、枢机不利，故寒热往来、胸胁苦满、心烦喜呕、默默不欲饮食、口苦咽干、脉弦。阳明病证为但热不寒、腹满便秘。"},{"q":"下述何项对于新生儿问诊意义不大","o":["妊娠期母体营养状况","有无传染病史","妊娠期母体患过何病","母亲妊娠期、产育期用过何药","分娩时是否难产、早产"],"a":1,"e":"新生儿问诊重在胎禀与分娩情况，包括母体妊娠期营养、患病与用药，以及是否难产、早产。其无独立生活史，传染病史须从母体情况间接了解。"},{"q":"白厚腻苔多见于","o":["里热证","寒湿证","表寒证","虚寒证","阴虚证"],"a":1,"e":"白苔主表证、寒证，厚腻为湿浊痰饮内停，故白厚腻苔多主寒湿。苔白厚腻而干者亦见于湿浊化热，须结合苔之润燥与全身症状辨别。"},{"q":"泻下黄糜，伴肛门灼热者，属于","o":["大肠液亏","大肠湿热","肠虚滑脱","脾肾阳虚","肝郁乘脾"],"a":1,"e":"泻下物色黄如糜、臭秽，肛门灼热，为湿热蕴结大肠、传导失常，属大肠湿热。脾肾阳虚者泻下清稀或完谷不化，无肛门灼热。"},{"q":"观察舌苔以辨别病邪深浅的主要依据是","o":["舌苔的有无","舌苔的黄白","舌苔的有根无根","舌苔的薄厚","舌苔的润燥"],"a":3,"e":"舌苔薄厚反映邪气深浅与轻重：苔薄者邪在表、病轻，苔厚者邪入里、病重。苔之黄白辨寒热，润燥辨津液存亡，有根无根辨邪正虚实。"},{"q":"牙齿光燥如石，多为","o":["胃津已伤","肾阴枯竭","胃火炽盛","阳明热盛，津液大伤","肾气旺盛，津液充足"],"a":3,"e":"牙齿光燥如石而色白，为阳明热盛、津液大伤，齿失濡润。齿燥色黑而枯、骨瘦如脱者属肾阴枯竭；齿焦有垢为胃热，齿焦无垢为肾虚。"},{"q":"下列选项中，不属于闭经常见原因的是","o":["痰湿阴滞胞宫","气滞血瘀","寒凝血瘀","肝郁血热","肝肾不足"],"a":3,"e":"闭经多因气血亏虚、肝肾不足、气滞血瘀、寒凝血瘀、痰湿阻滞胞宫。肝郁血热迫血妄行，多见月经先期、量多或经期延长，不致经闭。"},{"q":"以头晕头胀，或头痛剧烈，面红目赤，急躁易怒，失眠多梦，舌红苔黄，脉弦数为主要表现的证是","o":["肝血虚证","肝风内动证","肝郁气滞证","肝火炽盛证","肝胆湿热证"],"a":3,"e":"肝火炽盛，火性上炎，故头晕胀痛、面红目赤、急躁易怒、失眠多梦、耳鸣，舌红苔黄、脉弦数。肝阳上亢以头重脚轻、腰膝酸软为特点，属本虚标实。"},{"q":"以下不属于涩脉主病的是","o":["伤精","血少","气滞血瘀","夹痰夹食","阴盛气结"],"a":4,"e":"涩脉往来艰涩不畅，主气滞血瘀、痰食内停及伤精血少。阴盛气结为结脉所主，脉来缓慢而时一止，与涩脉之艰涩不畅不同。"},{"q":"牙齿光燥如石者多属","o":["热极动风","胃阴亏损","肾虚，虚火上炎","阳明热甚、津液大伤","肾阴枯竭，精不上荣"],"a":3,"e":"牙齿光燥如石，为阳明热甚、津液大伤，齿面失于濡润而反光。若齿燥色黑枯槁，多属肾阴枯竭、精不上荣，病位深浅有别。"},{"q":"辨寒热的目的是","o":["辨病因","辨病性","辨病位","辨邪正盛衰","辨标本缓急"],"a":1,"e":"八纲中表里辨病位，寒热辨病性，虚实辨邪正盛衰，阴阳为总纲。寒热反映疾病的性质，故辨寒热的目的在于确定病性。"},{"q":"嗜睡的主要病机是","o":["阳气不足","阳盛阴虚","阴阳两虚","阳虚阴盛","阴盛格阳"],"a":3,"e":"嗜睡为神气不振、阳气衰微，阳虚则阴盛，卫阳不能振奋，故精神困倦而多寐，多见于痰湿困脾、脾虚或阳虚之证。失眠则多属阳盛阴虚。"},{"q":"野外工作者面色偏黑，称为","o":["主色","善色","客色","常色","恶色"],"a":2,"e":"客色为因气候环境、生活条件、情绪劳逸等影响而发生的面色相应变化，属正常范围。野外工作日久受日晒而面黑，随环境改变可复，故为客色。"},{"q":"下列脉象除哪项外，脉位皆表浅","o":["浮脉","芤脉","濡脉","散脉","弱脉"],"a":4,"e":"浮、芤、濡、散四脉脉位均浅，轻取即得。弱脉沉细而软，须重按始得，脉位在沉，与其余四脉相反。"},{"q":"下列哪项宜诊断为心肺气虚证","o":["咳嗽气喘、自汗畏风","咳痰清稀、声低少气","咳喘心悸、神疲思睡","胸胁闷痛、咳唾益甚","呼多吸少、短气乏力"],"a":2,"e":"心肺气虚证为心肺两脏气虚，肺气虚则咳喘气短，心气虚则心悸，宗气不足故神疲思睡、声低乏力，舌淡脉弱。呼多吸少、短气乏力属肾不纳气。"},{"q":"下列各项，属于寒湿困脾证常见病因的是","o":["暴饮暴食","饮食肥甘生冷","思虑过度","劳倦内伤","久泻久痢"],"a":1,"e":"寒湿困脾多因冒雨涉水、久居湿地，或过食肥甘生冷，寒湿内侵，脾阳受困。思虑过度、劳倦内伤多伤脾气，久泻久痢多为脾虚之果。"},{"q":"“直中”是指","o":["两经或三经证候同时出现","一经证候已罢，继而出现另一经证候","互为表里的阴阳两经证候同时出现","一经证候未罢，又出现另一经证候","外邪入犯三阴而出现三阴证候"],"a":4,"e":"直中指素体阳虚，外邪不经三阳而径入三阴，起病即见三阴证候。合病为两经或三经证候同时出现，并病为一经证候未罢又见另一经证候。"},{"q":"实证的临床表现常见","o":["神疲乏力","自汗","五心烦热","腹部绞痛","畏寒"],"a":3,"e":"实证邪气亢盛、正气未衰，故腹痛剧烈如绞而拒按，伴声高气粗、便秘、脉实有力。神疲乏力、自汗、五心烦热、畏寒均属虚证表现。"},{"q":"浮滑脉的主病多为","o":["痰热内结","饮食停滞","湿热内蕴","风痰","风寒袭表"],"a":3,"e":"浮脉主表，滑脉主痰，浮滑相兼为风痰，因风邪挟痰上扰，常见头目眩晕、口眼㖞斜。浮紧主风寒表证，滑数多主痰热。"},{"q":"疮疡红肿高大，根盘紧束，灼热疼痛为","o":["痈","疽","疔","疖","丹毒"],"a":0,"e":"痈为气血受毒邪所困、壅聚而成，红肿高大、根盘紧束、灼热疼痛，易消易溃易敛，属阳证。疽漫肿无头、皮色不变、不热少痛，属阴证。"},{"q":"因气候环境的变化而使面色发生相应变化的正常肤色称为","o":["客色","主色","常色","善色","恶色"],"a":0,"e":"常色包括主色与客色：主色为个体终生不变的基本肤色，客色为随四时气候、地理环境等变化而相应改变的面色，二者皆属正常。"},{"q":"下列各项不属于中焦病证的是","o":["腹满便秘","胸脘痞闷","大便不爽","呼吸气粗","舌红少苔"],"a":4,"e":"中焦病证分阳明燥热与太阴湿热：前者腹满便秘、呼吸气粗、苔黄燥，后者胸脘痞闷、大便不爽、苔黄腻。舌红少苔为阴液亏虚，见于下焦肝肾阴虚。"},{"q":"下列属于特征相反的脉象是","o":["沉脉与伏脉","洪脉与实脉","濡脉与浮脉","滑脉与涩脉","弦脉与紧脉"],"a":3,"e":"滑脉往来流利，涩脉往来艰涩，二者脉之流利度相反，为特征相对的脉象。沉与伏、洪与实、濡与浮、弦与紧虽相近而非相反。"},{"q":"肺气不得宣散，上逆于喉间，气道窒塞，呼吸急促称之为","o":["喘证","哮证","上气","短气","少气"],"a":2,"e":"上气指肺气不得宣散、上逆于喉间、气道窒塞而呼吸急促，多因痰饮阻肺。哮证以喉中哮鸣有声为特征，喘证以呼吸困难、张口抬肩为主。"},{"q":"沉涩脉主病常为","o":["肝郁气滞","水饮内停","血虚肝郁","寒凝血瘀","阳明热甚"],"a":3,"e":"沉脉主里，涩脉主血瘀，沉涩相兼为寒凝气滞、血行瘀阻，常见胸痹、痛经、癥积。沉细多主虚，沉滑多主痰饮，与沉涩病机不同。"},{"q":"下列各项，不属于水停证临床表现的是","o":["水肿按之凹陷不易起","小便短少不利","身体困重","舌淡胖苔白滑，脉濡缓","咳吐清稀痰涎"],"a":4,"e":"水停证为水液代谢失常、泛溢肌肤，见水肿按之凹陷不起、小便短少、身体困重、舌淡胖苔白滑、脉濡缓。咳吐清稀痰涎属饮证，为饮邪犯肺。"},{"q":"切脉指法中，不轻不重，委曲求之，称为","o":["举","总按","按","寻","单按"],"a":3,"e":"寻法指切脉时指力从轻到重、从重到轻，左右前后推寻，以探求脉动最明显的部位与形态，所谓委曲求之。举为轻取，按为重取。"},{"q":"下列哪项最不可能出现在心阳暴脱证","o":["心悸怔忡","脉数极而无力","心胸疼痛","四肢厥冷","冷汗淋漓"],"a":1,"e":"心阳暴脱证阳气骤脱，见心悸怔忡、心胸疼痛、四肢厥冷、冷汗淋漓、面色苍白、脉微欲绝。脉数极而无力为阴竭阳越、虚热内扰之象。"},{"q":"观察病人面色的关键，在于区分","o":["主色与客色","善色与恶色","常色与病色","客色与病色","主色与病色"],"a":1,"e":"望面色重在辨别善色与恶色，即色之有无光泽、是否明润：明润光泽为善色，主病轻、胃气未衰；枯槁晦暗为恶色，主病重、胃气已败。"},{"q":"用手指掌面或手掌轻轻接触病人局部皮肤，以了解肌肤的情况称为","o":["按法","触法","摸法","压法","叩法"],"a":1,"e":"按诊手法分触、摸、按、叩：以掌面或手指轻触局部皮肤，了解肌肤凉热润燥为触法；以指腹抚摸肿物大小形态为摸法；重手按压为按法。"},{"q":"下列各项，属于脾虚气陷证临床表现的是","o":["脘腹重坠，食后更甚","腹痛喜暖喜按","畏寒肢冷","身热不扬，汗出不解","便血"],"a":0,"e":"脾虚气陷证中气不足、升举无力，故脘腹重坠、食后更甚，伴久泻脱肛、内脏下垂、头晕气短。腹痛喜暖喜按、畏寒肢冷属脾阳虚。"},{"q":"多食易饥，口臭便秘者，可见于","o":["胃火炽盛","食滞胃脘","胃气不足","胃阴亏虚","肝气犯胃"],"a":0,"e":"胃火炽盛，腐熟太过则多食易饥，火盛耗津、腑气不通则口臭便秘，伴口渴喜冷、齿龈肿痛。胃阴亏虚者饥不欲食、口燥咽干而无口臭。"},{"q":"虚实夹杂不包括","o":["表虚里实证","上实下虚证","虚实并重证","虚中夹实证","实证转虚证"],"a":4,"e":"虚实夹杂指同一病证中虚与实并见，有表虚里实、上实下虚、虚中夹实、实中夹虚及虚实并重等。实证转虚证属证候转化，是病机由实变虚的动态过程。"},{"q":"最不易见于肺热炽盛证的症状是","o":["咳嗽气喘","气息灼热","大便秘结","咽喉肿痛","腥臭脓痰"],"a":4,"e":"肺热炽盛证热壅于肺，见咳嗽气喘、气息灼热、咽喉肿痛、大便秘结、舌红苔黄。腥臭脓痰为热壅血瘀、肉腐成痈之肺痈征象，非肺热炽盛所必有。"},{"q":"战汗后向愈的表现是","o":["精神萎靡","身热不减","烦躁不安","脉静身凉","脉象疾数"],"a":3,"e":"战汗后脉静身凉、神清气爽，为正胜邪却、病趋痊愈之象；若汗后身热不退、烦躁不安、脉来疾数，则为邪盛正衰、病情恶化。"},{"q":"暴注下泻，色黄味臭者属于","o":["湿热蕴脾证","大肠湿热证","肝胆湿热证","肠热腑实证","肠虚滑泻证"],"a":1,"e":"暴注下泻、色黄臭秽，伴腹痛、肛门灼热、小便短黄，为湿热蕴结大肠、传导失职。湿热蕴脾以脘腹痞闷、身重、口黏为主，泻势较缓。"},{"q":"往来流利，应指圆滑，如珠走盘的脉象是","o":["弦脉","滑脉","数脉","涩脉","细脉"],"a":1,"e":"滑脉往来流利、应指圆滑，如珠走盘，主痰饮、食积、实热，孕妇亦见。涩脉往来艰涩如轻刀刮竹，弦脉端直以长如按琴弦。"},{"q":"下列不属实证的是","o":["食积","内燥","气滞","水停","血瘀"],"a":1,"e":"实证为邪气亢盛、正气未衰，食积、气滞、水停、血瘀皆属有形之邪壅滞。内燥为津液亏少、脏腑失于濡润，属虚证范畴。"},{"q":"弹石脉的脉象是","o":["短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","如釜中沸水，浮泛无根","脉来乍疏乍密，如解乱绳状","脉在筋骨之间，如指弹石"],"a":4,"e":"弹石脉在筋骨之间，按之坚搏，如指弹石，主肾气竭绝。短小坚搏如循薏苡子者为转豆脉，乍疏乍密如解乱绳者为麻促脉，皆属真脏脉。"},{"q":"下列各项，不属中医诊断的内容的是","o":["收集病情资料","判断健康与否","作出疾病诊断","辨别确定证名","提出治疗原则"],"a":4,"e":"中医诊断包括收集病情资料、判断健康与否、作出疾病诊断与辨别确定证名，即诊法、诊病、辨证三个环节。提出治疗原则属论治范畴。"},{"q":"诊脉时指力从轻到重，从重到轻，左右前后推寻，以寻找脉动最明显的特征，称为","o":["浮取","中取","沉取","寻法","总按"],"a":3,"e":"寻法以指力由轻渐重、由重渐轻，并左右前后推寻，探求脉动最明显之处及脉形变化，为切脉三法之一。浮取、中取、沉取专论指力深浅。"},{"q":"最应归属阴证的是","o":["里虚寒证","里虚热证","表虚寒证","表虚热证","里实寒证"],"a":0,"e":"阴证以里、虚、寒为基本属性，里虚寒证三者兼备，为阴证的代表；里虚热证属虚热，表证病位在表，均不属阴证。"},{"q":"咽喉间起灰白色假膜，不易剥离，剥则出血，随即复生者，称为","o":["白喉","乳蛾","瘿瘤","烂乳蛾","痰核"],"a":0,"e":"白喉系疫毒犯肺，咽喉生灰白色假膜，坚韧不易剥离，强行剥离则出血并迅速复生，为其特征性表现。"},{"q":"饭后嗜睡，神疲倦怠，食少纳呆者多为","o":["痰湿困脾","中气不足","心肾阴虚","热入心包","心肾阳虚"],"a":1,"e":"脾气虚弱、清阳不升，食后气血聚于脾胃而头目失养，故饭后困倦嗜睡，兼神疲、食少纳呆，属中气不足。"},{"q":"解索脉的主病是","o":["肾气竭绝","肾与命门之气皆亡","三阳热极，阴液枯竭","三阴寒极，阳亡于外","胃气营卫将绝"],"a":1,"e":"解索脉在筋肉间乍疏乍密、散乱无序，如解乱绳之状，主肾与命门之气皆亡，为脏气竭绝之危候。"},{"q":"“望色十法”中判断病情之轻重的纲领是","o":["泽夭","清浊","微甚","散抟","浮沉"],"a":0,"e":"望色十法中浮沉辨表里、清浊辨阴阳、微甚辨虚实、散抟辨新久、泽夭辨轻重，故判断病情轻重以泽夭为纲。"},{"q":"下列哪项不是望头部情况的主要诊察范畴","o":["脑的病变","肾的病变","肺的病变","精气盛衰","血的虚实"],"a":2,"e":"头为精明之府、诸阳之会，望头主要察脑与肾的病变，并测精气盛衰、血液虚实，肺病不反映于头颅形色。"},{"q":"下列哪项提示病多凶险，预后不佳","o":["络脉仅显示于风关","络脉达于气关","透关射甲","络脉达于命关","络脉沉隐"],"a":2,"e":"小儿指纹透风、气、命三关直射指端爪甲，称透关射甲，示邪陷深入、脏气衰败，病多凶险，预后不良。"},{"q":"问现在症的方法，首先应该是","o":["问寒热情况","按十问内容逐项询问","根据症状进行询问","根据体征进行询问","抓住主症展开询问"],"a":4,"e":"问现在症应在全面了解病情后抓住主症，围绕主症追询其性状、程度、兼症与演变，方能理清辨证线索。"},{"q":"精神萎靡，意识模糊的是","o":["得神","少神","失神","假神","神乱"],"a":2,"e":"失神见精神萎靡、意识模糊、目光晦暗、言语低微、反应迟钝，为正气大伤、脏腑精气衰败之象，病多沉重。"},{"q":"古称谓“哕”者即","o":["干呕","恶心","嗳气","呃逆","呕吐"],"a":3,"e":"哕即呃逆，因胃气上逆动膈，气从喉间冲出，声短而频、不能自制，古以哕称之，与干呕、嗳气不同。"},{"q":"由于气候影响，平脉在春天可见","o":["浮","沉","洪","弦","迟"],"a":3,"e":"脉应四时，春微弦、夏微洪、秋微浮、冬微沉，皆平脉应时之象；春气通肝，肝主弦，故春季平脉可见弦。"},{"q":"主元气离散之脉是","o":["散脉","弱脉","微脉","芤脉","细脉"],"a":0,"e":"散脉浮散无根、来去不齐，按之则散，是元气离散、脏腑精气衰败之候，故主元气离散，属无根之脉。"},{"q":"以下不属于弦脉主病的是","o":["痛证","疟疾","胆病","湿证","痰饮"],"a":3,"e":"弦脉端直以长如按琴弦，主肝胆病、诸痛、痰饮与疟疾；湿邪为患脉多濡缓，故湿证不属弦脉主病。"},{"q":"燥邪伤肺，或肺阴亏虚者，其痰常表现为","o":["痰中带血","痰少而黏难以咯出","咯吐脓血痰","痰黄质黏而稠","痰多色白滑易咯"],"a":1,"e":"燥邪伤肺或肺阴亏虚，肺失濡润，津液被灼，故痰少而黏、难以咯出，甚则痰中带血，属燥痰。"},{"q":"下列各项说法，错误的是","o":["围绕主要病痛问诊","运用医学术语问诊","耐心听患者陈述病情","对危重病人要扼要问诊","现在症是当前诊断的主要依据"],"a":1,"e":"问诊须用通俗语言，避免生硬医学术语，以免患者不解而答非所问；围绕主症、耐心倾听、危重者扼要询问皆属正确做法。"},{"q":"月经提前7天以上，量多、色红、质稠者，属于","o":["气虚","血热","血虚","血寒","血瘀"],"a":1,"e":"热迫血行、血海不宁，则月经先期而量多、色红、质稠，属实热或阴虚火旺之血热；气虚者量多而色淡质稀。"},{"q":"脉来时有一止，止有定数，良久方来的是","o":["代脉","促脉","涩脉","结脉","动脉"],"a":0,"e":"代脉脉来一止，止有定数，良久方还，主脏气衰微，亦见于风证、痛证、七情惊恐与跌打损伤。"},{"q":"虚证的形成不包括","o":["外邪直中","饮食失调","思虑太过","悲哀卒恐","过度劳倦"],"a":0,"e":"虚证由先天不足或后天失养而成，饮食失调、思虑太过、悲哀卒恐、劳倦过度皆耗伤正气；外邪直中属邪实为患。"},{"q":"以下不属于沉脉类的是","o":["沉脉","涩脉","伏脉","牢脉","弱脉"],"a":1,"e":"沉脉类含沉、伏、牢、弱，均以脉位深沉为共同点；涩脉以往来艰涩不畅为特征，脉位并不偏沉。"},{"q":"燥热伤津常出现","o":["口黏","口苦","口酸","口甜","口涩"],"a":4,"e":"燥热耗伤津液，口舌失润，故口中涩滞；口苦多属肝胆火旺，口甜属脾胃湿热，口黏多为湿浊内蕴。"},{"q":"下列除哪项外均为至数不齐的脉象","o":["散脉","动脉","促脉","结脉","代脉"],"a":1,"e":"散、促、结、代均以脉律不齐、至数不匀为特点；动脉脉来滑数、形如豆大，节律匀整，不属至数不齐之脉。"},{"q":"脾胃虚弱导致脘腹疼痛的特点是","o":["隐痛","灼痛","窜痛","胀痛","刺痛"],"a":0,"e":"脾胃虚弱，气血不足，脘腹失于温养，故痛势绵绵、喜温喜按、时作时止，属虚性隐痛，与实痛拒按有别。"},{"q":"下列选项中，均具有脉位深沉特点的脉象是","o":["牢脉，实脉，洪脉，弦脉","洪脉，实脉，弦脉，芤脉","牢脉，革脉，弦脉，弱脉","弱脉，革脉，伏脉，牢脉","牢脉，弱脉，沉脉，伏脉"],"a":4,"e":"牢、弱、沉、伏四脉均须重按始得，脉位俱深；洪、芤、革三脉位偏浮，弦脉居中，故余组不合。"},{"q":"下列各项，问带下最无意义是","o":["天数","量的多少","颜色","质的变化","气味"],"a":0,"e":"问带下重在其量之多少、色之变化、质之稀稠与气味秽臭，以辨寒热虚实；带下无周期天数可计，问天数意义最小。"},{"q":"胸胁部胀闷或痛，呼吸、咳嗽或转侧时牵引作痛者属于","o":["风水搏肺证","肺热炽盛证","痰热壅肺证","寒痰阻肺证","饮停胸胁证"],"a":4,"e":"饮停胸胁，气机阻滞，故胸胁胀闷疼痛，咳唾、呼吸或转侧时牵引作痛，常伴息促，属悬饮证。"},{"q":"痰火扰心的狂证可出现","o":["哭笑无常，焦虑恐惧","神昏谵语","登高而歌，弃衣而走","突然昏仆，四肢抽动","失眠惊悸"],"a":2,"e":"痰火扰心，神机错乱，发为狂证，见登高而歌、弃衣而走、骂詈不避亲疏、力逾常人，舌红苔黄腻、脉滑数。"},{"q":"初起如粟如米，根脚坚硬较深，麻木或发痒，顶白而痛者，称为","o":["痈","疽","疹","疖","疔"],"a":4,"e":"疔形小根深，初起如粟如米，顶白而痛，根脚坚硬，麻木发痒，毒深易致走黄；痈疽则肿形大而根盘宽。"},{"q":"散脉的主病是","o":["元气离散","气血两虚","诸虚劳损","失精亡血","阴盛气结"],"a":0,"e":"散脉浮散不收、至数不齐，主元气离散、脏腑精气衰败，多见于久病危重之人，预后不良。"},{"q":"口干微渴，发热恶寒，咽喉肿痛者，多见于","o":["温病卫分证","阳明经证","消渴病","水逆证","温病营分证"],"a":0,"e":"温邪初袭肺卫，卫气被郁，故发热恶寒、咽喉肿痛；热渐伤津则口干微渴，属温病卫分证。"},{"q":"瞪目直视，多为","o":["有机磷农药中毒","阿托品中毒","脏腑精气衰竭","肝风内动","瘿病"],"a":2,"e":"两目固定上视、瞪目直视而不灵动，是脏腑精气衰竭、神气将绝之象，多见于病危之人，预后不良。"},{"q":"下列各项，与绝汗无关的是","o":["面色苍白","恶寒战栗","冷汗淋漓","呼吸气微","肢厥脉微"],"a":1,"e":"绝汗由阳气欲脱或阴液将竭所致，见冷汗淋漓、面色苍白、肢厥脉微、呼吸气微；恶寒战栗为战汗前兆。"},{"q":"脏躁可表现为","o":["淡漠痴呆","猝然昏仆","焦虑恐惧","狂躁不安","蒙蔽清窍"],"a":2,"e":"脏躁多因忧思过度、心脾两伤、脏阴不足，见情志失常、焦虑恐惧、悲伤欲哭、频作欠伸。"},{"q":"一个规范的证名，应当包括病位和","o":["病因","病机","病性","病势","连接词"],"a":2,"e":"证是对疾病某阶段病位与病性等本质的概括，故规范证名由病位与病性构成，如心气虚证、肝阳上亢证。"},{"q":"花剥苔一般提示","o":["胃气阴两伤","湿遏热邪","脾虚伤食","胃肠有热","痰浊未化"],"a":0,"e":"花剥苔为舌苔部分剥落、剥处光滑，因胃之气阴两伤、不能上蒸生苔；先天剥苔者属生理现象。"},{"q":"胆郁痰扰证的情志变化表现为","o":["多思善虑","抑郁不乐","喜笑不休","胆怯易惊","悲忧不解"],"a":3,"e":"痰热内扰胆腑，胆失疏泄、决断无权，故胆怯易惊、烦躁不宁、失眠多梦，兼口苦、呕恶、苔黄腻。"},{"q":"微脉的主病是","o":["气虚血少","气虚有湿","阴阳气血俱虚","诸虚诸湿","阳气有余"],"a":2,"e":"微脉极细极软，似有似无，按之欲绝，主阴阳气血俱虚，多见于阳气衰微或气血大伤之危候。"},{"q":"肠虚滑泻证的辨证要点是大便失禁与下列何项共见","o":["气虚症状","血虚症状","阳虚症状","阴虚症状","津亏症状"],"a":2,"e":"肠虚滑泻由脾肾阳虚、统摄无权所致，以大便失禁、久泻滑脱不禁，兼形寒肢冷等阳虚症状为辨证要点。"},{"q":"下列哪个病证不属于痰蒙心神证临床表现","o":["神志抑郁","狂","痴呆","癫病","痫病"],"a":1,"e":"痰蒙心神证见神志抑郁、表情淡漠、痴呆、癫病、意识模糊；狂属痰火扰心、阳热亢盛，不属本证表现。"},{"q":"因外界因素变动而发生相应变化的肤色是","o":["主色","客色","善色","恶色","病色"],"a":1,"e":"客色随四时气候、昼夜晨昏及居处环境等外界因素而变，属生理性肤色变化，与生来固定的主色相对。"},{"q":"阴虚或气阴两虚导致的汗出是","o":["自汗","盗汗","战汗","半身汗","绝汗"],"a":1,"e":"盗汗指睡时汗出、醒则汗止，因阴虚内热、入睡后卫阳入里、虚热蒸津外泄所致，气阴两虚者亦可见。"},{"q":"湿邪困遏作痛的特点是","o":["重痛","胀痛","冷痛","隐痛","刺痛"],"a":0,"e":"湿性重浊黏滞，困遏气机，故痛处兼有沉重之感，多见于头身四肢及腰部，为湿邪致痛的特征。"},{"q":"下列目形见于脏腑精气衰竭的是","o":["眼窝微陷","眼窝深陷","眼球突出","针眼","眼丹"],"a":1,"e":"眼窝深陷、目光暗淡，为脏腑精气衰竭、目失所养，见于久病重病；眼窝微陷仅示轻度伤津，不可概言精衰。"},{"q":"肝郁气滞证与肝阳上亢证均可见有","o":["情志抑郁","烦躁易怒","胁肋疼痛","脉细数","舌体淡白"],"a":2,"e":"肝之经脉布于胁肋，肝郁气滞则胁肋胀痛；肝阳上亢多由肝郁化火、肝阴不足而阳亢于上，亦见胁肋疼痛。"},{"q":"对诊断肺肾阴虚证最有意义的是","o":["咳嗽痰少、声音嘶哑","腰膝酸软、骨蒸潮热","舌红少苔、脉象细数","颧红咽干、月经不调","咳痰带血、遗精盗汗"],"a":4,"e":"肺肾阴虚，肺失濡润则咳痰带血，虚火扰动精室则遗精，虚热内蒸则盗汗潮热，两组症状并见最具诊断价值。"},{"q":"以下不属于代脉主病的是","o":["风证","痛证","虚证","惊恐","食滞"],"a":4,"e":"代脉主脏气衰微，亦主风证、痛证、七情惊恐与跌扑损伤；食滞多致滑脉或涩脉，非代脉所主。"},{"q":"久流腥臭浊涕，状如鱼脑者，多为","o":["肺痈","肺热","鼻渊","瘟疫","肺痿"],"a":2,"e":"鼻渊为鼻窍时流浊涕、缠绵不止，其涕腥臭黏稠如鱼脑，兼鼻塞、头痛，多由风热或胆热上蒸鼻窍。"},{"q":"紫舌多主","o":["外感风热表证","血行不畅","阴虚火旺","气血不足","里热亢盛"],"a":1,"e":"紫舌总由血脉瘀阻、血行不畅而成，淡紫偏虚寒，青紫偏寒凝血瘀，紫红偏热盛血壅，总以瘀滞为要。"},{"q":"喜伤证的临床表现有","o":["善悲喜哭","喜笑不休","胆怯心悸","胸闷胁胀","二便失禁"],"a":1,"e":"喜则气缓，过喜伤心，神气涣散不收，故喜笑不休、精神不专，甚则心神失守、举止失常。"},{"q":"寸口诊法始见于","o":["《内经》","《难经》","《脉经》","《伤寒论》","《濒湖脉学》"],"a":0,"e":"《内经》已提出气口独为五脏主、诊寸口以候脏腑，《难经》更申独取寸口之义，故寸口诊法始见于《内经》。"},{"q":"下列哪项不属于腻苔的特征","o":["苔质疏松浮浅","苔质颗粒细腻致密","中间厚边周薄","融合成片","紧贴舌面，揩之不去"],"a":0,"e":"腻苔颗粒细腻致密、融合成片，紧贴舌面揩之不去，中部厚而边周薄；苔质疏松浮浅为腐苔特征。"},{"q":"《景岳全书》中“阴挺”指","o":["阴囊肿大","阴部湿疹","子宫脱垂","脱肛","肛痈"],"a":2,"e":"阴挺指子宫下垂，甚则脱出阴道口外，多因中气下陷、肾气不固、带脉失约而成，见于《景岳全书》。"},{"q":"下列哪项不属于心病的常见症状","o":["怔忡","心痛","健忘","神识错乱","背痛"],"a":4,"e":"心病常见心悸怔忡、心痛、胸闷、健忘、失眠、神识错乱；背痛多属肺、督脉或肩背筋络病变。"},{"q":"下列哪项不属于心气虚证的常见症状","o":["心悸","心烦","胸闷","气短","自汗"],"a":1,"e":"心气虚证见心悸、胸闷、气短、自汗、神疲乏力、脉虚；心烦系热扰心神，属心火或心阴虚之症。"},{"q":"下列何证表现为喘声低微，呼吸短促难续，得一长息为快，动则喘甚","o":["风寒袭肺","痰湿阻肺","痰热壅肺","肺肾气虚","肺脾气虚"],"a":3,"e":"肺肾气虚，摄纳无权，气不归元，故喘声低微、呼吸短促难续、动则喘甚，引长息为快，属虚喘。"},{"q":"下列除哪项外，都可与肾精亏虚有关","o":["鼻柱塌陷，眉毛头发脱落","目胞色黑晦暗","耳郭瘦薄","牙根宣露","齿摇发脱"],"a":0,"e":"肾精亏虚可见目胞色黑、耳郭瘦薄、齿摇发脱、牙根宣露；鼻柱塌陷、眉毛头发脱落为疠气麻风之征。"},{"q":"下列不是气血两虚证的临床表现的是","o":["少气懒言","肢体麻木","头晕目眩","舌有紫斑","唇甲色淡"],"a":3,"e":"气血两虚证见少气懒言、头晕目眩、肢体麻木、唇甲色淡、舌淡脉细弱；舌有紫斑为血瘀之象。"},{"q":"脾病的常见面色是","o":["白色","黄色","黑色","青色","红色"],"a":1,"e":"脾属土而色黄，脾虚失运、水湿不化则面色萎黄，湿热熏蒸则黄而鲜明，故黄色为脾病主色。"},{"q":"肾阳虚衰、阴寒凝滞，面色多为","o":["面色黑而淡黯","面色黑而干焦","面色黧黑，肌肤甲错","面色枯黄","面色苍白"],"a":0,"e":"黑为肾色，肾阳虚衰、阴寒凝滞，气血失于温运，故面色黑而淡黯；黑而干焦属肾阴亏虚、虚火灼津。"},{"q":"神昏暴厥多见于","o":["喜证","怒证","恐证","悲证","思证"],"a":1,"e":"怒则气上，血随气逆，蒙蔽清窍，故神昏暴厥、面红目赤，甚则呕血，属怒伤气逆之重证。"},{"q":"对心肾阳虚，最有诊断意义的是","o":["心悸怔忡、肢肿形寒","心中悸动、面白神疲","心胸憋痛、舌质暗淡","心悸失眠、腰酸盗汗","腰膝冷痛、畏寒肢冷"],"a":0,"e":"心肾阳虚，心失温养则心悸怔忡，肾阳不化水则水泛肢肿，阳虚失煦则形寒肢冷，三者并见最有诊断意义。"},{"q":"肠虚滑泻证的泻下特点是","o":["时干时稀","大便秘结","下利无度","气味恶臭","里急后重"],"a":2,"e":"肠虚滑泻因脾肾阳虚、固摄无权，故下利无度、滑脱不禁，甚则大便失禁，便质清稀而腹无胀痛。"},{"q":"下列各项中最不易导致月经先期的是","o":["营血亏损","肝郁血热","气虚不摄","阴虚火旺","阳盛血热"],"a":0,"e":"月经先期多由气虚不摄或血热迫血妄行，如阳盛血热、肝郁血热、阴虚火旺；营血亏损则血海不充，多致经行后期、量少。"},{"q":"提示疾病发展变化转折点的是","o":["自汗","盗汗","大汗","战汗","绝汗"],"a":3,"e":"战汗为邪正剧争、正气奋起驱邪之象，汗出热退脉静则邪去正安，汗出热不退、脉疾躁则正不胜邪，为病情转折点。"},{"q":"细脉的脉象是","o":["举之无力，按之空虚","沉细而软，应指无力","极细极软，似有似无","脉体如线，应指明显","浮而细软，应指无力"],"a":3,"e":"细脉脉细如线而应指分明，主气血两虚、湿邪困阻；濡脉浮细而软，弱脉沉细而软，微脉极细极软，三者与细脉有别。"},{"q":"《素问·五脏生成》中，描述为白如枯骨是","o":["主色","客色","善色","恶色","病色"],"a":3,"e":"色白如枯骨，为血气枯槁、脏气衰败，属恶色，主病重；白如鹅羽者润泽有神，方为善色。"},{"q":"芤脉的主病是","o":["实热","瘀血","气滞","失血","气虚"],"a":3,"e":"芤脉浮大中空、如按葱管，因血脱于内、脉道不充而成，主失血与伤阴，多见于大失血之后。"},{"q":"下列除哪项外均属于阳斑的表现","o":["斑色红紫","平铺于皮肤","点小如粟","压之不退色","身热、面赤、脉数"],"a":2,"e":"阳斑色红紫、平铺于皮肤、压之不退色，兼身热面赤脉数；点小如粟、根脚紧束为疹之特点，非阳斑。"},{"q":"以日晡潮热、大便不通、腹痛为辨证要点的属于","o":["热邪壅肺","热扰胸膈","热结肠道","热郁胆经","热扰心神"],"a":2,"e":"热邪结于肠道，腑气不通，故日晡潮热、腹痛拒按、大便不通，甚则神昏谵语，属阳明腑实。"},{"q":"气营两燔的舌象表现为","o":["红绛舌，薄白苔","红绛舌，黄白苔","红瘦舌，黑苔","红舌，苍老滑苔","淡白舌，黄裂苔"],"a":1,"e":"气营两燔为气分热盛而营热已起，故舌红绛而苔黄白相兼，示气分之邪未尽而营热已炽，属气营同病。"},{"q":"阳明经证最不可能出现的是","o":["脉洪大","大汗出","身大热","大便溏","口大渴"],"a":3,"e":"阳明经证为无形邪热亢盛，见身大热、大汗出、口大渴、脉洪大；大便溏属太阴或湿热下利之象。"},{"q":"肝阳上亢头痛的特点是","o":["重痛","胀痛","窜痛","灼痛","隐痛"],"a":1,"e":"肝阳上亢，气血上壅于头，故头痛而胀，兼眩晕、面红目赤、急躁易怒、腰膝酸软、脉弦有力。"},{"q":"以下何脉不属重按始得的脉象","o":["弱脉","牢脉","革脉","伏脉","沉脉"],"a":2,"e":"弱、牢、伏、沉四脉均须重按始得；革脉浮而搏指、中空外坚如按鼓皮，属浮脉类，故不属重按始得。"},{"q":"28脉中，具备虚、沉、小的特点的脉象是","o":["伏脉","弱脉","细脉","濡脉","涩脉"],"a":1,"e":"弱脉沉细而软，兼具位沉、体小、势虚三个特点，主气血俱虚；濡脉位浮，微脉极细极软，细脉不沉。"},{"q":"寒证化热的临床意义是","o":["邪热毒气严重","阳气耗散","疫毒痢初期","痰湿凝聚","阳气旺盛"],"a":4,"e":"寒证化热由寒邪郁久或过用温燥、阳气来复而化热，示机体阳气尚盛、正能抗邪，病势由阴转阳。"},{"q":"脾病虚证的基础证型是","o":["脾不统血证","脾气虚证","脾阴虚证","脾虚气陷证","脾阳虚证"],"a":1,"e":"脾气虚证为脾病虚证的基础，脾阳虚、脾虚气陷、脾不统血多由脾气虚进一步发展而成，故为诸虚之基。"},{"q":"重按实大弦长的脉象是","o":["长脉","弦脉","伏脉","牢脉","紧脉"],"a":3,"e":"牢脉沉取实大弦长、坚牢不移，主阴寒内实、疝气与癥瘕积聚；其位沉而形大势强，与单纯沉脉不同。"},{"q":"下列对主诉的表述，最正确的是","o":["经常腹痛已多年","5年来右胁胀痛","患高血压1年","发热、咳嗽2天","咳喘反复发作20年"],"a":3,"e":"主诉为就诊的主要症状及持续时间，须简明、症状在前时间在后；“经常”“反复”含混，“患高血压”系病名，均不规范。"},{"q":"证候真假的“真”是指","o":["病人提供的资料为真","临床上常见的症状表现","与疾病内在本质相符的证候","整个病程中始终存在的症状表现","与病人既往疾病和体质状态相符的表现"],"a":2,"e":"证候真假之“真”，指与疾病内在本质相符的证候；“假”指与本质不符的表象，辨证须去伪存真、由表及里。"},{"q":"心阴虚证的舌象最有可能是下列哪项","o":["舌红苔黄","舌红绛苔薄黄","舌淡红苔薄","舌红少苔","舌淡红无苔"],"a":3,"e":"心阴虚则心阴不足、虚热内生，故舌红少苔或无苔，兼心悸失眠、五心烦热、盗汗、脉细数。"},{"q":"濡脉和弱脉的共同特征是","o":["迟细而无力","沉而无力","空虚无力","细而无力","浮而无力"],"a":3,"e":"濡脉浮细而软，弱脉沉细而软，二者脉体细、脉势无力相同，仅脉位有浮沉之别，故共同特征为细而无力。"},{"q":"舌体胖大，边有齿痕多为","o":["肾阴不足","肺阴不足","脾虚湿盛","心血不足","肝血不足"],"a":2,"e":"脾虚失运，水湿内停，舌体胖大而受齿列挤压，故边现齿痕，为脾虚湿盛的典型舌象，多伴苔白腻。"},{"q":"寸关尺分候脏腑，《难经》以左寸候","o":["心、膻中","心、胸中","心、小肠","心、大肠","心、心包络"],"a":2,"e":"《难经》以左寸候心与小肠，左关候肝胆，右寸候肺与大肠，右关候脾胃，两尺候肾与膀胱。"},{"q":"导致亡阴的病因病机，错误的是","o":["病久阴竭","持续壮热","吐泻不止","大汗不止","严重冻伤"],"a":4,"e":"亡阴由热邪久留、壮热不退，或吐泻、大汗不止致阴液大量耗失而成；严重冻伤伤阳，所致者为亡阳。"},{"q":"真热假寒证通常不见","o":["脉沉有力","神志昏沉","高热肢厥","面色浮红如妆","胸腹灼热"],"a":3,"e":"真热假寒为内热壅盛、阳郁不达四末，见高热肢厥、胸腹灼热、脉沉有力、神志昏沉；面色浮红如妆属真寒假热。"},{"q":"郑声的病机是","o":["心气不足，神失所养","心气大伤，精神散乱","瘀血阻遏心窍","热扰心神，神明失主","痰湿阻遏心窍"],"a":1,"e":"郑声为神识不清、语言重复、声低无力，由心气大伤、精神散乱所致，属虚证；谵语则由热扰心神而声高有力。"},{"q":"心阳不足时，虚里搏动的特点是","o":["搏动迟弱","绝而不应","虚里动高","数急时止","聚而不散"],"a":0,"e":"虚里为心尖搏动处，心阳不足则推动无力，故搏动迟弱；动而应衣为宗气外泄，绝而不应乃宗气已绝。"},{"q":"手足蠕动的病机是","o":["热极生风","血虚生风","阴虚动风","肝阳化风","寒凝筋脉"],"a":2,"e":"手足蠕动为筋脉失养、虚风内动之象，多见于热病后期阴液耗损或肝阴不足，属阴虚动风。"},{"q":"下列除哪项外脉率均较正常脉率慢","o":["缓脉","弦脉","迟脉","结脉","涩脉"],"a":1,"e":"迟、缓、涩、结四脉脉率均偏慢，缓脉一息四至、结脉缓而时止；弦脉端直以长，脉率不快不慢。"},{"q":"肝郁气滞导致胁痛的特点是","o":["隐痛","灼痛","胀痛","掣痛","绞痛"],"a":2,"e":"肝郁气滞，气机不畅，胁部经气壅滞，故胁痛而胀、走窜不定，随情志变化而增减，脉多弦。"},{"q":"对诊断心肺气虚证最有意义的是","o":["咳喘痰多、动则尤甚","喘息短气、呼多吸少","咳痰清稀、乏力神疲","自汗乏力、喘咳心悸","咳喘无力、自汗畏风"],"a":3,"e":"心肺气虚，心气不足则心悸、自汗，肺气虚弱则喘咳、乏力，两组症状并见方能定位心、肺两脏。"},{"q":"下列哪项属于心病的常见症状","o":["口舌生疮","阴囊湿疹","目泡赤烂","牙龈肿痛","咽喉肿痛"],"a":0,"e":"舌为心之苗，心火上炎则口舌生疮、舌尖红赤；阴囊湿疹属肝经湿热下注，牙龈肿痛属胃火。"},{"q":"目赤胀痛，伴急躁易怒，口干口苦者，属于","o":["肝气犯胃","胆气上逆","肝郁脾虚","肝火上炎","风热上扰"],"a":3,"e":"肝开窍于目，肝火循经上炎则目赤胀痛，火盛则急躁易怒、口干口苦、脉弦数，属肝火上炎证。"},{"q":"身热夜甚、心烦不寐、斑疹隐现，舌红绛，脉细数，其临床意义是","o":["卫分证","气分证","营分证","血分证","热灼营阴"],"a":2,"e":"热灼营阴，营热蒸腾则身热夜甚、舌红绛、脉细数，营热扰心则心烦不寐，热窜血络则斑疹隐现，属营分证。"},{"q":"镜面舌的形成机理是","o":["热甚伤津","水湿上泛","热入营血","胃肠热结","胃无生发之气"],"a":4,"e":"镜面舌为舌苔全部剥落、光洁如镜，由胃阴枯竭、胃无生发之气所致，属胃气将绝之危候。"},{"q":"主痰热、湿热、食积内热的脉象是","o":["滑数脉","浮滑脉","弦数脉","洪数脉","细数脉"],"a":0,"e":"滑主痰湿食积，数主热，故滑数脉主痰热、湿热与食积化热，为邪实热盛之象，多见于痰火内盛者。"},{"q":"下列哪项不属于心阳虚证的辨证要点","o":["心悸","怔忡","心胸疼痛","神疲乏力","阳虚症状"],"a":3,"e":"心阳虚证以心悸怔忡、心胸憋闷疼痛、畏寒肢冷、面色淡白、脉微细为要点；神疲乏力为气虚共性表现。"},{"q":"皮肤、面目发黄，鲜明如橘子色，伴汗液、尿液颜色深黄如黄柏汁，口渴，舌苔黄腻者，属于","o":["阳黄","阴黄","萎黄","黄疸","苍黄"],"a":0,"e":"湿热熏蒸肝胆，胆汁外溢肌肤，故身目俱黄而鲜明如橘，汗尿深黄，兼口渴、苔黄腻，属阳黄。"},{"q":"以猝然昏倒，不省人事，喉中痰鸣，口眼歪斜，半身不遂，舌红苔腻，脉弦有力为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","寒滞肝脉证"],"a":1,"e":"肝阳亢逆无制，阳亢风动，气血上逆蒙蔽清窍，故猝然昏倒、半身不遂、口眼歪斜，舌红苔腻、脉弦有力。"},{"q":"阴黄是指","o":["面色黄鲜明","黄色晦黯如烟熏","面色苍黄","面色淡黄而兼虚浮","面、目、尿俱黄"],"a":1,"e":"阴黄由寒湿困阻脾胃、胆汁不循常道外溢而成，黄色晦黯如烟熏，伴畏寒、纳少、腹胀、脉沉迟。"},{"q":"与惊伤证无关的是","o":["惊悸","坐卧不宁","胆怯","二便失禁","健忘失眠"],"a":3,"e":"惊则气乱，心无所倚、神无所归，故惊悸、坐卧不宁、胆怯、健忘失眠；二便失禁多因恐则气下或肾气不固。"},{"q":"症见腹胀满，疼痛拒按，大便燥结，舌红苔黄厚焦燥，其脉可为","o":["沉紧脉","迟细脉","浮滑脉","沉缓脉","浮紧脉"],"a":1,"e":"此为阳明腑实、燥屎内结，燥屎阻滞脉道，故脉反见迟细有力，即迟脉亦主里实热之例，不可误作虚寒。"},{"q":"下列属于麻疹顺证表现的是","o":["壮热无汗","疹点颜色淡红而黯","疹点突然隐没，神昏喘息","疹出透彻，色泽红润","疹点不能透发，颜色白而不红"],"a":3,"e":"麻疹顺证疹点依序透发、分布均匀、色泽红润、身热渐退；壮热无汗、疹色淡黯、骤然隐没均属逆证。"},{"q":"病人一侧颧下颌上耳周发红肿起，伴有寒热、疼痛者，称为","o":["痄腮","发颐","阳水","阴水","抱头火丹"],"a":1,"e":"发颐生于颐颌之间，红肿热痛、张口受限，多由阳明少阳热毒上攻或温病后余毒未清；痄腮漫肿而多不红。"},{"q":"下列哪项对诊断肾阴虚证最有意义","o":["腰酸耳鸣","舌红无苔","经少经闭","遗精潮热","眩晕健忘"],"a":3,"e":"肾阴虚，虚火扰动精室则遗精，虚热内蒸则潮热盗汗，二者并见最能反映肾阴亏虚、虚火内扰之本质。"},{"q":"主寒证和痛证的脉象是","o":["紧脉","缓脉","革脉","短脉","促脉"],"a":0,"e":"紧脉绷急弹指、状如转索，主寒证、痛证与宿食，因寒性收引、疼痛致脉道挛急而现紧象。"},{"q":"下列各项，属于“病”的概念的是","o":["湿热","胸闷","内风","麻疹","气滞"],"a":3,"e":"病指有特定病因、病机、发展规律与转归的完整过程，麻疹、消渴属病；湿热、气滞为病性，胸闷为症状。"},{"q":"大肠湿热证一般不见下列哪项","o":["肛门灼热","溏结不调","泻下黄糜","便下脓血","里急后重"],"a":1,"e":"大肠湿热见腹痛、泻下黄糜、肛门灼热、里急后重、便下脓血；溏结不调多属肝郁脾虚或脾虚。"},{"q":"咳吐脓血腥臭痰者，多属","o":["肺痈","白喉","肺痿","顿咳","肺痨"],"a":0,"e":"肺痈为热毒壅肺、血败肉腐成脓，故咳吐脓血腥臭痰，兼胸痛、发热、舌红苔黄腻、脉滑数。"},{"q":"舌尖红赤或破溃，多为","o":["心火上炎","外感风热表证","肝经有热","肾阴亏虚","湿热下注"],"a":0,"e":"舌尖属心，心火上炎则舌尖红赤、生疮破溃疼痛，兼心烦失眠、小便短赤，属心火亢盛之证。"},{"q":"寸关尺分候脏腑，右关部侯","o":["心","肺","脾","肝","肾"],"a":2,"e":"寸关尺分候脏腑，左寸候心、左关候肝、左尺候肾；右寸候肺、右关候脾、右尺候命门，故右关候脾。"},{"q":"头痛连项者，属","o":["太阳经头痛","少阳经头痛","阳明经头痛","厥阴经头痛","少阴经头痛"],"a":0,"e":"太阳经脉循项背，故头痛连项、项背强痛属太阳经头痛；阳明痛在前额，少阳痛在两侧，厥阴痛在巅顶。"},{"q":"下列各项，提出“独取寸口”诊脉法的是","o":["《黄帝内经》","《难经》","《脉经》","《伤寒杂病论》","《中藏经》"],"a":1,"e":"《难经·一难》明确提出“独取寸口”以决五脏六腑死生吉凶，自此寸口诊法成为后世脉诊常法。"},{"q":"腹部肿块推之可移，痛无定处，病在","o":["血分","气分","虚痞","结胸","肠痈"],"a":1,"e":"腹中积块推之可移、痛无定处、时聚时散者属气分，为气滞所致；痛有定处、推之不移者属血分，为瘀血。"},{"q":"下列各项，不属现病史内容的是","o":["发病情况","病变过程","做过何诊断","经过哪些治疗","过去曾患何病"],"a":4,"e":"现病史含发病情况、病变过程、诊治经过与现在症状；既往曾患何病属既往史，不属现病史范畴。"},{"q":"属于内湿证辨证要点的是","o":["恶寒微热","皮肤湿疹","瘙痒","纳呆腹泻","脉浮滑"],"a":3,"e":"内湿由脾失健运、水湿内停而生，湿滞中焦则纳呆、脘痞、腹泻、苔腻，故纳呆腹泻为辨证要点。"},{"q":"咳声不扬，痰稠色黄，证属","o":["风热袭表","寒邪客肺","热邪犯肺","痰湿阻肺","阴虚肺燥"],"a":2,"e":"热邪犯肺，灼津为痰，肺气失宣，故咳声不扬、痰稠色黄，兼发热口渴、舌红苔黄、脉数。"},{"q":"经前小腹胀痛，行经后痛减者，多为","o":["气血不足","血瘀","肾虚","寒证","气滞"],"a":4,"e":"经前气血壅滞、气机不畅，故小腹胀痛；经行之后气随血泄，其痛自减，属气滞，痛多胀而走窜。"},{"q":"多食易饥，大便溏泄者，多属","o":["胃火亢盛","胃阴不足","胃强脾弱","阴虚火旺","肝气犯胃"],"a":2,"e":"胃热则腐熟太过而多食易饥，脾虚失运则大便溏泄，此胃强脾弱之候，即胃热脾虚，与单纯胃火不同。"},{"q":"下列哪项舌象特征可见于正常人","o":["红绛舌","裂纹舌","歪斜舌","瘦薄舌","胖大舌"],"a":1,"e":"裂纹舌可见于少数正常人，为生理性裂纹，无他症者不作病论；红绛、歪斜、瘦薄、胖大舌皆属病象。"},{"q":"发热，齿龈红肿疼痛出血，口渴欲饮，舌红，脉数。宜诊断为","o":["肝火炽盛证","心火亢盛证","胃火炽盛证","肺热炽盛证","阴虚火旺证"],"a":2,"e":"足阳明胃经入上齿龈，胃火循经上炎则齿龈红肿疼痛出血，热盛伤津则口渴欲饮，舌红脉数，属胃火炽盛。"},{"q":"胃脘冷痛，喜温喜按，食后痛减，畏寒肢冷，证属","o":["胃气虚证","胃阳虚证","食滞胃脘证","脾气虚证","脾阳虚证"],"a":1,"e":"胃阳不足，虚寒内生，胃失温养，故胃脘冷痛、喜温喜按、食后痛减，兼畏寒肢冷，属胃阳虚证。"},{"q":"不属于面色白的主证是","o":["虚证","寒证","失血","夺气","水饮"],"a":4,"e":"白色主虚证、寒证、失血与夺气，由气血不充、血脉空虚所致；水饮内停多见目胞浮肿、面色淡白虚浮或黧黑。"},{"q":"下列除哪项外，均可导致癃闭","o":["热结膀胱","瘀血内结","肾阳虚衰","肾气不固","结石阻塞"],"a":3,"e":"癃闭由膀胱气化不利所致，热结膀胱、瘀血内结、结石阻塞、肾阳虚衰均可致尿闭；肾气不固则膀胱失约。"},{"q":"以下脉象中，脉位不在浮位的脉象是","o":["洪脉","散脉","芤脉","弱脉","革脉"],"a":3,"e":"洪、散、芤、革四脉位均浮，洪脉浮大有力，芤、革中空，散脉浮散无根；弱脉沉细而软，位在于沉。"},{"q":"虚证常见","o":["五心烦热","大便干结","小便不通","痰涎壅盛","腹痛拒按"],"a":0,"e":"虚证以正气不足为特点，阴虚则五心烦热、盗汗、舌红少苔；大便干结、小便不通、腹痛拒按多属实证。"},{"q":"以咳喘无力、声低懒言、自汗为主要表现的证是","o":["肺气虚证","肺脾气虚证","肺阴虚证","肺肾气虚证","心肺气虚证"],"a":0,"e":"肺气虚弱，宣降无力则咳喘无力、声低懒言，卫外不固则自汗畏风，无脾肾见症，故属肺气虚证。"},{"q":"苔少无津多见于","o":["里热证","寒湿证","表寒证","虚寒证","阴虚证"],"a":4,"e":"苔少无津为胃阴不足、不能上蒸生苔之象，主阴虚；里热证多见苔黄燥，寒湿证多见苔白腻。"},{"q":"发黄干枯，稀疏易落，多属","o":["禀赋不足","血虚受风","疳积","精血不足","血热"],"a":3,"e":"发为血之余、肾其华在发，精血不足则发失濡养，故干枯发黄、稀疏易落；小儿发结如穗者属疳积。"},{"q":"痰白滑而量多，易咳出者，属","o":["风痰","寒痰","热痰","湿痰","燥痰"],"a":3,"e":"湿痰色白而滑、量多易咯，由脾虚湿聚、湿浊化痰所致；寒痰清稀，燥痰黏少难咯，热痰黄稠。"},{"q":"下列哪项不属于心气虚证的辨证要点","o":["心悸","神疲","多梦","胸闷","气虚症状"],"a":2,"e":"心气虚证以心悸、胸闷气短、神疲乏力、自汗、脉虚为辨证要点；多梦多属心血不足或心神不宁。"},{"q":"下列各项，不属痫病的常见临床表现的是","o":["猝然跌倒","四肢抽搐","半身不遂","口吐涎沫","醒后如常"],"a":2,"e":"痫病发时猝然跌倒、昏不知人、四肢抽搐、口吐涎沫、两目上视，移时苏醒如常人；半身不遂为中风后遗。"},{"q":"属于除中表现的是","o":["食欲旺盛","食量逐渐减少","食量逐渐增加","饥而不欲食","重病突然欲食"],"a":4,"e":"除中指久病重病本不能食而突然暴食、食不知饱，为脾胃之气将绝、残灯复明之假神，预后极差。"},{"q":"下列哪项对诊断肾气不固证最无意义","o":["胎动易滑","小便失禁","滑精早泄","齿摇发脱","月经淋漓"],"a":3,"e":"肾气不固以膀胱失约、精关不固、冲任不固为要点，见小便失禁、滑精早泄、月经淋漓、胎动易滑；齿摇发脱属肾精亏虚。"},{"q":"下列各项，不属食滞胃脘证的临床表现的是","o":["胃脘胀痛","嗳腐吞酸","泻下不爽","厌恶食物","呕吐清水"],"a":4,"e":"食滞胃脘见胃脘胀痛、嗳腐吞酸、厌食、泻下不爽、苔厚腻；呕吐清水多属胃寒或胃阳虚。"},{"q":"风寒犯肺证与寒痰阻肺证皆可见到的症状是","o":["咳白痰","咳黄痰","喉间痰鸣","气喘","苔厚"],"a":0,"e":"风寒犯肺与寒痰阻肺均属寒邪在肺、肺气失宣，故皆咳白色痰；前者痰稀薄兼表证，后者痰多稠而喉间痰鸣。"},{"q":"气滞血瘀多见","o":["革脉","虚脉","疾脉","涩脉","实脉"],"a":3,"e":"气滞血瘀，脉道不畅，血行艰涩，故脉来涩滞不畅，如轻刀刮竹，属涩脉所主，亦主精血亏少。"},{"q":"脉来急数而时一止，止无定数，是指","o":["疾脉","促脉","结脉","动脉","代脉"],"a":1,"e":"促脉脉来急数而时有一止，止无定数，主阳热亢盛、气血痰食郁滞，亦见于脏气衰败之危候。"},{"q":"风湿头疼的主要特点是","o":["头痛如裹","头痛晕","头脑空痛","头痛连项","头痛绵绵"],"a":0,"e":"风湿上蒙清窍，清阳不升，故头痛如裹、肢体困重、苔白腻；头空痛属精血亏虚，痛连项属太阳经。"},{"q":"面色淡白无华多属","o":["气滞","血虚","阴虚","亡阴","血瘀"],"a":1,"e":"血虚不能上荣于面，故面色淡白无华，兼唇甲色淡、头晕心悸、舌淡脉细；淡白虚浮则属阳虚水泛。"},{"q":"燥邪犯肺证与肺阴虚证的主要鉴别要点是","o":["有无发热恶寒","有无胸痛咳血","有无口干咽燥","痰量的多少","咯痰的难易"],"a":0,"e":"燥邪犯肺属外感，初起必见发热恶寒等表证；肺阴虚为内伤，病程长而无表证，二者干咳痰少相似。"},{"q":"疮疡红肿高大，根盘紧束，伴有焮热疼痛，称为","o":["痈","疽","疹","疖","疔"],"a":0,"e":"痈由热毒壅聚、气血壅滞而成，红肿高大、根盘紧束、焮热疼痛，易肿易脓易溃易敛，属阳证。"},{"q":"引起哮病发作最常见的诱因是","o":["宿痰内伏","感受外邪","劳倦过度","过食辛辣","情志失调"],"a":1,"e":"哮病以宿痰内伏为夙根，遇外感、异气、饮食、情志等触动伏痰、痰气搏结而发，其中感受外邪最为常见。"},{"q":"虚里位于","o":["左乳下第4、5肋间","左乳下第3、4肋间","右乳下第4、5肋间","右乳下第3、4肋间","剑突下"],"a":0,"e":"虚里为心尖搏动处，位于左乳下第4、5肋间，内应于心，诊其搏动可察宗气盛衰与心气强弱。"},{"q":"脉象“有神”是指","o":["从容和缓","节律一致","柔和有力","沉取有力","不浮不沉"],"a":2,"e":"脉之有神指脉来柔和有力、节律整齐、从容和缓，反映胃气与肾气充盛，虽病亦示正气未败。"},{"q":"神识不清，语无伦次，声高有力者称为","o":["错语","独语","谵语","呓语","郑声"],"a":2,"e":"谵语为神识不清、语无伦次而声高有力，由热扰心神、神明失主所致，属实证；郑声则声低重复，属虚。"},{"q":"微脉、弱脉、濡脉的共同特征是","o":["脉细如线","细小无力","浮取即得","沉取即得","举按有力"],"a":1,"e":"三脉均脉体细小、脉势无力，仅脉位不同：微脉极细极软、似有似无，弱脉沉细而软，濡脉浮细而软。"},{"q":"咽喉色红，肿痛不显者，多辨证为","o":["肺胃热盛","肺肾阴虚","肝火犯肺","肺经风热","肝肾阴虚"],"a":1,"e":"咽喉微红微肿、疼痛不显而日久不愈，为肺肾阴虚、虚火上炎所致，兼口干、五心烦热、舌红少苔。"},{"q":"下列与先天禀赋不足有关的是","o":["桶状胸","鸡胸、漏斗胸、肋如串珠","胸廓不对称","小儿头摇","扁平胸"],"a":1,"e":"鸡胸、漏斗胸、肋如串珠属佝偻病胸，由先天禀赋不足或后天失养、肾精亏虚、骨骼失充而成。"},{"q":"以下脉象中，脉位在浮位的脉象是","o":["沉脉","伏脉","牢脉","濡脉","弱脉"],"a":3,"e":"濡脉浮细而软，轻取即得、重按不显，脉位在浮；沉、伏、牢、弱四脉均须重按始得，脉位俱沉。"},{"q":"热扰神明引起的呕吐多表现为","o":["吐势较缓","吐利并作","朝食暮吐","呕吐脓血","呈喷射状呕吐"],"a":4,"e":"热扰神明、颅内热盛则呕吐呈喷射状，伴头痛、神昏；吐势徐缓声低属虚寒，朝食暮吐属胃反。"},{"q":"脉形细小，脉势软弱，按之欲绝，若有若无，是","o":["散脉","濡脉","微脉","弱脉","细脉"],"a":2,"e":"微脉脉形极细而软，脉势软弱无力，按之欲绝，若有若无，主阳气衰微、气血大虚。细脉虽细小但应指明显，弱脉则沉细而软、须重按始得。"},{"q":"导致半身无汗的病机是","o":["阳气虚损","邪阻经络","中焦郁热","脏腑实热","气虚痰凝"],"a":1,"e":"邪阻经络，气血运行不畅，营卫不能布达于一侧，故见半身无汗，多见于中风偏枯。阳气虚损多致全身汗出异常，不限一侧。"},{"q":"“望色十法”中判断病情之虚实的纲领是","o":["散抟","微甚","浮沉","清浊","泽夭"],"a":1,"e":"望色十法中，微甚指色之浅淡与深浓，色浅淡为正气虚，色深浓为邪气实，故为判断虚实的纲领。浮沉辨表里，清浊辨阴阳。"},{"q":"劳神过度的辨证要点是","o":["失眠多梦","神疲懒言","腰膝酸软","形体消瘦","形体臃肿"],"a":0,"e":"劳神过度耗伤心血、损伤脾气，心神失养则失眠多梦、心悸健忘，故以失眠多梦为辨证要点。"},{"q":"气血两虚证和气虚血瘀证的共同证候表现","o":["心悸失眠","舌质黯","少气懒言","肢体麻木","面色萎黄"],"a":2,"e":"气血两虚证与气虚血瘀证均以气虚为基础，故共同表现为少气懒言、神疲乏力。心悸失眠偏于心，舌质黯、肢体麻木为血瘀之征。"},{"q":"下列各项，属于形盛气虚表现的是","o":["体胖能食，肌肉坚实","体胖食少，神疲乏力","形瘦能食，舌红苔黄","形瘦颧红，皮肤干焦","卧床不起，骨瘦如柴"],"a":1,"e":"形盛气虚指形体肥胖而元气不足，故体胖食少、神疲乏力、舌淡脉弱。体胖能食而肌肉坚实者属形盛气盛。"},{"q":"住院病历中家族史应记录（）的健康状况","o":["直系亲属","父母身体状况","旁系亲属","与本人生活密切相关者","直系亲属和与本人生活密切相关的亲属"],"a":4,"e":"家族史应记录直系亲属及与本人生活密切相关的亲属的健康与患病情况，以判断遗传与传染倾向。仅记父母或旁系均不完整。"},{"q":"下述哪项不属辨证的范畴","o":["分析病因","确定病位","推断病势","判断病性","明确病名"],"a":4,"e":"辨证包括分析病因、确定病位、判断病性、推断病势，明确病名属辨病范畴，故不属辨证。"},{"q":"失眠伴有心悸、纳差及便溏者，属于","o":["心脾两虚","心阴不足","心血亏虚","心肾不交","食积胃脘"],"a":0,"e":"失眠兼心悸为心血不足、心神不安，纳差便溏为脾气虚弱、运化失职，二者合参即心脾两虚证。"},{"q":"弦脉的脉象特征是","o":["绷急弹指，状如转索","沉取有力，实大弦长","轻按搏指，中空外坚","端直以长，如按琴弦","脉位深沉，重按始得"],"a":3,"e":"弦脉端直以长，挺然指下，如按琴弦，主肝胆病、疼痛、痰饮。绷急弹指如转索为紧脉，中空外坚为芤脉。"},{"q":"心悸失眠属心脾两虚证者，最有说服力的依据是","o":["心烦而悸、脉象细数","食少腹胀、乏力舌淡","心悸善惊、多梦易醒","烦热盗汗、舌质红绛","心悸怔忡、面色淡白"],"a":1,"e":"心脾两虚除心悸失眠外，必有脾失健运、气血生化不足之象，故食少腹胀、乏力、舌淡最具说服力。心烦脉细数偏于阴虚。"},{"q":"饥不欲食的病机是","o":["脾失健运","胃强脾弱","胃阴不足","胃火炽盛","脾气亏虚"],"a":2,"e":"胃阴不足，虚热内扰则嘈杂似饥，胃失濡润则不欲食，故饥不欲食为胃阴虚特征。胃火炽盛则消谷善饥。"},{"q":"下列哪项一般不会出现滑苔","o":["脾阳不振","痰饮恋肺","寒湿内生","蓄水证","气滞血瘀"],"a":4,"e":"滑苔主痰饮、水湿内停，脾阳不振、寒湿内生、痰饮恋肺及蓄水证均可见到。气滞血瘀舌多紫黯或有瘀斑，不见滑苔。"},{"q":"下列哪项不属于常色的表现","o":["光明润泽","含蓄隐隐","鲜明暴露","兼见红色","容光焕发"],"a":2,"e":"常色红黄隐隐、明润含蓄，光明润泽、容光焕发，可因体质气候兼见偏红。鲜明暴露属病色，为精气外泄之象。"},{"q":"坐而喜俯，少气懒言多属","o":["痰湿阻肺","水气痰饮","肺实气逆","肺虚体弱","痰饮停肺"],"a":3,"e":"坐而喜俯、少气懒言，为肺气亏虚、宗气不足，故属肺虚体弱。肺实气逆者多坐而仰首，痰饮停肺者多卧而喘促。"},{"q":"浮大中空，如按葱管，是","o":["浮脉","结脉","芤脉","缓脉","濡脉"],"a":2,"e":"芤脉浮大中空，如按葱管，为失血后脉道不充所致，主失血、伤阴。濡脉浮而细软，结脉缓而时止。"},{"q":"下列各项，不属问诊内容的是","o":["了解病人的自觉症状","了解既往的患病情况","发现病人的异常气色","得知以往的诊治情况","了解病人的工作性质及环境"],"a":2,"e":"问诊通过询问了解自觉症状、既往患病情况、以往诊治经过及工作生活环境。观察异常气色属望诊内容。"},{"q":"痰最容易停聚于","o":["脾","心","肺","咽喉","肢体"],"a":2,"e":"肺为贮痰之器，脾为生痰之源，痰生成后最易停聚于肺，故咳嗽痰多、胸闷喘满为痰病最常见表现。"},{"q":"观察舌苔，辨别病邪的性质主要依据","o":["舌苔的有无","舌苔的润燥","舌苔的厚薄","舌苔的颜色","舌苔有根与无根"],"a":3,"e":"苔色辨病邪性质，白苔主表主寒，黄苔主热，灰黑苔主寒极或热极。苔之厚薄辨病位深浅，润燥辨津液盛衰。"},{"q":"面色黑而干焦者，多属","o":["肾阳虚衰，血失温养","阴虚火旺","寒湿带下","瘀血久停","肾虚水饮"],"a":1,"e":"黑而干焦为肾阴亏虚、阴虚火旺，虚火上炎，故色黑而晦暗干燥。黑而暗淡属肾阳虚，黑而肌肤甲错属瘀血。"},{"q":"阳明潮热的时间是","o":["11~13时","13~15时","15~17时","17~19时","19~21时"],"a":2,"e":"阳明潮热见于日晡，即申时15～17时，阳明经气旺于此时，热势随之增高，常伴腹胀便秘。"},{"q":"下列各项，不属胃阴虚证的临床表现的是","o":["胃脘灼痛","口燥咽干","大便干结","消谷善饥","舌红少津"],"a":3,"e":"胃阴虚以胃脘灼痛、口燥咽干、大便干结、舌红少津为特征。消谷善饥为胃火炽盛、腐熟太过所致。"},{"q":"淡白舌可见于","o":["阴虚火旺证","肝阳上亢证","阳虚水湿内停","外感表热证","外感表寒证"],"a":2,"e":"淡白舌主气血两虚与阳虚，阳虚水湿内停则舌淡白而胖嫩、苔白滑。阴虚火旺及表热证舌多红。"},{"q":"膀胱湿热证一般不出现的症状是","o":["小便浑浊","余沥不尽","尿急短黄","排尿灼痛","小便频数"],"a":1,"e":"膀胱湿热见尿频、尿急、尿痛、小便短黄浑浊，由湿热蕴结、气化不利所致。余沥不尽属肾气不固。"},{"q":"脾肾阳虚可见下列哪项","o":["泻下腐臭","泻下黄糜","肛门灼热","完谷不化","里急后重"],"a":3,"e":"脾肾阳虚，命门火衰，脾失温煦，水谷不化，故下利完谷不化，伴畏寒肢冷、腰膝冷痛。泻下黄糜、肛门灼热属大肠湿热。"},{"q":"心阳虚证的舌象最有可能的是下列哪项","o":["舌红绛无苔","舌淡胖苔白滑","舌淡嫩苔薄黄","舌淡白苔黄滑","舌淡红苔薄白"],"a":1,"e":"心阳虚衰，水气不化，故舌淡胖、苔白滑，伴心悸怔忡、畏寒肢冷。舌红绛无苔为阴虚火旺。"},{"q":"舌体歪斜多见于","o":["气血虚衰","肝风夹痰","阴虚动风","热甚动风","寒凝筋脉"],"a":1,"e":"舌体歪斜为肝风夹痰、风痰阻络，舌脉失养而偏侧不用，多见于中风。阴虚动风、热极动风以震颤抽搐为主。"},{"q":"食积证呕吐物的特点是","o":["清稀","酸腐","黄绿苦水","黯红有血块","清水痰涎"],"a":1,"e":"食积停滞胃脘，胃气上逆，宿食腐败，故呕吐物酸腐，伴嗳腐吞酸、脘腹胀满。黄绿苦水属肝胆湿热。"},{"q":"卫分证是","o":["里热证","里寒证","表寒证","表热证","表虚证"],"a":3,"e":"卫分证为温热病初起，温邪袭表，邪在肌表，属表热证，见发热微恶寒、头痛、咽痛、咳嗽、脉浮数。"},{"q":"《脉经》中记载有脉象的种类是多少种","o":["21种","24种","26种","27种","28种"],"a":1,"e":"《脉经》为西晋王叔和所撰，归纳脉象为24种，为后世脉学分类之基础。《濒湖脉学》则载27种。"},{"q":"弱脉的脉象特征为","o":["脉极软而沉细","脉细如线","脉来绷急","迟缓无为","来盛去衰"],"a":0,"e":"弱脉沉细而软，重按始得，主气血两虚、阳气衰微。濡脉浮细而软，细脉细如线而应指明显。"},{"q":"下列哪项对诊断肺肾气虚证最无意义","o":["咳喘无力","声低自汗","苔腻脉滑","腰膝酸软","呼多吸少"],"a":2,"e":"肺肾气虚见咳喘无力、声低自汗、呼多吸少、腰膝酸软。苔腻脉滑为痰湿之象，与气虚不符。"},{"q":"体瘦食多属于","o":["阳虚脾弱","阴虚火旺","气血亏虚","阴虚不足","中焦有火"],"a":4,"e":"体瘦而食多，为胃火亢盛、腐熟太过，消耗精微，故属中焦有火。阳虚脾弱者食少而形瘦。"},{"q":"面目一身俱黄，且黄鲜明如橘皮色的是","o":["萎黄","黄胖","阳黄","阴黄","水饮"],"a":2,"e":"湿热熏蒸，胆汁外溢肌肤，黄色鲜明如橘皮，属阳黄。黄色晦暗如烟熏者为阴黄，属寒湿困脾。"},{"q":"形成脉象的动力是","o":["心脏搏动","脉道通利","气血盈亏","脏腑协同","肾藏精化血"],"a":0,"e":"心脏搏动是形成脉象的动力，心气推动气血沿脉道运行，故脉动应指。脉道通利、气血盈亏为形成脉象的条件。"},{"q":"胃脘胀痛，伴有嗳腐吞酸，呕吐宿食者，多为","o":["寒犯胃脘","食滞胃脘","肝气犯胃","血瘀胃腑","胃火炽热"],"a":1,"e":"食滞胃脘，胃失和降，浊气上逆，宿食腐败，故胃脘胀痛、嗳腐吞酸、呕吐宿食，吐后痛减。"},{"q":"与恐伤证无关的是","o":["气下","伤肾","恶梦惊醒","二便失禁","头目胀痛"],"a":4,"e":"恐伤肾，恐则气下，肾气不固则二便失禁，神气不宁则恶梦惊醒。头目胀痛多属肝阳上亢或肝火上炎。"},{"q":"下述何项与月经后期无关","o":["营血亏损","阳气虚衰","气滞血瘀","寒凝血瘀","阳盛血热"],"a":4,"e":"月经后期多因营血亏损、阳气虚衰、气滞血瘀、寒凝血瘀，致血海不能按时满盈。阳盛血热迫血妄行，致月经先期。"},{"q":"久流浊涕不止者，为","o":["鼻渊","肺痿","鼻衄","肺痈","外感风寒"],"a":0,"e":"鼻渊为鼻流浊涕、久流不止，甚则腥臭，伴头痛鼻塞，多因外邪侵袭或胆经郁热上蒸所致。"},{"q":"以下除哪项均为“得神”的表现","o":["神志清楚","颧赤如妆","反应灵敏","肌肉不削","两目精彩"],"a":1,"e":"得神见神志清楚、两目精彩、反应灵敏、肌肉不削、呼吸平稳。颧赤如妆为虚阳浮越之假神。"},{"q":"虚里是指","o":["左乳下心尖冲动处","心下","胃脘","少腹","胁肋"],"a":0,"e":"虚里指左乳下心尖搏动处，为宗气汇聚之所，可候宗气盛衰。按之动而不紧、缓急均匀为正常。"},{"q":"肾虚体衰可导致的是","o":["足跟胫膝酸痛","四肢游走疼痛","四肢困重","四肢冷痛剧烈","四肢局部红肿灼痛"],"a":0,"e":"肾主骨，腰为肾之府，肾虚则骨髓不充，故足跟胫膝酸痛，劳则加重。四肢游走疼痛属行痹。"},{"q":"下列各项，不属阴脏人的特点的是","o":["头圆颈粗","肩宽胸厚","偏于矮胖","喜静少动","喜凉恶热"],"a":4,"e":"阴脏人形多矮胖，头圆颈粗，肩宽胸厚，喜静少动，喜温恶凉，阳气偏衰。喜凉恶热属阳脏人特点。"},{"q":"鉴别蓄水证与蓄血证，下述哪项最有意义","o":["少腹硬满或不满","口渴引饮或不渴","小便自利或不利","大便泄泻或秘结","脉象浮数或浮缓"],"a":2,"e":"蓄水证膀胱气化不利，小便不利；蓄血证瘀热结于下焦，小便自利。故小便自利或不利为鉴别要点。"},{"q":"耳廓厚大，多属","o":["气血不足","肝胆湿热","阴寒内盛","肾精亏耗","肾气充足"],"a":4,"e":"耳为肾之外窍，耳廓厚大、润泽色红，为肾气充足、先天禀赋强盛。耳薄干枯属肾精亏耗。"},{"q":"白睛色红，多为","o":["肝经风热","肺火、外感风热","脾有湿热","心火上炎","肝经湿热"],"a":1,"e":"白睛属肺，白睛红赤为肺火或外感风热所致；全目赤肿属肝经风热，目眦赤烂属心火，目窠浮肿属脾虚。"},{"q":"大便先干后溏，多属","o":["脾气虚弱","肝郁乘脾","命门火衰","湿盛伤脾","食滞肠胃"],"a":0,"e":"大便先干后溏，为脾虚运化无力，初段糟粕停留较久而干，后段水湿不化而溏，故属脾气虚弱。"},{"q":"肝病日久，两胁胀满疼痛，并见舌质瘀斑，瘀点。其病机是","o":["气滞血瘀","气不摄血","气随血脱","气血两虚","气血失和"],"a":0,"e":"肝病日久，气机郁滞则两胁胀满疼痛，血行瘀阻则舌见瘀斑瘀点，故病机为气滞血瘀，属气血同病。"},{"q":"气血两虚证的舌色为","o":["舌淡红","舌淡白","舌红","舌绛","舌紫"],"a":1,"e":"气血两虚，舌失充盈荣养，故舌色淡白，兼舌体瘦薄、苔薄白，伴神疲乏力、头晕心悸、脉细弱。"},{"q":"病人卧时向外，躁动不安，多属","o":["阳证","阴证","寒证","虚证","虚寒证"],"a":0,"e":"卧时喜向外、躁动不安，为阳热有余、邪气亢实，故属阳证；喜向里、蜷卧静而少动者属阴证。"},{"q":"里热亢盛和阴虚火旺都可见到的舌象是","o":["瘦薄舌","红绛舌","芒刺舌","肿胀舌","青紫舌"],"a":1,"e":"里热亢盛则舌红绛而干，阴虚火旺则舌红绛少苔少津，二者舌色皆红绛，可据苔之有无润燥区分。"},{"q":"下列哪项不是黄厚腻苔的主病","o":["湿热蕴结","痰浊化热","寒湿内结","食积化热","痰热交阻"],"a":2,"e":"黄厚腻苔主湿热蕴结、痰浊化热、食积化热、痰热交阻；寒湿内结苔多白厚腻或白滑，故不属黄厚腻苔所主。"},{"q":"下列哪项不属脉位浮的脉象","o":["散脉","濡脉","微脉","芤脉","革脉"],"a":2,"e":"浮脉类包括浮、洪、濡、散、芤、革，皆轻取即得。微脉极细极软、按之欲绝，不属脉位浮之列。"},{"q":"除下列哪项外均为脾肾阳虚证的大便异常表现","o":["久泻久痢","泻下清冷水液","先干后溏","完谷不化","五更泄泻"],"a":2,"e":"脾肾阳虚见久泻久痢、泻下清冷水液、完谷不化、五更泄泻，因命门火衰、脾失温煦；先干后溏为脾气虚弱之象。"},{"q":"耳鸣声小，如闻蝉鸣，按之减轻，时发时止，属于","o":["肾精亏虚","肝胆火盛","痰浊上蒙","瘀血阻滞","风邪上袭"],"a":0,"e":"耳鸣声小如蝉，按之减轻，时作时止，属虚证，为肾精亏虚、髓海不足。耳鸣声大、按之加重属实。"},{"q":"肝经风热常表现为","o":["睑缘赤烂","目眦淡红","白睛红赤","全目赤肿","目窠浮肿"],"a":3,"e":"肝经风热上攻于目，气血壅滞，故全目赤肿疼痛。睑缘赤烂属脾经湿热，白睛红赤属肺火。"},{"q":"以身目发黄，色鲜明如橘，大便黏滞不爽，小便短黄，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","热极生风证","肝阴虚证"],"a":1,"e":"湿热蕴结肝胆，胆汁外溢则身目发黄鲜明，下注则大便黏滞、小便短黄，舌红苔黄腻、脉弦滑数。"},{"q":"舌苔厚腻如积粉，多为","o":["食积内停","时邪夹湿","痰饮上泛","痰湿化热","湿浊内盛"],"a":1,"e":"苔厚腻如积粉，为湿浊秽浊之邪内蕴，多见于瘟疫初起、时邪夹湿，邪伏膜原，属积粉苔。"},{"q":"胃脘灼痛，口气臭秽，渴喜冷饮，大便秘结，舌红苔黄，脉滑数，证属","o":["食滞胃脘证","寒滞胃脘证","胃热炽盛证","肝郁脾虚证","肝胃不和证"],"a":2,"e":"胃热炽盛，腐熟太过则胃脘灼痛、渴喜冷饮，热灼津伤则口气臭秽、大便秘结，舌红苔黄、脉滑数。"},{"q":"临床常见的气逆证，多与下列哪些脏腑关系密切","o":["肺、脾、肾","肺、胃、肾","肺、胃、肝","心、肝、肺","心、肺、肾"],"a":2,"e":"气逆多见于肺、胃、肝，肺气上逆则咳喘，胃气上逆则恶心呕吐嗳气，肝气上逆则头痛面红、甚则昏厥。"},{"q":"下列哪项为紧张度较低的脉象","o":["弦脉","濡脉","紧脉","革脉","牢脉"],"a":1,"e":"濡脉浮细而软，脉体松弛，按之无力，故紧张度低；弦、紧、革、牢脉皆脉体劲急，紧张度高。"},{"q":"初起多为红斑，迅速形成肿胀、丘疹或水疱，继而水疱破裂、渗液，出现红色湿润之糜烂，此为","o":["缠腰火丹","阳斑","湿疹","瘾疹","热气疮"],"a":2,"e":"湿疹初起红斑，迅即肿胀、丘疹、水疱，破后渗液、出现红色湿润糜烂面，多因湿热蕴结肌肤。"},{"q":"自言自语，喃喃不休，见人语止，首尾不续者称为","o":["错语","独语","谵语","郑声","狂言"],"a":1,"e":"独语为自言自语、喃喃不休，见人语止，首尾不续，多因心气不足或痰浊蒙蔽心神。错语为言错而自知。"},{"q":"属于中医住院病历个人史的是","o":["起病情况","生活习惯","伴随症状","发病以来诊治经过及结果","发病以来一般情况"],"a":1,"e":"个人史包括生活习惯、居住环境、情志嗜好等。起病情况、伴随症状、发病以来诊治经过属现病史。"},{"q":"不属于瘟黄辨证要点的是","o":["来势凶猛","高热神昏","猝然发黄","苔白如积粉","出血发斑"],"a":3,"e":"瘟黄来势凶猛，猝然发黄，高热神昏，出血发斑，为湿热疫毒深入营血。苔白如积粉为瘟疫初起之苔。"},{"q":"燥邪犯肺证见恶寒发热、无汗、脉浮紧，属","o":["秋燥","温燥","凉燥","内燥","风燥"],"a":2,"e":"燥邪犯肺兼恶寒发热、无汗、脉浮紧，为凉燥，属燥邪与风寒并袭。温燥则发热微恶寒、口渴、脉浮数。"},{"q":"下列各项中属于营分证临床表现的是","o":["发热微恶寒","头痛","咽喉肿痛","舌绛","脉浮数"],"a":3,"e":"营分证以身热夜甚、心烦不寐、时有谵语、舌绛而干、脉细数为特征。发热微恶寒、头痛咽痛、脉浮数属卫分。"},{"q":"症见咳嗽痰黄，伴发热微恶风寒，咽喉肿痛，舌苔薄黄，脉浮数，宜辨证为","o":["风热表证","风热犯肺证","肺热炽盛证","痰热壅肺证","燥邪犯肺证"],"a":1,"e":"咳嗽痰黄、咽喉肿痛、苔薄黄、脉浮数，兼发热微恶风寒，为风热犯肺、邪在肺卫。肺热炽盛则但热不寒。"},{"q":"病人的病情表现不宜称作","o":["症状","病候","病机","病形","病状"],"a":2,"e":"症状、病候、病形、病状均指病情表现。病机为疾病发生发展的机理，是辨证所求之本质。"},{"q":"下列各项，不属于构成躯体身形的基本要素的是","o":["皮","肉","脉","络","筋"],"a":3,"e":"躯体身形由皮、肉、脉、筋、骨五体构成，为望形之基础；络为经脉之分支，不在五体之列。"},{"q":"小腹刺痛，小便自利者，为","o":["膀胱虚寒","寒凝肝脉","虫积","脾胃虚寒","蓄血"],"a":4,"e":"小腹刺痛、小便自利，为瘀血蓄于下焦，属蓄血证；膀胱虚寒、寒凝肝脉多痛而喜温，小便无异常。"},{"q":"肝火上炎证最易出现的脉象是","o":["滑数脉","浮滑脉","弦数脉","洪数脉","弦紧脉"],"a":2,"e":"肝火上炎，肝气有余而脉道紧张，火热鼓动血行，故脉弦数。滑数主痰热，洪数主气分热盛。"},{"q":"红黄隐隐，明润含蓄的面色是","o":["病色","常色","善色","恶色","主色"],"a":1,"e":"红黄隐隐、明润含蓄为正常面色，即常色，为胃气充足、气血调和之象。善色为病中色泽明润。"},{"q":"主阴寒内盛，疝气癥瘕的脉象是","o":["革脉","牢脉","实脉","结脉","洪脉"],"a":1,"e":"牢脉沉取实大弦长，坚牢不移，主阴寒内盛、疝气癥瘕。革脉浮而搏指、中空外坚，主亡血失精。"},{"q":"囟陷多属虚证，多因","o":["脑髓有病","温病火邪上攻","吐泻伤津、气血不足","颅内水液停聚","脾肾阳虚"],"a":2,"e":"囟陷为囟门凹陷，多因吐泻伤津、气血不足，脑髓失充所致。囟填则因温病火邪上攻或颅内水停。"},{"q":"下列各项，不属脾不统血证的临床表现的是","o":["皮肤紫斑","面色无华","少气懒言","口臭龈肿齿衄","神疲乏力"],"a":3,"e":"脾不统血见皮肤紫斑、便血崩漏，兼面色无华、少气懒言、神疲乏力。口臭龈肿齿衄为胃火炽盛。"},{"q":"下列不属表证特点的是","o":["外感邪气","起病急","必发展成里证","病情轻","病程短"],"a":2,"e":"表证起病急、病程短、病情轻，多由外感六淫所致，经治可愈，亦可入里，但并非必然传里。"},{"q":"虚实辨证用以辨别","o":["病势","病因","病位","病名","邪正盛衰"],"a":4,"e":"虚实辨证用以辨邪正盛衰，虚指正气不足，实指邪气亢盛；表里辨病位浅深，寒热辨病性。"},{"q":"虚里搏动正常者应为","o":["搏动微弱","散慢不收","搏动应衣","动而不紧","弹手有力"],"a":3,"e":"虚里搏动应手，动而不紧，缓急均匀，为宗气充盈、心气平和。搏动应衣、弹手有力为宗气外泄。"},{"q":"判断气血盛衰的主要依据是","o":["舌体的颜色","舌苔的厚薄","舌体的动态","舌苔的颜色","舌下络脉"],"a":0,"e":"舌体颜色反映气血盛衰，淡白为气血不足，红绛为热盛，青紫为血瘀。舌苔主要反映邪气与胃气。"},{"q":"鉴别表证与里证主要根据","o":["寒热是否并见","头痛轻重","腹痛喜按拒按","咳嗽有无黄痰","脉象迟数"],"a":0,"e":"表证发热与恶寒同时并见，即恶寒发热；里证但热不寒或但寒不热，故以寒热是否并见为鉴别要点。"},{"q":"下列与虚喘发作关系最密切的是","o":["心肺","肝肺","肺肾","脾肺","脾肾"],"a":2,"e":"虚喘病位在肺肾，肺不主气、肾不纳气，故呼吸浅短、呼多吸少、动则喘甚，与肺肾关系最密切。"},{"q":"结、代、促脉的共同点是","o":["脉来急数","脉来时止","脉来迟缓","止有定数","止无定数"],"a":1,"e":"结、代、促三脉共同点为脉来时有一止；结脉缓而时止，代脉止有定数，促脉数而时止，皆属节律失常。"},{"q":"下列哪项属于危重舌象","o":["歪斜舌","裂纹舌","胖嫩舌","紫黯舌","镜面舌"],"a":4,"e":"镜面舌为舌苔全部剥落、光剥如镜，属胃气衰败、胃阴枯竭之危重舌象。裂纹舌、胖嫩舌多主阴虚或脾虚湿盛。"},{"q":"下列哪一项不属于浮脉类","o":["濡脉","散脉","革脉","动脉","芤脉"],"a":3,"e":"浮脉类含浮、洪、濡、散、芤、革，皆轻取即得；动脉脉形如豆、滑数而短，厥厥动摇，属数脉类。"},{"q":"下列哪项不是失眠的常见原因","o":["痰湿内蕴","心胆气虚","心肾不交","肝郁化火","食滞内停"],"a":0,"e":"失眠常见心脾两虚、心胆气虚、心肾不交、肝郁化火、食滞内停、痰热内扰。痰湿内蕴多致嗜睡、头身困重。"},{"q":"肺热壅盛，痰多表现为","o":["痰黄稠","痰脓血腥臭","痰清稀","痰白黏稠","痰稀有泡沫"],"a":0,"e":"肺热壅盛，热灼津液，炼液为痰，故痰黄稠，伴发热口渴、舌红苔黄。痰脓血腥臭为肺痈。"},{"q":"大便中夹杂有脓血黏液者，属于","o":["肝郁脾虚","脾肾阳虚","食滞胃肠","脾气亏虚","大肠湿热"],"a":4,"e":"大便夹脓血黏液，为湿热蕴结大肠、气血壅滞腐败所致，伴腹痛、里急后重、肛门灼热，属大肠湿热。"},{"q":"关节痛剧，伴肿大变形，屈伸受限者，属于","o":["行痹","痛痹","热痹","尪痹","着痹"],"a":3,"e":"关节痛剧、肿大变形、屈伸受限，为尪痹，因风寒湿邪久羁、痰瘀阻络、伤及筋骨。行痹痛无定处。"},{"q":"下列各项，不属气虚证表现的是","o":["神疲乏力","少气懒言","头晕眼花","活动后诸症加剧","尿频清长"],"a":4,"e":"气虚见神疲乏力、少气懒言、头晕眼花、动则诸症加剧、脉虚。尿频清长为肾气不固之象。"},{"q":"下列哪一项属脉症不相应","o":["表证见浮脉","里证见沉脉","久病见浮脉","暴病见浮脉","暴病见洪脉"],"a":2,"e":"久病正气已虚而脉反浮，为脉症不相应，属正虚邪恋或虚阳外越。暴病见浮脉为外感新病之常。"},{"q":"下列哪项不属于气虚证的表现","o":["神疲乏力","畏寒肢冷","少气懒言","舌质淡嫩","脉虚"],"a":1,"e":"气虚以神疲乏力、少气懒言、舌质淡嫩、脉虚为特征；畏寒肢冷为阳虚失于温煦的表现，属阳虚证。"},{"q":"小儿发结如穗，多属","o":["禀赋不足","血虚受风","疳积","精血不足","血热"],"a":2,"e":"小儿发结如穗、枯黄稀疏而易折断，为脾胃虚弱、气血不足、发失荣养所致，多见于疳积。"},{"q":"下列主诉哪项最正确","o":["5年来右胁胀痛","患高血压病1年","经常腹痛已多年","发热、咳嗽2天","咳喘反复发作20年"],"a":3,"e":"主诉为患者就诊的主要症状及持续时间，应简明具体，如发热、咳嗽2天。病名及慢性反复发作的概括不宜作主诉。"},{"q":"解索脉的脉象是","o":["如釜中沸水，浮泛无根","短小坚搏，如循薏苡子","如屋漏残滴，良久一滴","脉在筋肉之间，乍疏乍密，如解乱绳状","脉在皮肤，头定尾摇，似有似无"],"a":3,"e":"解索脉脉在筋肉之间，乍疏乍密，如解乱绳状，为肾气竭绝之怪脉，主元气将脱，病势危重。"},{"q":"区别血分证和营分证的基本要点是","o":["身热躁扰","昏狂谵语","斑疹隐隐","吐血衄血","舌质红绛"],"a":3,"e":"血分证在营分证基础上出现耗血动血，故吐血、衄血、斑疹显露为血分特有。身热夜甚、舌绛为二者共有。"},{"q":"可使舌苔染白的食物或药物是","o":["蛋黄","橘子","牛乳","吸烟","核黄素"],"a":2,"e":"牛乳可使舌苔染白，属染苔，不主病；橘子、核黄素染黄苔，长期吸烟者苔多灰黑而燥厚。"},{"q":"弱脉与濡脉的不同之处主要在于","o":["脉势","脉长","脉位","至数","脉宽"],"a":2,"e":"弱脉沉细而软，濡脉浮细而软，二者脉势脉形相近，区别主要在于脉位一沉一浮，一重按一轻取。"},{"q":"舌色青多见于","o":["阳虚气不化津","气血不足","寒凝血瘀","营血热盛","痰湿中阻"],"a":2,"e":"青色主寒、主痛、主瘀、主惊风，舌色青为阴寒内盛、寒凝血瘀，血脉瘀阻则舌色青紫，可见于胸痹心痛。"},{"q":"下列哪项不属于心阳暴脱证的辨证要点","o":["心悸怔忡","心胸疼痛","神志昏糊","畏寒怕冷","亡阳症状"],"a":3,"e":"心阳暴脱辨证要点为心悸怔忡、心胸疼痛、神志昏糊及亡阳症状，见冷汗淋漓、四肢厥冷、脉微欲绝。畏寒怕冷仅为心阳虚一般表现。"},{"q":"下列哪一项一般不会出现面色苍白","o":["亡阳证","血脱证","阴寒凝滞","脾胃气虚","大失血之人"],"a":3,"e":"面色苍白主亡阳、血脱、大失血及阴寒凝滞，因阳气或血失于上荣。脾胃气虚面色多萎黄不泽。"},{"q":"下列脉象中不主痰饮证的脉象是","o":["滑脉","弦脉","促脉","结脉","濡脉"],"a":4,"e":"痰饮可见滑脉、弦脉，痰阻气机、脉道不畅亦可见促、结；濡脉主虚证与湿困，不主痰饮。"},{"q":"小儿睡眠露睛，最常见的原因是","o":["脾气虚弱","外伤所致","先天不足","气血亏虚","肾精亏损"],"a":0,"e":"小儿睡卧露睛，为脾虚气弱、眼睑失养、约束无力，故最常见于脾气虚弱，多见于吐泻之后。"},{"q":"有形实邪阻闭气机所致疼痛多为","o":["隐痛","窜痛","绞痛","胀痛","重痛"],"a":2,"e":"有形实邪阻闭气机，脉络挛急，气血骤闭不通，故痛势剧烈如绞，痛而拒按，如结石、蛔虫所致。"},{"q":"兼具沉、弦、实、大、长五脉之象，坚牢不移的脉象是","o":["沉脉","长脉","伏脉","牢脉","实脉"],"a":3,"e":"牢脉沉取实大弦长，坚牢不移，为沉、弦、实、大、长五脉之象兼具，主阴寒内盛、疝气癥瘕。"},{"q":"以下哪项表现为疮疡红肿高大，根盘紧束，焮热疼痛","o":["疽","痈","疔","疖","丹毒"],"a":1,"e":"痈为红肿高大、根盘紧束、焮热疼痛，属阳证，易脓易溃易敛。疽漫肿无头、皮色不变，属阴证。"},{"q":"脉不见于寸口，而从尺部斜向手背，称为","o":["斜飞脉","反关脉","鱼翔脉","虾游脉","雀啄脉"],"a":0,"e":"斜飞脉为脉不见于寸口，而从尺部斜向手背；反关脉则脉自寸口背侧行于腕背，二者位置不同。"},{"q":"血分证与营分证的共有症状是","o":["身热夜甚","吐血衄血","手足蠕动","目睛上视","颈项强直"],"a":0,"e":"血分证与营分证均属温热病后期，热灼营阴，故共有身热夜甚、舌绛。吐血衄血为血分证特有。"},{"q":"根据《灵枢•五色》划分法将面部分为不同部位并给予命名，其中颊侧命名为","o":["庭","阙","名堂","蔽","藩"],"a":4,"e":"《灵枢·五色》分面部为庭、阙、明堂、藩、蔽，颊侧为藩，耳门为蔽，鼻为明堂，眉间为阙。"},{"q":"痰热壅肺证，舌象可见","o":["舌淡嫩胖，苔白润滑","舌质红，苔黄厚腻","舌红少苔而有裂纹","舌淡红，苔白腻","舌绛红，苔黄燥"],"a":1,"e":"痰热壅肺，热盛则舌质红，痰浊热蒸则苔黄厚腻，伴咳嗽痰黄稠、胸闷气促、发热口渴、脉滑数。"},{"q":"鼓胀重证中，常与腹部膨隆同时出现的是","o":["脊柱后突","脊柱侧弯","肋如串珠","漏斗胸","腹露青筋"],"a":4,"e":"鼓胀重证腹大如鼓，常伴腹露青筋，即腹壁脉络怒张，因肝脾肾受损、气滞血瘀水停所致。"},{"q":"儿童常见，发作前，咳嗽喷嚏，眼泪汪汪，耳后有红丝出现；发热三四日，疹点从头面到胸腹四肢，形如麻粒，抚之触手，此为","o":["痱子","风疹","湿疹","隐疹","麻疹"],"a":4,"e":"麻疹先有咳嗽喷嚏、眼泪汪汪、耳后红丝，发热三四日后疹出，从头面至胸腹四肢，形如麻粒、抚之触手。"},{"q":"舌苔腻而滑，多为","o":["时邪夹湿","外感风寒","食积内停","痰饮上泛","痰湿化热"],"a":3,"e":"苔腻而滑，为痰饮内停、水湿上泛，故主痰饮。苔厚腻如积粉属时邪夹湿，苔黄腻为痰湿化热。"},{"q":"可作为鉴别燥邪犯肺证与肺阴虚证的症状是","o":["发热恶寒","痰中带血","口唇干燥","尿少便干","痰少而黏"],"a":0,"e":"燥邪犯肺兼表证，见发热恶寒；肺阴虚为内伤虚证，无表证。二者皆见口唇干燥、痰少而黏。"},{"q":"紧脉的脉象特征是","o":["如按琴弦","如按葱管","如按鼓皮","如牵绳转索","如按刀刃"],"a":3,"e":"紧脉脉来绷急，左右弹指，如牵绳转索，主寒、主痛、主宿食；如按琴弦而端直者则为弦脉。"},{"q":"浮大中空的脉象是","o":["散脉","革脉","洪脉","芤脉","濡脉"],"a":3,"e":"芤脉浮大中空，如按葱管，为失血后阴血亏虚、脉道不充所致。革脉浮而搏指、中空外坚如按鼓皮。"},{"q":"观察舌苔，辨别病位的深浅主要依据","o":["舌苔的有无","舌苔的润燥","舌苔的厚薄","舌苔的颜色","舌苔的有根与无根"],"a":2,"e":"苔之厚薄辨病位深浅，苔薄邪多在表，苔厚邪已入里。苔色辨病邪性质，润燥辨津液盛衰。"},{"q":"“望色十法”中“浮沉”是判断病情的","o":["表里","虚实","阴阳","轻重","新久"],"a":0,"e":"望色十法中浮沉辨表里，色浮显于皮肤为病在表，沉隐于内为病在里。微甚辨虚实，清浊辨阴阳。"},{"q":"五色晦暗枯槁者为","o":["主色","客色","善色","恶色","病色"],"a":3,"e":"五色晦暗枯槁、搏聚不散为恶色，示脏腑精气衰败、病重。善色虽病而色泽明润，主病轻预后好。"},{"q":"饭后嗜睡，神倦，食少纳呆者，为","o":["热入心包","肝阳化风","痰湿困脾","心肾阳虚","中气不足"],"a":4,"e":"饭后困倦嗜睡，神疲乏力，食少纳呆，为脾气虚弱、运化无力、清阳不升，故属中气不足。"},{"q":"下列哪项对诊断膀胱湿热证最无意义","o":["血尿","尿频","尿痛","尿急","尿失禁"],"a":4,"e":"膀胱湿热见尿频、尿急、尿痛、血尿，为湿热蕴结膀胱、气化不利、灼伤血络。尿失禁属肾气不固。"},{"q":"长期微热，烦劳则甚，兼见少气自汗，属","o":["湿温潮热","气虚发热","阴虚潮热","阳明潮热","气郁发热"],"a":1,"e":"长期微热，烦劳则甚，兼少气自汗，为脾气虚弱、清阳不升、虚热内生，属气虚发热，宜甘温除热。"},{"q":"鼻头红肿生疮，多属","o":["胃热或血热","肺胃湿热","外感风热","湿热郁结","阴虚肺燥"],"a":0,"e":"鼻头红肿生疮，为胃热或血热上蒸于鼻所致；鼻流清涕属外感风寒，鼻翼煽动属肺热壅盛。"},{"q":"色红或青紫，点大成片，平摊于皮肤下，摸之不碍手，此为","o":["痈","疹","斑","疽","痱子"],"a":2,"e":"斑色红或青紫，点大成片，平摊于皮下，抚之不碍手，压之不退色，属血热妄行或阳明热盛。"},{"q":"下列各项，不属既往史内容的是","o":["居住或旅游过的地域","曾接受过何种预防接种","以往患过何种其他疾病","是否做过何种手术治疗","有无药物之类的过敏史"],"a":0,"e":"既往史记录过去所患疾病、预防接种、手术及药物过敏史。居住或旅游过的地域属个人史。"},{"q":"口甜而黏腻多为","o":["肝脾不和","脾胃气虚","肝胆湿热","脾胃湿热","肝胃不和"],"a":3,"e":"口甜而黏腻，为脾胃湿热、浊气上泛，属脾瘅之征；口淡属脾胃气虚，口苦属肝胆火热上炎。"},{"q":"热极生风证与肝阳化风证均可见到的症状是","o":["高热","头重脚轻","肢体抽搐","角弓反张","腰膝酸软"],"a":2,"e":"热极生风与肝阳化风均有肝风内动，故见肢体抽搐、甚则痉挛。高热仅见于热极生风，头重脚轻属肝阳化风。"},{"q":"舌淡苔黑滑者，多属","o":["痰火内蕴","阴虚火旺","热盛伤津","阳虚寒盛","湿热郁蒸"],"a":3,"e":"舌淡胖嫩、苔黑而滑润，为阳虚寒盛、水湿不化，阴寒内盛之象。苔黑而燥裂属热盛伤津。"},{"q":"面色与口唇青紫者，多属","o":["阴寒内盛","肝郁脾虚","心血瘀阻","高热抽搐","胁下癥积"],"a":2,"e":"面色与口唇青紫，为瘀血内阻、血脉运行不畅，多见于心阳不振、心血瘀阻。阴寒内盛者青紫而伴畏寒。"},{"q":"脉形如豆，滑数而短，厥厥动摇，关部尤显，是","o":["微脉","动脉","疾脉","结脉","弱脉"],"a":1,"e":"动脉脉形如豆，滑数而短，厥厥动摇，关部尤显，主惊恐与疼痛，因气血相搏、脉道拘急而动摇。"},{"q":"鱼翔脉的脉象是","o":["短小坚搏，如循薏苡子","如釜中沸水，浮泛无根","如屋漏残滴，良久一滴","脉在皮肤，时而跃然而去，须臾又来","脉在皮肤，头定尾摇，似有似无"],"a":4,"e":"鱼翔脉脉在皮肤，头定尾摇，似有似无，为三阴寒极、阳气将绝之怪脉，主病势危重难治。"},{"q":"下列关于实证和虚证鉴别错误的是","o":["实证疼痛拒按，虚证疼痛喜按","实证多发热，虚证多恶寒","实证声高气粗，虚证声低息微","实证舌质老，虚证舌质嫩","实证脉有力，虚证脉无力"],"a":1,"e":"实证多发热，虚证亦可见发热，如气虚发热、阴虚潮热，故虚证并非多恶寒；畏寒多见于阳虚。"},{"q":"下列除哪项外，皆肾气不固所致","o":["尿频而清","余沥不尽","小便失禁","尿频而痛","遗尿"],"a":3,"e":"肾气不固见尿频而清、余沥不尽、小便失禁、遗尿。尿频而痛为湿热蕴结膀胱之膀胱湿热。"},{"q":"“O”形腿又称","o":["膝内翻","膝外翻","足内翻","足外翻","鹤膝风"],"a":0,"e":"O形腿两膝不能并拢，小腿向内弯曲，故称膝内翻。X形腿两膝并拢而踝部分离，称膝外翻。"},{"q":"舌体瘦薄而色淡者，多属","o":["阴津亏虚","热盛津伤","气血两虚","阳气亏虚","寒湿内蕴"],"a":2,"e":"舌体瘦薄而色淡，为气血两虚、舌失充盈濡养；舌瘦薄而色红绛少苔有裂纹者，属阴虚火旺。"},{"q":"面色紫黯黧黑，伴有肌肤甲错多因","o":["肾阴亏虚","瘀血阻络","肾虚水饮","肾气亏虚","肾阳亏虚"],"a":1,"e":"面色紫黯黧黑，伴肌肤甲错，为瘀血阻络、肌肤失养。黑而干焦属肾阴虚，黑而暗淡属肾阳虚。"},{"q":"下列哪项不符合斑的临床表现","o":["点大成片","色深红或青紫","平铺于皮下","压之退色","抚之不碍手"],"a":3,"e":"斑压之不退色，因血溢皮下、瘀于肌腠；疹高出皮肤、抚之碍手，压之退色，二者以此为辨。"},{"q":"疟疾可见","o":["浮脉","弦脉","芤脉","散脉","洪脉"],"a":3,"e":"官方答案为【散脉】，但依据教材，正确答案为【弦脉】。疟疾为疟邪伏于少阳、枢机不利，脉多弦，弦脉主肝胆病与疟疾；散脉主元气离散、脏腑精气衰败，见于危重之候。"},{"q":"睡中咬牙啮齿，多辨证为","o":["肾阴虚","胃热或虫积","肝风内动","阳明热盛","脾虚"],"a":1,"e":"睡中啮齿，多因胃热炽盛或肠道虫积，扰动心神、筋脉不和所致。小儿多见虫积，成人多见胃热。"},{"q":"濡脉的脉象是","o":["浮数无根","浮而细软","沉细而软","浮大无力","脉细如线"],"a":1,"e":"濡脉浮而细软，轻取即得，重按不显，主虚证与湿困，因湿邪压抑脉道；沉细而软者为弱脉。"},{"q":"尿后余沥不尽多因下列何项所致","o":["肾精不足","肾阴亏虚","瘀血内阻","肾气不固","结石阻塞"],"a":3,"e":"尿后余沥不尽，为肾气不固、膀胱失约，排尿后气化无力、尿液不能尽出。结石阻塞多伴尿痛、尿流中断。"},{"q":"风热犯肺证与肺热炽盛证的鉴别，可根据是否伴有","o":["咽喉肿痛","口干口渴","咳脓血痰","恶寒发热","苔黄脉数"],"a":3,"e":"风热犯肺兼表证，见恶寒发热；肺热炽盛为里热，但热不寒。二者皆见咽喉肿痛、口干、苔黄脉数。"},{"q":"下列不属于正常脉象的生理变异的是","o":["妊娠期脉常见滑数而冲和","老人脉多兼弦","运动员脉多缓而有力","发热后脉滑数有力","瘦人脉偏浮"],"a":3,"e":"正常脉象可因年龄、体质、季节而变异，老人脉多弦、瘦人脉偏浮、妊娠脉滑数冲和。发热后脉滑数有力属病脉。"},{"q":"脉沉细，应指无力，为","o":["微脉","细脉","濡脉","弱脉","虚脉"],"a":3,"e":"弱脉沉细而软，应指无力，主气血两虚、阳气衰微。微脉极细极软、按之欲绝，细脉虽细而应指明显。"},{"q":"热势较高，日晡热甚，兼腹胀便秘者，属","o":["气分壮热","骨蒸潮热","阳明潮热","湿温潮热","气郁发热"],"a":2,"e":"热势较高，日晡即申时热甚，兼腹胀满、大便秘结，为阳明腑实、燥热内结，属阳明潮热。"},{"q":"痰湿内阻的特征表现是","o":["胸闷气短","胸闷气喘","胸闷胁胀","胸闷刺痛","胸闷痰多"],"a":4,"e":"痰湿内阻，肺失宣降，故胸闷痰多、苔白腻、脉滑。胸闷刺痛属心血瘀阻，胸闷胁胀属肝气郁结。"},{"q":"以重手按压或推寻身体的局部，以了解其深部有无压痛或肿块，称为","o":["按法","触法","摸法","叩法","诊法"],"a":0,"e":"重手按压或推寻局部，了解深部有无压痛、肿块，称为按法。轻触局部了解凉热润燥者为触法。"},{"q":"属于八纲证候错杂关系的是","o":["真寒假热证","上热下寒证","实证转虚证","表实热证","里虚寒证"],"a":1,"e":"八纲证候错杂指表里寒热虚实同时并存，上热下寒证即属寒热错杂。真寒假热属证候真假。"},{"q":"证候真假的“假”是指","o":["临床不常见的症状表现","因个体差异而出现的特殊表现","病人叙述虚假的病情资料","起病时出现，一段时间后消失的症状","与病理本质不符的症"],"a":4,"e":"证候真假之假，指与病理本质不符的症状，即疾病过程中出现的假象，如真寒假热之面赤。"},{"q":"下列哪一项不是热证的表现","o":["舌鲜红少苔","苔灰黑而干燥","舌红苔黄","舌红绛而痿软","舌质淡而青紫湿润"],"a":4,"e":"热证舌多红、绛或舌红绛少苔、苔黄燥。舌质淡而青紫湿润，为阳虚寒盛、血行瘀滞之象。"},{"q":"肠燥津亏证与肠热腑实证的鉴别可根据","o":["有无大便干燥","有无小便短少","有无舌红苔黄","有无腹满坚硬","有无腹胀疼痛"],"a":3,"e":"肠燥津亏证以便秘干燥、口干舌红少津为主，腹无所苦；肠热腑实证燥屎内结，腹满硬痛而拒按。有无腹满坚硬是二者的鉴别要点。"},{"q":"不属现病史内容的是","o":["发病情况","病变过程","做过何诊断","经过哪些治疗","过去患过何病"],"a":4,"e":"现病史包括发病情况、病变过程、诊治经过及现在症状；过去患过何病属既往史，为本次发病之前的情况，不列入现病史。"},{"q":"虚脉的脉象特征为","o":["举之泛泛有，重按稍减而不空","三部脉举之无力，按之空虚","浮大中空，如按葱管","浮散无力，漫无根蒂，稍用力则按不着","浮而细软"],"a":3,"e":"官方答案为【浮散无力，漫无根蒂，稍用力则按不着】，但依据教材，正确答案为【三部脉举之无力，按之空虚】。虚脉主虚证，脉道不充，故举按皆无力而空虚；浮散无根、稍按即无者为散脉。"},{"q":"与生活密切接触有关的疾病是","o":["肺痨","头痛","水肿","中风","消渴"],"a":0,"e":"肺痨由痨虫犯肺，随咳嗽、喷嚏飞沫经呼吸道传播，与生活密切接触相关；头痛、水肿、中风、消渴均非接触传染性疾病。"},{"q":"望痰有助于诊察哪些脏腑的功能状态及病邪的性质","o":["肺脾肾","肺肝肾","心肺肝","肺胃肾","心肺肾"],"a":0,"e":"痰由水液代谢失常而成，肺主通调水道、脾主运化水湿、肾主水，故望痰可察肺脾肾三脏的功能状态与病邪性质。"},{"q":"下列哪项不属于证候真假","o":["阴盛格阳证","上寒下热证","至虚有盛候","大实有羸状","阳盛格阴证"],"a":1,"e":"证候真假指本质与现象不符，如阴盛格阳、阳盛格阴、至虚有盛候、大实有羸状；上寒下热属寒热错杂，是不同部位同时出现性质相反的证候。"},{"q":"腹部高度胀大如鼓，称为","o":["结胸","虚痞","水饮","食积","臌胀"],"a":4,"e":"腹部胀大如鼓、皮色苍黄、脉络显露者为臌胀，因肝脾肾受损、气滞水停血瘀而成；结胸以心下硬满疼痛为主。"},{"q":"阴虚证中少见","o":["心阴虚","肺阴虚","肝阴虚","脾阴虚","肾阴虚"],"a":3,"e":"阴虚证以心、肺、肝、肾阴虚为常见，脾多病气虚、阳虚，脾阴虚临床少见，故阴虚诸证中脾阴虚最为少见。"},{"q":"濡脉的脉象特征是","o":["浮大无力","沉细而软","浮细而软","极细极软","脉细如线"],"a":2,"e":"濡脉浮细而软，轻取即得，重按不显，主诸虚与湿证；沉细而软者为弱脉，二者之别在于脉位浮沉。"},{"q":"下列哪项与弦脉所主病症无关","o":["肝胆病","诸痛证","痰饮证","宿食","虚劳"],"a":3,"e":"弦脉主肝胆病、诸痛、痰饮及老年脉道失柔；宿食内停阻滞气机多见滑脉，与弦脉所主无关。"},{"q":"妊娠后期出现音哑或失音者，称为","o":["金实不鸣","夺气","金破不鸣","子瘖","恶阻"],"a":3,"e":"妊娠后期因胎阻经络、肾精不能上承而音哑甚至失音者称子瘖；金实不鸣为外邪闭肺，金破不鸣为肺气亏损。"},{"q":"真寒假热的面色是","o":["满面通红","红黄隐隐","两颧潮红","两颧泛红如妆","面色萎黄"],"a":3,"e":"真寒假热为阴寒内盛、虚阳浮越，面色见两颧泛红如妆、游移不定；满面通红属实热，两颧潮红属阴虚。"},{"q":"胃气不足，胃阴枯竭，可形成","o":["有根苔","腐苔","剥脱苔","滑苔","腻苔"],"a":2,"e":"剥脱苔为舌苔部分或全部剥落，多因胃气不足、胃阴枯竭，苔失化生之源；腐苔、腻苔主实邪与湿浊。"},{"q":"情绪抑郁，胸闷不畅而发出长吁或短叹声的是","o":["呃逆","太息","嗳气","喷嚏","喘息"],"a":1,"e":"情绪抑郁、胸闷不畅时发出长吁短叹以舒解气机者称太息，多因肝气郁结；呃逆、嗳气皆属胃气上逆出声。"},{"q":"以吐血、衄血，面红目赤，胁肋灼痛，口干口苦，烦躁失眠，大便秘结，小便短黄，舌红苔黄，脉弦数为主要表现的证是","o":["肝胆湿热证","肝风内动证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":3,"e":"肝火上炎则面红目赤、胁肋灼痛、口苦烦躁，火热迫血妄行则吐血衄血，舌红苔黄、脉弦数为肝火炽盛之征。"},{"q":"肾阳不足所致腰痛的特点为","o":["冷痛绵绵不休","刺痛固定不移","重痛活动受限","隐痛喜按","疼痛游走不定"],"a":0,"e":"肾阳不足，腰府失于温煦，故腰痛冷痛绵绵、喜温喜按、遇劳加重；刺痛属瘀血，重痛属湿邪。"},{"q":"四肢抽搐，角弓反张，颈项强直，两目上视者，多属","o":["风中脏腑","肝风内动","风中经络","中风脱证","中风闭证"],"a":1,"e":"四肢抽搐、角弓反张、颈项强直、两目上视属痉病，为肝风内动的典型表现；风中脏腑以突然昏仆、半身不遂为主。"},{"q":"腹部肿块，时聚时散，按之无形，痛无定处，为","o":["癥积","瘕聚","虫积","燥屎","蓄水"],"a":1,"e":"瘕聚指腹中肿块时聚时散、按之无形、痛无定处，属气机阻滞；癥积则固定不移、按之有形、痛有定处。"},{"q":"命名痰、悬、支、溢四饮的依据是","o":["饮邪的性质","饮停的部位","饮邪的多少","饮停的先后","饮停的原因"],"a":1,"e":"痰饮、悬饮、支饮、溢饮依水饮停聚部位命名：停于胃肠为痰饮，停于胸胁为悬饮，停于肺为支饮，溢于肢体为溢饮。"},{"q":"三部举按均有力的脉象是","o":["滑脉","紧脉","实脉","弦脉","洪脉"],"a":2,"e":"实脉三部举按均有力，为邪气亢盛、正气不虚、正邪剧争之象；滑、紧、弦、洪各有其脉形特点，不以举按皆有力为特征。"},{"q":"下列各项，不属湿热蕴脾证的临床表现的是","o":["纳呆厌食","呕恶口苦","口甜或口黏","便溏不爽","面色晦黄"],"a":4,"e":"湿热蕴脾则纳呆呕恶、口甜口黏、便溏不爽、身目发黄而色鲜明；面色晦黄属寒湿困脾或脾虚，非湿热之象。"},{"q":"下列各项，属于“体征”的是","o":["头晕头重","恶心欲吐","神疲乏力","手指麻木","大便腥臭"],"a":4,"e":"体征是医生诊察所得的客观征象；大便腥臭需医者嗅闻而知，头晕、恶心、乏力、指麻均属病人自觉的症状。"},{"q":"下列哪项不属于心阳虚证的常见症状","o":["心悸","心痛","心烦","气短","自汗"],"a":2,"e":"心阳虚则鼓动无力、温煦失职，见心悸、心痛、气短、自汗、畏寒肢冷；心烦属心神被扰，见于心阴虚、心火亢盛。"},{"q":"脉来急速，一息七八至者为","o":["促脉","疾脉","动脉","洪脉","紧脉"],"a":1,"e":"疾脉脉来急数，一息七八至，主阳极阴竭、元气欲脱；促脉数而时止，动脉数而形短，至数均不至此。"},{"q":"与地方水土失调密切相关的是","o":["乳蛾","发颐","痄腮","瘿瘤","瘰疬"],"a":3,"e":"瘿瘤生于颈前，多因久居山区、水土缺碘，兼情志失调、气结痰凝而成，与地方水土密切相关；乳蛾、痄腮属外感疫毒为患。"},{"q":"咳吐脓血腥臭痰，或吐脓痰如米粥者，属","o":["肺痿","肺痨","肺胀","肺痈","热痰"],"a":3,"e":"咳吐脓血腥臭痰，或吐脓痰如米粥，为热毒壅肺、血肉腐败成痈，是肺痈的特征；肺痿则以咳吐浊唾涎沫为主。"},{"q":"吸气时间延长，多因吸气困难所致，常见于","o":["哮喘","肺胀","悬饮","痰饮停肺、急喉风、白喉","鼓胀、胸腔积液"],"a":3,"e":"吸气时间延长属吸气性呼吸困难，见于痰饮停肺、急喉风、白喉等上气道阻塞；呼气延长则见于哮喘、肺胀。"},{"q":"黄燥苔常见于","o":["虚热证","湿热证","实热证","假热证","表热证"],"a":2,"e":"黄苔主热，苔黄而干燥为热盛伤津，见于实热证；湿热则黄而腻，表热苔多薄黄，虚热苔少而剥。"},{"q":"以皮肤瘙痒，肢体麻木，屈伸不利，肌肉瞤动，爪甲不荣，面白无华，舌质淡白，脉细或弱为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚风动证","热极生风证","肝胆湿热证"],"a":0,"e":"血虚不能濡养肌肤筋脉，故皮肤瘙痒、肢体麻木、肌肉瞤动、爪甲不荣，面白舌淡、脉细弱为血虚之征，属血虚生风。"},{"q":"症见咳喘痰多色白，甚至喉中哮鸣，伴形寒肢冷，舌淡苔白腻，脉濡缓者，应辨证为","o":["饮停胸胁证","风寒犯肺证","寒湿困脾证","肾不纳气证","寒痰阻肺证"],"a":4,"e":"寒痰阻肺则咳喘痰多色白、喉中哮鸣，兼形寒肢冷、舌淡苔白腻、脉濡缓；风寒犯肺以表证为主，痰量不如是之多。"},{"q":"阴虚火旺的舌象可见","o":["舌灰黑而干燥","舌红苔黄","舌红苔灰黑而腻","舌红苔黄腻","舌绛苔少"],"a":4,"e":"阴虚火旺，虚火上炎则舌绛，阴液亏耗则苔少；舌红苔黄为实热，苔灰黑而腻多属痰湿久郁化热。"},{"q":"肝阳上亢所致头痛的特点是","o":["灼痛","隐痛","窜痛","胀痛","绞痛"],"a":3,"e":"肝阳上亢，气血上冲，故头痛而胀，兼眩晕、面红目赤、脉弦；灼痛属火热，窜痛属气滞，隐痛属虚。"},{"q":"某些舌体病变，如舌痛、舌疮等，亦常责之于哪个脏腑","o":["心","肝","脾","肺","小肠"],"a":0,"e":"舌为心之苗，心开窍于舌，心火上炎则舌痛、舌疮、舌尖红赤，故舌体的病变常责之于心。"},{"q":"口角流涎而不自知，睡则更甚，多属","o":["肾寒","肾虚","胃寒","湿热","脾虚"],"a":4,"e":"脾开窍于口，在液为涎，脾气虚弱则固摄无权，涎液外溢而口角流涎、睡则更甚；胃热流涎多伴口臭、口渴。"},{"q":"肺气上逆的病因病机，下述哪项不对","o":["外邪犯肺","痰饮停肺","肾不纳气","肺失宣发","肺失肃降"],"a":2,"e":"肺气上逆多因外邪犯肺、痰饮停肺及肺失宣发肃降，气逆于上而为咳喘；肾不纳气属肾气虚衰、摄纳无权，病本在肾。"},{"q":"上焦病证的临床表现是","o":["身热额红","口燥咽干","手足蠕动","发热汗出","时腹自痛"],"a":3,"e":"上焦病证为温邪袭肺卫，见发热、微恶风寒、汗出、口渴、咳嗽、头痛、舌边尖红、脉浮数；手足蠕动属下焦阴虚风动。"},{"q":"洪脉主病","o":["气分热盛","湿热蕴结","外感表证","肝失疏泄","宿食积滞"],"a":0,"e":"洪脉脉体阔大、充实有力、来盛去衰，为邪热亢盛、气分热盛之象；湿热见濡数，表证见浮，宿食见滑。"},{"q":"津液输布障碍而致舌苔干燥者可见","o":["舌红苔黄","舌红绛有芒刺","舌红绛少苔","舌青紫有瘀斑","舌淡白苔白腻"],"a":4,"e":"津液输布失常则水湿内停，苔见白腻；阳气不化、血不上荣则舌淡白，故舌淡白苔白腻为津凝湿阻之象。"},{"q":"不能归属于阳证的是","o":["面红目赤","疼痛喜按","心烦不宁","脉数有力","发热口苦"],"a":1,"e":"阳证属实热，见面红目赤、心烦不宁、发热口苦、脉数有力；疼痛喜按为正气不足、虚证之征，属阴证。"},{"q":"对心肝血虚证最有诊断意义的是","o":["心悸健忘、面白舌淡","头晕目眩、月经停闭","手足震颤、头晕目眩","视物模糊、爪甲不荣","失眠多梦、肢麻脉细"],"a":4,"e":"心肝血虚，心血不足则失眠多梦，肝血亏虚则肢麻脉细，二者并见最具诊断意义；单纯心悸面白偏于心，视物模糊偏于肝。"},{"q":"对人体生命活动外在表现高度概括的是","o":["神","精","气","血","液"],"a":0,"e":"神是人体生命活动的外在表现，包括精神意识、面目表情、语言气息与形体动态，为五脏精气盛衰的高度概括。"},{"q":"叩诊腹大而胀的病人，叩之如鼓者为","o":["水臌","气胀","食积","癥积","瘕聚"],"a":1,"e":"腹胀叩之如鼓、中空作响者为气胀，因气机壅滞；水臌叩之浊实并有移动性浊音，食积、癥瘕可扪及痞块。"},{"q":"下列不属于望舌苔的是","o":["腐腻","有根无根","老嫩","黄或灰黑","剥落偏全"],"a":2,"e":"望舌苔包括苔色与苔质，如黄或灰黑、腐腻、剥落偏全、有根无根；老嫩属望舌质的内容，反映邪正盛衰。"},{"q":"下列哪项与瘦薄舌形成有关","o":["脾肾阳虚","气血瘀积","心脾热盛","气血两虚、阴虚火旺","寒湿内生"],"a":3,"e":"瘦薄舌为舌体瘦小而薄，因气血阴液亏虚、舌失充养；气血两虚者舌色淡，阴虚火旺者舌红绛而瘦。"},{"q":"口干但欲漱水不欲咽者，多属","o":["风热袭表","里热亢盛","阳气虚衰","瘀血内阻","湿热内蕴"],"a":3,"e":"瘀血内阻，津液输布受阻而不上承，故口干但欲漱水不欲咽；里热伤津者口渴喜饮，饮水自救。"},{"q":"可见于表邪入里的有","o":["昨起恶寒发热，现仅发热恶热","吐泻后烦渴多饮","起病即舌红苔黄","晨起头痛恶风脉浮数","发热重微恶寒"],"a":0,"e":"表证恶寒发热并见，邪入于里则恶寒消失、但热不寒，故由恶寒发热转为但热恶热是表邪入里的表现。"},{"q":"下列除哪项外为脉体较长的脉象","o":["实脉","牢脉","革脉","动脉","滑脉"],"a":3,"e":"实脉、牢脉、革脉脉体皆长，滑脉亦往来流利而长；动脉形短如豆、厥厥动摇，属短脉之类。"},{"q":"痰阻心脉之心脉痹阻证心胸疼痛的特点是","o":["刺痛","胀痛","冷痛","灼痛","闷痛"],"a":4,"e":"痰浊阻于心脉，气机痹阻，故心胸闷痛、痛引肩背，伴体胖痰多、苔腻脉滑；刺痛属瘀阻，冷痛属寒凝。"},{"q":"以下不属于数脉类的是","o":["疾脉","动脉","数脉","促脉","洪脉"],"a":4,"e":"数脉类包括数、促、疾、动，均以至数急数为特点；洪脉以脉体阔大、来盛去衰为特征，至数不快，不属数脉类。"},{"q":"寸口脉按寸关尺分候脏腑，右寸当候","o":["心与膻中","肝胆与膈","肺与胸中","脾胃","肾与小腹"],"a":2,"e":"寸口分候脏腑，左寸候心与膻中，右寸候肺与胸中，左关候肝胆，右关候脾胃，两尺候肾与小腹。"},{"q":"下列各项，属于寒滞胃脘证的临床表现的是","o":["消谷善饥","饥不欲食","胃痛且势剧","大便秘结","舌红苔黄"],"a":2,"e":"寒邪客胃，阳气被遏，气机凝滞，故胃脘冷痛剧烈、得温则减、遇寒加重，伴苔白脉弦紧；消谷善饥属胃火。"},{"q":"肢体筋脉迟缓，痿软无力，丧失功能，日久可致肌肉萎缩者，多见于","o":["痹证","厥证","癫证","痉证","痿证"],"a":4,"e":"痿证以肢体筋脉弛缓、痿软无力、日久肌肉萎缩为特征，因精血亏虚或湿热浸淫；痹证以关节疼痛为主，痉证以抽搐为主。"},{"q":"以手足蠕动，肢体抽搐，口咽干燥，形体消瘦，五心烦热，舌红少津，脉弦细数为主要表现的证是","o":["血虚生风证","肝阳化风证","阴虚动风证","热极生风证","寒滞肝脉证"],"a":2,"e":"热病后期阴液亏耗，筋脉失养而动风，故手足蠕动、肢体抽搐，兼口咽干燥、五心烦热、舌红少津、脉弦细数。"},{"q":"苔黑而滑润，多属","o":["湿热郁蒸","阴虚火旺","热盛伤津","痰火内蕴","寒盛阳衰"],"a":4,"e":"苔黑而滑润为阴寒内盛、阳气衰微、水湿不化；苔黑而干燥属热盛津枯，灰黑而腻多属痰湿久郁。"},{"q":"气虚类证不包括下列哪项","o":["气虚证","气逆证","气脱证","气陷证","气不固证"],"a":1,"e":"气虚类证包括气虚、气陷、气脱、气不固；气逆证为气机升降失常、上逆为病，属气机失调，不属气虚之类。"},{"q":"脘腹胀痛，走窜不定，嗳气、肠鸣、矢气后胀痛可减，应诊断为","o":["食滞胃肠证","寒滞胃脘证","虫积肠道证","胃肠气滞证","饮停胃肠证"],"a":3,"e":"脘腹胀痛走窜不定，嗳气、肠鸣、矢气后胀痛减轻，为气机阻滞、得通则舒，属胃肠气滞证；食滞者嗳腐吞酸。"},{"q":"恶寒，身热不扬，胸闷，咳嗽，苔白腻属","o":["邪袭肺卫证","湿浊阻肺证","邪陷心包证","湿蒙心包证","邪热壅肺证"],"a":1,"e":"湿邪犯肺，卫阳被遏则恶寒、身热不扬，湿阻肺气则胸闷咳嗽、苔白腻；邪袭肺卫以发热微恶风寒、口微渴为主。"},{"q":"“见微知著”的诊断原理最主要是指","o":["从轻微的表现预测严重的病变","从局部的微小变化测知整体状态","从隐蔽的症状测知明显的症状","从易忽略的体征中求得病情","运用特殊诊法诊断出病证"],"a":1,"e":"见微知著指机体局部常蕴含整体信息，由外显的细微征象可测知全身状态，是司外揣内原理的延伸。"},{"q":"“寒包火”属于","o":["真虚假实","真寒假热","真热假寒","证候错杂","证候转化"],"a":3,"e":"寒包火为外感寒邪而内有郁热，寒热同时并存于不同病位，属表寒里热的证候错杂；真假寒热是本质与现象不符。"},{"q":"属阳证表现的是","o":["恶寒畏冷","倦怠无力","腹痛喜按","大便溏泄","小便短赤"],"a":4,"e":"阳证属实热，见小便短赤、面红、发热、脉数有力；恶寒畏冷、倦怠无力、腹痛喜按、大便溏泄均属阴证虚寒之象。"},{"q":"痰清稀而多泡沫，多属","o":["寒痰","风痰","湿痰","燥痰","热痰"],"a":1,"e":"痰清稀而多泡沫为风痰，因风邪袭肺、津液凝聚；寒痰清稀色白而无沫，湿痰白滑量多，燥痰黏少难咯，热痰黄稠。"},{"q":"坐时常以手抱头，头倾不能昂，神情呆钝，多属","o":["肝阳化风","气虚体弱","水气凌心","精神衰败","肺气壅滞"],"a":3,"e":"坐则以手抱头、头倾不能抬举、神情呆钝，为脏腑精气衰竭、神气将败之象，属危候；气虚体弱者虽倦卧而神清。"},{"q":"以眩晕头摇，舌强语謇，肢体震颤，手足麻木，舌红，脉弦细为主要表现的证是","o":["血虚生风证","肝阳化风证","肝阳上亢证","肝火炽盛证","寒滞肝脉证"],"a":1,"e":"肝肾阴虚，肝阳亢逆无制而化风，故眩晕头摇、舌强语謇、肢体震颤麻木、舌红脉弦细，属上实下虚之候。"},{"q":"腹痛喜温喜按，大便清稀，肢体浮肿，口淡不渴，形寒肢冷，证属","o":["肺气虚证","脾气虚证","胃阳虚证","脾阳虚证","脾肺气虚证"],"a":3,"e":"脾阳亏虚，温运失职，故腹痛喜温喜按、大便清稀、口淡不渴、形寒肢冷；水湿泛溢肌肤则肢体浮肿。"},{"q":"弱脉与濡脉的主要区别在于","o":["脉势","脉态","脉位","节律","至数"],"a":2,"e":"濡脉浮细而软，弱脉沉细而软，二者脉形脉势相近，区别在于脉位之浮沉不同，一浮一沉。"},{"q":"小儿囟门凸出，多属于","o":["温病火邪上攻，脑髓有病","吐泻伤津，或气血不足","肾精亏虚，脑髓失充","肾气不足，发育不良","肾阴不足，虚火上炎"],"a":0,"e":"囟门凸出为囟填，因温病火邪上攻、脑髓有病或颅内水停；囟陷属吐泻伤津、气血不足，解颅为囟门迟闭、颅缝不合。"},{"q":"咳声重浊，痰多色白者，多属","o":["风寒束表","寒邪客肺","痰湿阻肺","阴虚肺燥","热邪壅肺"],"a":2,"e":"咳声重浊、痰多色白易咯，为痰湿阻肺、肺失宣降；风寒束表咳声重而痰少兼表证，阴虚肺燥则咳声清脆少痰。"},{"q":"外感表证失治误治损伤人体正气为","o":["实证","虚证","虚证转实","实证转虚","真虚假实"],"a":3,"e":"外感表证失治误治，邪气未除而正气已伤，病由实转虚，称为实证转虚，属证候的转化过程。"},{"q":"喉中痰鸣，咯痰黄稠量多者属","o":["肺热炽盛证","风热犯肺证","痰热壅肺证","肠热腑实证","肺阴虚证"],"a":2,"e":"痰热壅肺则喉中痰鸣、咯痰黄稠量多，兼发热口渴、苔黄腻、脉滑数；风热犯肺以表证为主，痰少而黄。"},{"q":"宗气外泄之时，虚里搏动应为","o":["微弱","应衣","弹手","数急","迟弱"],"a":1,"e":"虚里为胃之大络，按之应手和缓为常；宗气外泄则搏动躁动应衣，甚至弹手，属宗气失守之危象。"},{"q":"伏脉主要表现为脉象何因素的变化","o":["脉位","脉数","脉形","脉势","脉律"],"a":0,"e":"伏脉重按推筋着骨始得，甚则伏而不见，主邪闭、厥证与痛极，其变化在于脉位的浅深变化。"},{"q":"下列哪项不是导致失眠的常见原因","o":["心肾不交","食滞胃脘","肝郁化火","痰湿内阻","心脾两虚"],"a":3,"e":"失眠多因心脾两虚、心肾不交、肝郁化火、痰热内扰及食滞胃脘，胃不和则卧不安；痰湿内阻多致嗜睡困倦。"},{"q":"风水搏肺证的辨证要点是面、睑浮肿伴见","o":["卫表症状","里实症状","表虚症状","里虚症状","水湿症状"],"a":0,"e":"风水搏肺证由风邪袭表、肺失宣降、水溢肌肤而成，故面睑浮肿而伴恶风发热、脉浮等卫表症状。"},{"q":"下列哪项不是表里证鉴别要点","o":["寒热症状","舌象","内脏证候是否突出","脉象","汗出情况"],"a":4,"e":"表里辨证以寒热是否并见、内脏证候是否突出、舌象与脉象变化为要点；汗出有无表里皆可见，不作鉴别依据。"},{"q":"黄腻苔多见于","o":["寒湿内结","湿热蕴结","燥热伤津","痰饮阻滞","阴虚火旺"],"a":1,"e":"黄苔主热，腻苔主湿浊痰饮，黄腻苔为湿热蕴结、熏蒸舌面；白腻属寒湿，黄燥属燥热伤津。"},{"q":"面色苍黄者，多属","o":["脾胃气虚","肝胆湿热","寒湿郁滞","脾胃湿热","肝郁脾虚"],"a":4,"e":"面色苍黄为黄中透青、暗淡不泽，因肝郁气滞、脾虚失运，气血不能上荣；黄疸之黄鲜明如橘者属湿热。"},{"q":"气虚证多见哪种舌象","o":["舌淡红苔薄白","舌淡瘦苔白腻","舌淡胖苔水滑","舌淡苔薄白","舌紫黯苔少"],"a":3,"e":"气虚则推动无力、血不上荣，故舌色淡白；气化不足而津液未伤，苔仍薄白润泽，为气虚常见舌象。"},{"q":"小儿惊风的面色表现是","o":["额头色青","左颊色青","面色苍白","眉间、鼻柱、唇周色青","面黑淡黯"],"a":3,"e":"小儿惊风属肝风内动，气血郁滞于脉络，故眉间、鼻柱、唇周色青；面色苍白属虚寒，左颊色青主肝病。"},{"q":"表证的形成主要原因是","o":["外邪直中","六淫侵袭","劳倦所伤","食积","虫兽所伤"],"a":1,"e":"表证由六淫、疫疠之邪从皮毛口鼻侵入，邪留肌表、卫气失和而成；劳倦、食积、虫兽所伤多致内伤或里证。"},{"q":"鉴别假神与病情好转的最主要依据是","o":["突然神志清醒，目光转亮","言语不休，语声清亮","欲进饮食，想见亲人","面色无华，两颧泛红如妆","局部症状好转与整体病情恶化不相符合"],"a":4,"e":"假神是精气衰竭、阴阳将绝时突然精神转佳、言语不休、欲进饮食，其局部好转与整体恶化不符，为临终预兆。"},{"q":"以下哪项为脉位沉的脉象","o":["革脉","濡脉","芤脉","牢脉","散脉"],"a":3,"e":"牢脉沉取始得，实大弦长、坚牢不移，脉位在沉；濡、芤、革、散四脉则皆属浮脉之类，主病各异。"},{"q":"热证常见的面色是","o":["青色","赤色","黄色","白色","黑色"],"a":1,"e":"热证气血沸涌、脉络充盈，故面色赤；实热则满面通红，虚热则两颧潮红，赤色总主热证。"},{"q":"青壮年头发稀疏易落，伴头皮瘙痒，多屑多脂者，多为","o":["劳心过度","精血不足","血热化燥","血虚受风","疳积"],"a":2,"e":"青壮年血热化燥，头皮失润，故头发稀疏易落、瘙痒多屑多脂；精血不足者发黄干枯而无瘙痒多屑。"},{"q":"辨别疾病类别的纲领为","o":["表里","标本","寒热","虚实","阴阳"],"a":4,"e":"八纲之中阴阳为总纲，表里、寒热、虚实六纲皆统属于阴阳，故阴阳为辨别疾病类别的纲领。"},{"q":"对诊断心脾两虚证最有诊断意义的是","o":["心悸怔忡、神疲乏力","食少腹胀、面色萎黄","心悸失眠、便溏舌淡","心烦不寐、色红少苔","失眠多梦、舌淡苔白"],"a":2,"e":"心脾两虚为心血不足与脾气虚弱并见，故心悸失眠而食少便溏、舌淡；仅心悸乏力偏于心，食少腹胀偏于脾。"},{"q":"由于地理环境影响，北方人脉象多","o":["浮数","沉实","洪数","弦滑","濡弱"],"a":1,"e":"北方地势高寒，人体腠理致密、阳气内藏，故脉多沉实；南方气候湿热，腠理疏松，脉多濡弱或浮数。"},{"q":"蛔虫腹痛的特点是","o":["大腹隐痛","小腹胀痛","小腹刺痛","脐周腹痛","少腹冷痛"],"a":3,"e":"蛔虫寄居肠道，扰乱气机，故腹痛多在脐周，时作时止，可扪及条索状包块，面有白斑、吐蛔。"},{"q":"关于相反的两种脉象，下列哪一项是错误的","o":["迟脉与数脉","浮脉与沉脉","洪脉与弦脉","滑脉与涩脉","紧脉与缓脉"],"a":2,"e":"浮与沉、迟与数、滑与涩、紧与缓、虚与实皆为性质相反的脉对；洪脉主热盛，弦脉主肝胆痛证，二者不构成相反关系。"},{"q":"以胆怯易惊，心悸怔忡，失眠多梦，烦躁不安，口苦呕恶，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","胆郁痰扰证","肝火炽盛证"],"a":3,"e":"痰热内扰胆腑，胆气不宁，故胆怯易惊、心悸失眠、烦躁不安、口苦呕恶，苔黄腻、脉弦滑数为痰热之象。"},{"q":"尿后为余沥不尽多由于","o":["肾气不固","肾阳虚弱","瘀阻膀胱","膀胱湿热","寒凝肝脉"],"a":0,"e":"肾气不固，膀胱失约，故尿后余沥不尽，甚则小便失禁、遗尿；膀胱湿热见尿频急涩痛，瘀阻则尿细如线。"},{"q":"阳虚证与气虚证的主要区别是","o":["有无少气懒言","有无神疲乏力","脉象是否无力","寒象是否明显","舌质是否淡嫩"],"a":3,"e":"阳虚必兼气虚，故二者皆有神疲乏力、少气懒言、脉弱；阳虚生外寒，形寒肢冷、苔白等寒象为阳虚独具。"},{"q":"濡脉的主病是","o":["气郁，气虚","阴盛，阳极","瘀血，气滞","痰饮，食积","诸虚，湿证"],"a":4,"e":"濡脉浮细而软，主诸虚不足与湿邪困阻；湿性黏滞、气血亏虚皆致脉道充盈不足而脉体软弱。"},{"q":"“舌赤生疮、尿赤涩灼痛”常见于哪组脏腑病变","o":["心与小肠","肾与膀胱","脾与小肠","心与膀胱","肝与膀胱"],"a":0,"e":"心火上炎则舌赤生疮，心移热于小肠则尿赤涩灼痛，此为脏腑相表里、病邪相传的典型表现。"},{"q":"有形实邪阻闭气机导致的疼痛是","o":["冷痛","窜痛","绞痛","胀痛","重痛"],"a":2,"e":"有形实邪如结石、虫积阻闭气机，或寒凝气滞致血脉挛急，痛势剧烈如绞，故称绞痛，多阵发加重。"},{"q":"由于气候影响，平脉在夏天可见","o":["浮","沉","洪","弦","迟"],"a":2,"e":"夏季阳气隆盛，气血充盈，脉来洪大，为平脉随四时变化的正常现象；春脉微弦，秋脉微浮，冬脉微沉。"},{"q":"半表半里证的寒热特点是","o":["但寒不热","但热不寒","寒热往来","发热重恶寒轻","恶寒重发热轻"],"a":2,"e":"邪在半表半里，正邪交争，故恶寒与发热交替出现，即寒热往来，为少阳证的特征性表现。"},{"q":"肾阳不足所致腰痛的特点是","o":["冷痛绵绵不休","刺痛固定不移","重痛活动受限","隐隐作痛喜按","疼痛游走不定"],"a":0,"e":"肾阳亏虚，腰府失煦，故腰痛冷痛绵绵不休、酸软无力、遇劳遇寒加重；刺痛固定属瘀血，重痛属湿。"},{"q":"舌淡胖大，多为","o":["脾肾阳虚，水湿内停","脾胃湿热","痰热内蕴","心脾热盛","血络郁闭"],"a":0,"e":"舌淡胖大因阳气虚弱、水湿内停、舌体充水而胖；脾胃湿热、痰热内蕴多见舌红而胖，血络郁闭则舌青紫。"},{"q":"日晡潮热可见于","o":["湿温病","热入营血","阳明经证","阳明腑证","气虚证"],"a":3,"e":"日晡潮热为热邪入里、阳明腑实、燥屎内结，申时阳明经气旺而热势增高；湿温则为午后身热不扬。"},{"q":"病历书写一律使用阿拉伯数字书写日期和时间，采用（）小时制进行记录","o":["6","12","18","24","48"],"a":3,"e":"病历书写规范要求日期与时间一律用阿拉伯数字，采用24小时制记录，以准确反映病情变化的时间顺序。"},{"q":"导致头发色黄干枯，稀疏易落的主要原因是","o":["精血不足","血虚受风","肾精亏损","疳积","血热化燥"],"a":0,"e":"发为血之余、肾其华在发，精血不足则头发色黄干枯、稀疏易落；血热化燥多伴头皮瘙痒、多屑多脂。"},{"q":"绞痛一般不见于","o":["头颅部","心胸部","腰腹部","脘腹部","胁肋部"],"a":0,"e":"绞痛由有形实邪阻闭气机而作，见于心脉痹阻、胆道蛔虫、石淋及脘腹寒凝；头部之痛多胀多眩，不呈绞痛。"},{"q":"脉象“有根”主要是指","o":["不浮不沉","柔和有力，节律一致","不快不慢","沉取应指有力，尺部尤显","一息四~五至"],"a":3,"e":"脉之有根指尺脉沉取有力、应指不绝，反映肾气未绝；有胃为从容和缓，有神为柔和有力、节律整齐。"},{"q":"心血虚证与心阴虚证皆可见到的症状是","o":["面色淡白","颧红","失眠","舌淡","脉细数"],"a":2,"e":"心血虚与心阴虚皆因心神失养，故均见心悸、失眠、多梦；面白舌淡属血虚，颧红、舌红、脉细数属阴虚。"},{"q":"身热不扬的表现，多由于","o":["脾气虚损","阴经郁热","外感风热","湿遏热伏","阳明腑实"],"a":3,"e":"湿邪黏滞，热为湿遏，热势不能外扬，故身热不扬、午后热甚、汗出热不解，为湿温初起之特征。"},{"q":"下列脉象中脉位浮的是","o":["迟脉","牢脉","濡脉","伏脉","弱脉"],"a":2,"e":"濡脉浮细而软，轻取即得；牢、伏、弱三脉皆属沉脉之类，迟脉以至数言，不以脉位分，当参脉形。"},{"q":"以胁肋胀痛，纳呆腹胀，口苦厌油，泛恶欲呕，舌红，苔黄腻，脉弦滑数为主要表现的证是","o":["寒滞肝脉证","肝胆湿热证","肝郁气滞证","胆郁痰扰证","肝阴虚证"],"a":1,"e":"湿热蕴结肝胆，疏泄失职则胁肋胀痛、口苦厌油、泛恶欲呕，胆汁外溢可见身目发黄，苔黄腻、脉弦滑数为湿热之征。"},{"q":"热证转寒的临床意义是","o":["阳气偏盛","正气耗伤","痰湿凝聚","实证入内","寒包火证"],"a":1,"e":"热证转寒为邪热耗伤阳气，或过用寒凉损伤正气，阳气衰微而转为寒证，其临床意义在于正气耗伤。"},{"q":"亡阴证的典型表现有","o":["冷汗质稀","肢厥肤冷","呼吸气微","面赤如妆","脉微欲绝"],"a":3,"e":"亡阴为阴液枯涸、虚热内扰，见汗热而黏、肌肤热、面赤、烦躁、脉细数疾；冷汗肢厥、呼吸气微、脉微欲绝属亡阳。"},{"q":"鉴别实寒证与虚寒证主要看","o":["寒重还是热重","脉之迟数","脉之有力无力","舌红还是舌白","肢体痛与不痛"],"a":2,"e":"实寒为寒邪壅盛，脉沉迟有力；虚寒为阳气不足，脉沉迟无力。脉之有力无力是辨别虚实的关键。"},{"q":"下列哪项是太阴病“腹满”的病机","o":["腑气不通，气机壅滞","湿郁化热，气机逆乱","纳运失常，胃失和降","寒湿内生，气机阻滞","水饮不化，气机壅滞"],"a":3,"e":"太阴病属脾虚寒湿，脾阳不振则寒湿内生、气机阻滞，故腹满而吐、食不下、自利益甚；腑气不通之腹满属阳明。"},{"q":"根据五轮学说，眼睑属于","o":["心","肝","脾","肺","肾"],"a":2,"e":"五轮学说以眼睑为肉轮属脾，白睛为气轮属肺，黑睛为风轮属肝，目眦为血轮属心，瞳神为水轮属肾。"},{"q":"以颈部瘿瘤、瘰疬、胸胁、少腹胀满疼痛、走窜不定，舌苔薄白，脉弦为主要表现的证是","o":["肝阴虚证","肝风内动证","肝郁气滞证","寒滞肝脉证","肝胆湿热证"],"a":2,"e":"肝气郁结，气机不畅，故胸胁少腹胀满疼痛、走窜不定；气郁痰凝结于颈部则生瘿瘤瘰疬，脉弦为气滞之征。"},{"q":"下列哪项不属于正常舌象","o":["舌体柔软","舌色淡红","舌质淡嫩","舌苔均匀","薄白而湿润"],"a":2,"e":"正常舌象为淡红舌、薄白苔，舌体柔软、苔面均匀、薄白而润；舌质淡嫩主虚证，属病理性舌象。"},{"q":"下列脉象中，主湿的脉象多为","o":["弱脉","濡脉","弦脉","沉脉","数脉"],"a":1,"e":"濡脉浮细而软，主湿与诸虚，湿邪黏滞、脉道弛缓而见此象；弦脉主痛与饮，沉脉主里，弱脉主气血不足。"},{"q":"腹部肿块，推之不移，痛有定处者为","o":["瘕聚","癥积","食积","鼓胀","痞满"],"a":1,"e":"癥积为腹中肿块固定不移、按之有形、痛有定处，属血瘀；瘕聚则聚散无常、痛无定处，属气滞。"},{"q":"风寒犯肺证咳痰的特点是","o":["干咳少痰","痰稀色白","咳脓血痰","咳痰黄稠","咳痰带血"],"a":1,"e":"风寒犯肺，肺失宣降，津液不化，故咳痰稀薄色白，兼恶寒发热、鼻塞流清涕、苔薄白、脉浮紧。"},{"q":"“寸关尺分候脏腑”理论首见于","o":["《黄帝内经》","《难经》","《脉经》","《濒湖脉学》","《脉诀汇辨》"],"a":0,"e":"寸口分候脏腑源自《黄帝内经》，《难经》倡独取寸口，《脉经》加以厘定，《濒湖脉学》载二十七脉。"},{"q":"寒证一般不起因于","o":["外感寒邪","过食生冷","阳气不足","七情内伤","久病体弱"],"a":3,"e":"寒证多因外感寒邪、过食生冷，或阳气不足、久病体弱而致；七情内伤主要伤及脏腑气机，多从火化而不生寒。"},{"q":"与阳虚关系最密切的舌色是","o":["淡白舌","淡紫舌","红绛舌","淡红舌","青紫舌"],"a":0,"e":"阳虚则气血不能上荣，舌色淡白；淡紫舌主阳虚血瘀，红绛舌主热盛或阴虚，青紫舌主血瘀寒凝。"},{"q":"滑苔的形成机制是","o":["胃津、肾液上潮","寒湿内侵","热盛伤津","湿遏阳气","瘀阻"],"a":1,"e":"滑苔为舌面水液潴留、扪之湿滑，因寒湿内侵、阳气不化，水湿上泛；燥苔则属热盛伤津或阴液亏耗。"},{"q":"耳轮干枯焦黑者多属","o":["麻疹先兆","肾阴亏虚","肾阳不足","肾精亏损","血瘀日久"],"a":3,"e":"耳为肾之窍，肾精亏损则耳失所养，耳轮干枯焦黑，甚则耳薄瘦削；耳轮红肿属肝胆湿热或热毒上攻。"},{"q":"肾精不足证不会出现下列哪项症状","o":["齿松发脱","腰酸膝软","健忘恍惚","耳鸣耳聋","阳强早泄"],"a":4,"e":"肾精不足则生长发育迟缓、齿松发脱、腰膝酸软、健忘耳鸣；阳强早泄属相火妄动、精关不固，非精亏之象。"},{"q":"囟门未闭的小儿温病火邪上攻，可表现为","o":["囟填","囟陷","解颅","巨颅","方颅"],"a":0,"e":"囟门未闭而突起为囟填，多因温病火邪上攻、脑髓有病或颅内水停；囟陷属津亏气弱，解颅为囟门迟闭不合。"},{"q":"按脉时需重按推筋着骨始得的脉象是","o":["沉脉","牢脉","弱脉","伏脉","革脉"],"a":3,"e":"伏脉脉位最深，需重按推筋着骨始得，甚则伏而不见，主邪闭、厥证与痛极；沉脉按之有余，尚不需推筋着骨。"}];
